INSERT INTO "credibility_assessment" VALUES('cred-a8816b2bd40b','l2_finding','sf-ba4f38adf1c9','medium','由 web 端 Chatham House 来源提供实质性细节锚定，叠加多条小红书突发/事实项同向支撑，但小红书项偏薄、缺细节。','{"independence": "1 web + 3 xiaohongshu，跨平台半独立", "quality_density": "web 项信息密度高；xhs 项稀疏/卡片级", "recency": "2025 年谈判周期，时效有效"}',NULL,0,NULL,'active',NULL,'2026-06-29 12:13:31');
