INSERT INTO "credibility_assessment" VALUES('cred-6059d5ea15a1','l2_finding','sf-29c6fb7c6d01','low','单一小红书突发项，仅标题级、无细节，本载荷内无第二来源佐证。','{"independence": "单一来源", "quality_density": "仅标题级", "recency": "较新"}',NULL,0,NULL,'active',NULL,'2026-06-29 12:13:31');
