INSERT INTO "credibility_assessment" VALUES('cred-7326bb376228','l2_finding','sf-272bf447056b','low','单一平台（小红书）的二次评论与用户自整清单，记录了议题传播面但未提供一手数据；清单高赞反映一定转发放大。','{"independence": "同平台、用户二次汇编", "quality_density": "清单/综述，无一手数据", "recency": "较新"}',NULL,0,NULL,'active',NULL,'2026-06-29 12:13:31');
