INSERT INTO "knowledge_change_log" VALUES(83,'l3_claim','sc-02c2a9805a91','*','update','{"id": "sc-02c2a9805a91", "facet": null, "proposition": "Russia''s Q1 GDP contraction of 0.2% does not mean the war economy is broken — the author argues Russia will still grow ~1% this year and Putin can keep funding the war, framing Western think-tank (Kiel Institute) talk of ''structural exhaustion'' as misleading.", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-02c2a9805a91", "source_ref_ids": "[\"src-02c2a9805a91\"]", "verbatim_excerpt": "That 0.2% is misleading. Russia will grow about 1% this year and Putin can keep funding the war — Economist.", "cached_text_hash": "e9cb960d8bebf05da5d8406c44d12012e115c1904b43d0b88413a172e1b3136a", "analysis_note": "Contrarian interpretive take that disputes a Western-think-tank consensus (Kiel ''structural exhaustion''). Author is Tymofiy Mylovanov (economist; president of Kyiv School of Economics, former Ukrainian economy minister) — domain-credentialed. The 1% growth figure is attributed to The Economist, so the supporting data is a secondary citation, not original reporting.", "filter_trace": "{\"independence\": \"One author; numbers rest on a single secondary citation (The Economist) and the counterclaim targets another single institution (Kiel). No independent corroboration presented in-post.\", \"quality_density\": \"High density: specific figures, named sources, falsifiable claim (growth rate, funding capacity).\", \"recency\": \"Time-sensitive macro/geopolitical data (Q1 GDP, 2024 outlook) — decays; annual figures can be revised.\"}", "debate_trace": null, "credibility_id": "cred-a77ebaed6e95", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-02c2a9805a91", "facet": null, "proposition": "Russia''s Q1 GDP contraction of 0.2% does not mean the war economy is broken — the author argues Russia will still grow ~1% this year and Putin can keep funding the war, framing Western think-tank (Kiel Institute) talk of ''structural exhaustion'' as misleading.", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-02c2a9805a91", "source_ref_ids": "[\"src-02c2a9805a91\"]", "verbatim_excerpt": "That 0.2% is misleading. Russia will grow about 1% this year and Putin can keep funding the war — Economist.", "cached_text_hash": "e9cb960d8bebf05da5d8406c44d12012e115c1904b43d0b88413a172e1b3136a", "analysis_note": "Contrarian interpretive take that disputes a Western-think-tank consensus (Kiel ''structural exhaustion''). Author is Tymofiy Mylovanov (economist; president of Kyiv School of Economics, former Ukrainian economy minister) — domain-credentialed. The 1% growth figure is attributed to The Economist, so the supporting data is a secondary citation, not original reporting.", "filter_trace": "{\"independence\": \"One author; numbers rest on a single secondary citation (The Economist) and the counterclaim targets another single institution (Kiel). No independent corroboration presented in-post.\", \"quality_density\": \"High density: specific figures, named sources, falsifiable claim (growth rate, funding capacity).\", \"recency\": \"Time-sensitive macro/geopolitical data (Q1 GDP, 2024 outlook) — decays; annual figures can be revised.\"}", "debate_trace": null, "credibility_id": "cred-b4b835ea3d1f", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 11:48:07',NULL);
