INSERT INTO "knowledge_change_log" VALUES(89,'l3_claim','sc-144db63a9d52','*','update','{"id": "sc-144db63a9d52", "facet": null, "proposition": "乌克兰新一代中程无人机正在瓦解俄罗斯南部后勤补给线，可能打乱俄方攻势节奏；交战形态已转向由无人机覆盖的“灰色地带”，取代传统前线，使机动变得致命、领土得失难以据守。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-144db63a9d52", "source_ref_ids": "[\"src-144db63a9d52\"]", "verbatim_excerpt": "“无人机填充的‘灰色地带’已取代传统前线，使机动致命、领土得失难以据守。”", "cached_text_hash": "a2e208a6b8425e8e16f33e27b5117e12c6b7bfddffa299114dc63559ca5fbd20", "analysis_note": "CNN对乌战场态势的战略性分析报道，核心是无人机对俄后勤的打击效应与战场形态转变（灰色地带化）的判断，含未来推测成分（“可能打乱攻势”）。", "filter_trace": "{\"independence\": \"单源（CNN），需独立源印证后勤受损程度\", \"quality_density\": \"高：含具体地点、武器类型、战场形态判断\", \"recency\": \"2026-06-20，约一周前；地缘冲突信息易过期\"}", "debate_trace": null, "credibility_id": "cred-454bb70b57d9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-144db63a9d52", "facet": null, "proposition": "乌克兰新一代中程无人机正在瓦解俄罗斯南部后勤补给线，可能打乱俄方攻势节奏；交战形态已转向由无人机覆盖的“灰色地带”，取代传统前线，使机动变得致命、领土得失难以据守。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-144db63a9d52", "source_ref_ids": "[\"src-144db63a9d52\"]", "verbatim_excerpt": "“无人机填充的‘灰色地带’已取代传统前线，使机动致命、领土得失难以据守。”", "cached_text_hash": "a2e208a6b8425e8e16f33e27b5117e12c6b7bfddffa299114dc63559ca5fbd20", "analysis_note": "CNN对乌战场态势的战略性分析报道，核心是无人机对俄后勤的打击效应与战场形态转变（灰色地带化）的判断，含未来推测成分（“可能打乱攻势”）。", "filter_trace": "{\"independence\": \"单源（CNN），需独立源印证后勤受损程度\", \"quality_density\": \"高：含具体地点、武器类型、战场形态判断\", \"recency\": \"2026-06-20，约一周前；地缘冲突信息易过期\"}", "debate_trace": null, "credibility_id": "cred-8154db617c8a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "20