INSERT INTO "knowledge_change_log" VALUES(100,'l3_claim','sc-334cc1ca247f','*','update','{"id": "sc-334cc1ca247f", "facet": null, "proposition": "2025年12月,美国起草的乌克兰和平方案要求冻结赫尔松和扎波罗热前线(将两地大片区域划归俄罗斯控制),并要求乌军从其现控制的顿涅茨克部分撤出;泽连斯基就此提出反提案并承认顿巴斯控制是\"最困难的一点\",而特朗普与美方官员称柏林会谈后已接近达成(约90%问题解决)。", "claim_kind": "breaking", "source_kind": "article", "single_source_ref_id": "src-334cc1ca247f", "source_ref_ids": "[\"src-334cc1ca247f\"]", "verbatim_excerpt": "美国草案提议冻结赫尔松和扎波罗热前线……并要求基辅部队从其现控制的顿涅茨克部分撤出", "cached_text_hash": "a1afa4de0a7e06950515840767bb6d2c892e38ea9f68be07e7d62273c17f988e", "analysis_note": "France 24 对美乌和平方案草案与各方立场的 attributed 报道:核心主张来自泽连斯基的公开表态 + 美方官员陈述,属地缘政治快变议题中的点位快照。", "filter_trace": "{\"independence\": \"单一主流媒体一手报道,来源归因于具名官方,但本 unit 内仅此一源,独立性中等\", \"quality_density\": \"高:具体地理、数字与机构细节,可证伪\", \"recency\": \"地缘政治快变议题,2025-12 的谈判状态至 2026-06 可能已显著变动,时效衰减风险需在 aggregate/synthesize 阶段以更新来源印证\"}", "debate_trace": null, "credibility_id": "cred-d8f85fd52999", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-334cc1ca247f", "facet": null, "proposition": "2025年12月,美国起草的乌克兰和平方案要求冻结赫尔松和扎波罗热前线(将两地大片区域划归俄罗斯控制),并要求乌军从其现控制的顿涅茨克部分撤出;泽连斯基就此提出反提案并承认顿巴斯控制是\"最困难的一点\",而特朗普与美方官员称柏林会谈后已接近达成(约90%问题解决)。", "claim_kind": "breaking", "source_kind": "article", "single_source_ref_id": "src-334cc1ca247f", "source_ref_ids": "[\"src-334cc1ca247f\"]", "verbatim_excerpt": "美国草案提议冻结赫尔松和扎波罗热前线……并要求基辅部队从其现控制的顿涅茨克部分撤出", "cached_text_hash": "a1afa4de0a7e06950515840767bb6d2c892e38ea9f68be07e7d62273c17f988e", "analysis_note": "France 24 对美乌和平方案草案与各方立场的 attributed 报道:核心主张来自泽连斯基的公开表态 + 美方官员陈述,属地缘政治快变议题中的点位快照。", "filter_trace": "{\"independence\": \"单一主流媒体一手报道,来源归因于具名官方,但本 unit 内仅此一源,独立性中等\", \"quality_density\": \"高:具体地理、数字与机构细节,可证伪\", \"recency\": \"地缘政治快变议题,2025-12 的谈判状态至 2026-06 可能已显著变动,时效衰减风险需在 aggregate/synthesize 阶段以更新来源印证\"}", "debate_trace": null, "credibility_id": "cred-ded029c53372", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(101,'l3_claim','sc-3406f384a8d2','*','update','{"id": "sc-3406f384a8d2", "facet": null, "proposition": "小红书博主@袁晨曦发布了题为《浅谈被制裁前后的俄罗斯》的笔记（点赞60、评论9），就俄罗斯在制裁前后的状况展开个人评述；但该笔记正文未抓取，仅留存卡片级元数据，无实质性论点可供蒸馏。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-3406f384a8d2", "source_ref_ids": "[\"src-3406f384a8d2\"]", "verbatim_excerpt": "浅谈被制裁前后的俄罗斯（作者:@袁晨曦 | 点赞60 评论9）", "cached_text_hash": "e298fdd60ae5224aea071824c11c5670e0ba5721954eae9a131839ded7c998a4", "analysis_note": "卡片级证据：正文因规避小红书风控未抓取，xsec_token已留存可后续追溯/补抓。当前仅凭标题与互动数，无法判断作者对''制裁前后俄罗斯''的具体主张或立场，实质信息密度近乎为零。建议在下一轮经 xiaohongshu-mcp 补抓正文后再升格为实质 L3，本期仅作为''该话题在小红书存在公开讨论''的存在性信号留存。", "filter_trace": "{\"independence\": \"单条小红书笔记，无任何独立来源印证\", \"quality_density\": \"极低——仅标题与点赞/评论计数，正文缺失，无可证伪细节\", \"recency\": \"无明确发布时间戳，时效衰减无法评估\"}", "debate_trace": null, "credibility_id": "cred-0de662cebf83", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-3406f384a8d2", "facet": null, "proposition": "小红书博主@袁晨曦发布了题为《浅谈被制裁前后的俄罗斯》的笔记（点赞60、评论9），就俄罗斯在制裁前后的状况展开个人评述；但该笔记正文未抓取，仅留存卡片级元数据，无实质性论点可供蒸馏。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-3406f384a8d2", "source_ref_ids": "[\"src-3406f384a8d2\"]", "verbatim_excerpt": "浅谈被制裁前后的俄罗斯（作者:@袁晨曦 | 点赞60 评论9）", "cached_text_hash": "e298fdd60ae5224aea071824c11c5670e0ba5721954eae9a131839ded7c998a4", "analysis_note": "卡片级证据：正文因规避小红书风控未抓取，xsec_token已留存可后续追溯/补抓。当前仅凭标题与互动数，无法判断作者对''制裁前后俄罗斯''的具体主张或立场，实质信息密度近乎为零。建议在下一轮经 xiaohongshu-mcp 补抓正文后再升格为实质 L3，本期仅作为''该话题在小红书存在公开讨论''的存在性信号留存。", "filter_trace": "{\"independence\": \"单条小红书笔记，无任何独立来源印证\", \"quality_density\": \"极低——仅标题与点赞/评论计数，正文缺失，无可证伪细节\", \"recency\": \"无明确发布时间戳，时效衰减无法评估\"}", "debate_trace": null, "credibility_id": "cred-21afc61bba4d", "pare