INSERT INTO "knowledge_change_log" VALUES(102,'l3_claim','sc-35b5b46bb66f','*','update','{"id": "sc-35b5b46bb66f", "facet": null, "proposition": "2025年西方能源制裁导致俄罗斯石油收入同比下降约20%，乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队与替代供应链承压。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-35b5b46bb66f", "source_ref_ids": "[\"src-35b5b46bb66f\"]", "verbatim_excerpt": "俄罗斯石油收入：2025年因制裁石油收入下降约20%。乌拉尔原油相对布伦特折价扩大至每桶逾24美元。", "cached_text_hash": "7a6ab35dfbc77ef8a4acb2864e8ec802647f140f26d16fa20006e6e6be0b5c80", "analysis_note": "数据为FT援引，叠加Riddle Russia与GIS分析，反映制裁对俄财政的累积杀伤与价格上限机制效果。", "filter_trace": "{\"independence\": \"聚合FT、Riddle Russia、GIS三方观点，但均收敛于同一制裁叙事，独立性中等\", \"quality_density\": \"高密度：含具体收入降幅与折价数值，可证伪\", \"recency\": \"2025年数据，时效性强、未过期\"}", "debate_trace": null, "credibility_id": "cred-320dec89d56a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-35b5b46bb66f", "facet": null, "proposition": "2025年西方能源制裁导致俄罗斯石油收入同比下降约20%，乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队与替代供应链承压。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-35b5b46bb66f", "source_ref_ids": "[\"src-35b5b46bb66f\"]", "verbatim_excerpt": "俄罗斯石油收入：2025年因制裁石油收入下降约20%。乌拉尔原油相对布伦特折价扩大至每桶逾24美元。", "cached_text_hash": "7a6ab35dfbc77ef8a4acb2864e8ec802647f140f26d16fa20006e6e6be0b5c80", "analysis_note": "数据为FT援引，叠加Riddle Russia与GIS分析，反映制裁对俄财政的累积杀伤与价格上限机制效果。", "filter_trace": "{\"independence\": \"聚合FT、Riddle Russia、GIS三方观点，但均收敛于同一制裁叙事，独立性中等\", \"quality_density\": \"高密度：含具体收入降幅与折价数值，可证伪\", \"recency\": \"2025年数据，时效性强、未过期\"}", "debate_trace": null, "credibility_id": "cred-163d83c26822", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48: