INSERT INTO "knowledge_change_log" VALUES(103,'l3_claim','sc-3a6bff93c0af','*','update','{"id": "sc-3a6bff93c0af", "facet": null, "proposition": "一名 X 用户断言俄军已实际占领 Kostyantynivka 与 Lyman，并将随后包围 Slovyansk 与 Kramatorsk、从而控制整个顿巴斯，同时声称西方主流媒体关于乌克兰以无人机攻势击败俄罗斯的报道系捏造叙事。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-3a6bff93c0af", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "verbatim_excerpt": "the capture of Kostyantynivka and Lyman is a fact.", "cached_text_hash": "61516246129f260c8aa8161f4e318694308c4816b326fa0114a3d3986698fc11", "analysis_note": "单个未标明资质的社媒账号对战局进展作出的带强倾向性（pro-Russia）解读：将争议性领土占领陈述为''事实''，并以''捏造叙事''否定相反报道。地名具体（信息密度尚可），但无任何独立证据或来源支撑，且属快速过期的战场断言，需独立多源印证后方可采信。", "filter_trace": "{\"independence\": \"仅单条个人推文，post 内无任何独立来源佐证其领土占领或''媒体捏造''之断言。\", \"quality_density\": \"提及具体地名（Kostyantynivka/Lyman/Slovyansk/Kramatorsk）有一定密度，但无出处、无可证伪细节，''fabricated narrative''式措辞削弱质量。\", \"recency\": \"为快速移动的战场进展断言，属高 recency_decay 类型，信息极易随战线变化而过期。\"}", "debate_trace": null, "credibility_id": "cred-793375d58b1e", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-3a6bff93c0af", "facet": null, "proposition": "一名 X 用户断言俄军已实际占领 Kostyantynivka 与 Lyman，并将随后包围 Slovyansk 与 Kramatorsk、从而控制整个顿巴斯，同时声称西方主流媒体关于乌克兰以无人机攻势击败俄罗斯的报道系捏造叙事。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-3a6bff93c0af", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "verbatim_excerpt": "the capture of Kostyantynivka and Lyman is a fact.", "cached_text_hash": "61516246129f260c8aa8161f4e318694308c4816b326fa0114a3d3986698fc11", "analysis_note": "单个未标明资质的社媒账号对战局进展作出的带强倾向性（pro-Russia）解读：将争议性领土占领陈述为''事实''，并以''捏造叙事''否定相反报道。地名具体（信息密度尚可），但无任何独立证据或来源支撑，且属快速过期的战场断言，需独立多源印证后方可采信。", "filter_trace": "{\"independence\": \"仅单条个人推文，post 内无任何独立来源佐证其领土占领或''媒体捏造''之断言。\", \"quality_density\": \"提及具体地名（Kostyantynivka/Lyman/Slovyansk/Kramatorsk）有一定密度，但无出处、无可证伪细节，''fabricated narrative''式措辞削弱质量。\", \"recency\": \"为快速移动的战场进展断言，属高 recency_decay 类型，信息极易随战线变化而过期。\"}", "debate_trace": null, "credibility_id": "cred-b9207addb970", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 11:48:07',NULL);
