INSERT INTO "knowledge_change_log" VALUES(109,'l3_claim','sc-43f57fedfa87','*','update','{"id": "sc-43f57fedfa87", "facet": null, "proposition": "乌克兰F-16战机曾连续三周以上无法获得美制导弹，致使其难以击落俄方无人机与导弹，暴露出西方对乌军援供应链存在明显的断档与脆弱性", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-43f57fedfa87", "source_ref_ids": "[\"src-43f57fedfa87\"]", "verbatim_excerpt": "乌克兰F-16战机长达三周以上缺乏美制导弹，无法击落俄无人机和导弹，暴露西方军援供应链的脆弱性与断档。", "cached_text_hash": "f3ad109d4629382de39dd84efa52a6d41d8b887ffec0b4806a35b1a45d26ef49", "analysis_note": "路透社作为一级通讯社报道的可验证军事事实（具体武器平台、缺弹时长）。供应链脆弱性判断带分析成分，但建立在缺弹事实之上。", "filter_trace": "{\"independence\": \"单一来源（路透社），但路透社为一级独立通讯社，非回音室转发\", \"quality_density\": \"高密度：点名F-16/爱国者等具体平台、缺弹时长(三周以上)、可证伪\", \"recency\": \"2026-03发布，距今约3个月；快变军事主题，导弹供应状况可能已变化\"}", "debate_trace": null, "credibility_id": "cred-99c4248c5cc9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-43f57fedfa87", "facet": null, "proposition": "乌克兰F-16战机曾连续三周以上无法获得美制导弹，致使其难以击落俄方无人机与导弹，暴露出西方对乌军援供应链存在明显的断档与脆弱性", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-43f57fedfa87", "source_ref_ids": "[\"src-43f57fedfa87\"]", "verbatim_excerpt": "乌克兰F-16战机长达三周以上缺乏美制导弹，无法击落俄无人机和导弹，暴露西方军援供应链的脆弱性与断档。", "cached_text_hash": "f3ad109d4629382de39dd84efa52a6d41d8b887ffec0b4806a35b1a45d26ef49", "analysis_note": "路透社作为一级通讯社报道的可验证军事事实（具体武器平台、缺弹时长）。供应链脆弱性判断带分析成分，但建立在缺弹事实之上。", "filter_trace": "{\"independence\": \"单一来源（路透社），但路透社为一级独立通讯社，非回音室转发\", \"quality_density\": \"高密度：点名F-16/爱国者等具体平台、缺弹时长(三周以上)、可证伪\", \"recency\": \"2026-03发布，距今约3个月；快变军事主题，导弹供应状况可能已变化\"}", "debate_trace": null, "credibility_id": "cred-328bf93a02b4", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-0