INSERT INTO "knowledge_change_log" VALUES(112,'l3_claim','sc-4e893ca84bd7','*','update','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_density\": \"密度较高：点名系统名称、武器型号（M2 Browning）与目标（Shahed/Geran），但无影像/官方佐证\", \"recency\": \"俄乌战事属快变主题，部署消息时效性强\"}", "debate_trace": null, "credibility_id": "cred-f86c1b4f78de", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_density\": \"密度较高：点名系统名称、武器型号（M2 Browning）与目标（Shahed/Geran），但无影像/官方佐证\", \"recency\": \"俄乌战事属快变主题，部署消息时效性强\"}", "debate_trace": null, "credibility_id": "cred-55038b6e4502", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(113,'l3_claim','sc-4f82a42b4c15','*','update','{"id": "sc-4f82a42b4c15", "facet": null, "proposition": "An anonymous X user expresses skepticism about an unspecified (likely drone/anti-drone) system, arguing it must be proven in operation, is itself vulnerable to drone attack, and that automation risks friendly-fire incidents.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-4f82a42b4c15", "source_ref_ids": "[\"src-4f82a42b4c15\"]", "verbatim_excerpt": "Interesting, but need to see it in operation. It can, itself, get attacked by drones, and if automated, could result in friendly-fire.", "cached_text_hash": "29b6c08c747fb9d1760d9fac722f5835ad5a7d89f87f4a5b5ed954fa2aa7b83b", "analysis_note": "The post''s referent (which system) is not captured in this single unit; it is a speculative reaction, not a verifiable claim. Author handle (''MAGAtard'') is an anonymous/pseudonymous account with no institutional standing.", "filter_trace": "{\"independence\": \"Single pseudonymous account; no independent sources or corroboration cited.\", \"quality_density\": \"Short speculative reaction — no data, evidence, or specifics, pure conjecture.\", \"recency\": \"Concern is timeless (not time-bound); recency is not the binding constraint here.\"}", "debate_trace": null, "credibility_id": "cred-76e5b73fb867", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-4f82a42b4c15", "facet": null, "proposition": "An anonymous X user expresses skepticism about an unspecified (likely drone/anti-drone) system, arguing it must be proven in operation, is itself vulnerable to drone attack, and that automation risks friendly-fire incidents.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-4f82a42b4c15", "source_ref_ids": "[\"src-4f82a42b4c15\"]", "verbatim_excerpt": "Interesting, but need to see it in operation. It can, itself, get attacked by drones, and if automated, could result in friendly-fire.", "cached_text_hash": "29b6c08c747fb9d1760d9fac722f5835ad5a7d89f87f4a5b5ed954fa2aa7b83b", "analysis_note": "The post''s referent (which system) is not captured in this single unit; it is a speculative reaction, not a verifiable claim. Author handle (''MAGAtard'') is an anonymous/pseudonymous account with no institutional standing.", "filter_trace": "{\"independence\": \"Single pseudonymous account; no independent sources or corroboration cited.\", \"quality_density\": \"Short speculative reaction — no data, evidence, or specifics, pure conjecture.\", \"recency\": \"Concern is timeless (not time-bound); recency is not the binding constraint here.\"}", "debate_trace": null, "credibility_id": "cred-a47b819e44cf", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=opinion facet=None','condense-distill','2026-06-29 11:48:07',NULL);
