INSERT INTO "knowledge_change_log" VALUES(120,'l3_claim','sc-65378bb4a0ce','*','update','{"id": "sc-65378bb4a0ce", "facet": null, "proposition": "普京据称提出了最新一轮停战条件，且俄罗斯方面据称再次做出让步。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-65378bb4a0ce", "source_ref_ids": "[\"src-65378bb4a0ce\"]", "verbatim_excerpt": "普京开出最新停战条件，俄罗斯再次让步", "cached_text_hash": "750e535fda22bc986f83a15a35a3421de034277330ce77b97e1793036d04058a", "analysis_note": "卡片级证据：正文未抓取以规避风控，本条主张仅源自标题，无具体停战条件内容或佐证，信息密度极低，可信度受限。", "filter_trace": "{\"independence\": \"单一聚合账号「1点知」，疑似二次转发，无原始一手来源（如普京/Kremlin 声明）入档。\", \"quality_density\": \"极低——仅有标题，无任何停战条件或让步的具体内容，无可证伪细节。\", \"recency\": \"标题含「最新」但未留存发布日期；停战谈判类快变信息易过期。\"}", "debate_trace": null, "credibility_id": "cred-0cac75fd0346", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-65378bb4a0ce", "facet": null, "proposition": "普京据称提出了最新一轮停战条件，且俄罗斯方面据称再次做出让步。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-65378bb4a0ce", "source_ref_ids": "[\"src-65378bb4a0ce\"]", "verbatim_excerpt": "普京开出最新停战条件，俄罗斯再次让步", "cached_text_hash": "750e535fda22bc986f83a15a35a3421de034277330ce77b97e1793036d04058a", "analysis_note": "卡片级证据：正文未抓取以规避风控，本条主张仅源自标题，无具体停战条件内容或佐证，信息密度极低，可信度受限。", "filter_trace": "{\"independence\": \"单一聚合账号「1点知」，疑似二次转发，无原始一手来源（如普京/Kremlin 声明）入档。\", \"quality_density\": \"极低——仅有标题，无任何停战条件或让步的具体内容，无可证伪细节。\", \"recency\": \"标题含「最新」但未留存发布日期；停战谈判类快变信息易过期。\"}", "debate_trace": null, "credibility_id": "cred-9c64bdccd91b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(121,'l3_claim','sc-6a4598c1b723','*','update','{"id": "sc-6a4598c1b723", "facet": null, "proposition": "乌克兰总统泽连斯基向俄罗斯总统普京发出一封公开信。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-6a4598c1b723", "source_ref_ids": "[\"src-6a4598c1b723\"]", "verbatim_excerpt": "泽连斯基向普京发出公开信", "cached_text_hash": "9eed1c68f1039c6bfe852ebb828d59f64b31b2e91a2584c7aa0209d0eacd7e8a", "analysis_note": "仅卡片级证据（标题+媒体官方账号+互动数据：点赞337/评论10），正文未抓取以规避风控，无公开信的具体内容、发出时间或核心诉求，需后续抓取或跨源交叉印证核实细节。", "filter_trace": "{\"independence\": \"单条卡片级媒体帖，未见独立印证，暂以单源处理；corroboration 需在 aggregate 阶段由其他独立来源补足。\", \"quality_density\": \"低——仅标题与互动数据，无正文细节、无公开信内容、无时间地点等可证伪要素。\", \"recency\": \"快变地缘主题，来源易过期；卡片未含明确发布日期，时效衰减需结合后续时间线判断。\"}", "debate_trace": null, "credibility_id": "cred-c312e516a3cb", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-6a4598c1b723", "facet": null, "proposition": "乌克兰总统泽连斯基向俄罗斯总统普京发出一封公开信。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-6a4598c1b723", "source_ref_ids": "[\"src-6a4598c1b723\"]", "verbatim_excerpt": "泽连斯基向普京发出公开信", "cached_text_hash": "9eed1c68f1039c6bfe852ebb828d59f64b31b2e91a2584c7aa0209d0eacd7e8a", "analysis_note": "仅卡片级证据（标题+媒体官方账号+互动数据：点赞337/评论10），正文未抓取以规避风控，无公开信的具体内容、发出时间或核心诉求，需后续抓取或跨源交叉印证核实细节。", "filter_trace": "{\"independence\": \"单条卡片级媒体帖，未见独立印证，暂以单源处理；corroboration 需在 aggregate 阶段由其他独立来源补足。\", \"quality_density\": \"低——仅标题与互动数据，无正文细节、无公开信内容、无时间地点等可证伪要素。\", \"recency\": \"快变地缘主题，来源易过期；卡片未含明确发布日期，时效衰减需结合后续时间线判断。\"}", "debate_trace": null, "credibility_id": "cred-975f3a51a03c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-