INSERT INTO "knowledge_change_log" VALUES(126,'l3_claim','sc-804693cbd100','*','update','{"id": "sc-804693cbd100", "facet": null, "proposition": "乌克兰经济在持续约两年的俄乌战争后仍未发生全面崩溃（原笔记以此为题展开“为什么”分析）", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-804693cbd100", "source_ref_ids": "[\"src-804693cbd100\"]", "verbatim_excerpt": "打了两年，乌克兰经济为什么没垮？", "cached_text_hash": "bd7911f24f4532e58d468cf5a8d1fd67ab1dfb6446de829eb6482393cfe7f593", "analysis_note": "正文未抓取（规避风控），仅留存标题与卡片级互动数据（点赞20、评论159），故只能蒸馏出标题级主张，无法核实原笔记给出的具体支撑论据；如需论证需回抓全文（xsec_token 已留存可追溯）。", "filter_trace": "{\"independence\": \"单一作者单条小红书笔记，无交叉来源；正文缺失无法判断其论据独立性。\", \"quality_density\": \"仅标题+互动数据，正文未抓取，主张缺乏可证伪细节，信息密度低。\", \"recency\": \"标题“打了两年”指向约 2024 年，属快变地缘政治主题，时效性随时间衰减。\"}", "debate_trace": null, "credibility_id": "cred-36be1614de0c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-804693cbd100", "facet": null, "proposition": "乌克兰经济在持续约两年的俄乌战争后仍未发生全面崩溃（原笔记以此为题展开“为什么”分析）", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-804693cbd100", "source_ref_ids": "[\"src-804693cbd100\"]", "verbatim_excerpt": "打了两年，乌克兰经济为什么没垮？", "cached_text_hash": "bd7911f24f4532e58d468cf5a8d1fd67ab1dfb6446de829eb6482393cfe7f593", "analysis_note": "正文未抓取（规避风控），仅留存标题与卡片级互动数据（点赞20、评论159），故只能蒸馏出标题级主张，无法核实原笔记给出的具体支撑论据；如需论证需回抓全文（xsec_token 已留存可追溯）。", "filter_trace": "{\"independence\": \"单一作者单条小红书笔记，无交叉来源；正文缺失无法判断其论据独立性。\", \"quality_density\": \"仅标题+互动数据，正文未抓取，主张缺乏可证伪细节，信息密度低。\", \"recency\": \"标题“打了两年”指向约 2024 年，属快变地缘政治主题，时效性随时间衰减。\"}", "debate_trace": null, "credibility_id": "cred-7d02fea22c57", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at"