INSERT INTO "knowledge_change_log" VALUES(131,'l3_claim','sc-887e067cdfeb','*','update','{"id": "sc-887e067cdfeb", "facet": null, "proposition": "某中国无人机卖家(@UAV_drones)声称一名乌克兰买家收到其无人机产品并表示称赞，作为产品营销背书呈现", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-887e067cdfeb", "source_ref_ids": "[\"src-887e067cdfeb\"]", "verbatim_excerpt": "乌克兰美女收到我们的无人机表示很赞！", "cached_text_hash": "1a69167db0d295f3249592343ecb298f460d76f45eb32cb8a2e552c226256966", "analysis_note": "卡片级证据：笔记正文未抓取(规避风控)，仅留标题、作者与互动数(点赞463/评论466)。所称交易与赞语无法核实；来源为卖方自宣、利益相关。若用于俄乌战争主题，至多作为''中国民用无人机经商业渠道流入乌克兰''方向的弱信号，须独立来源印证。", "filter_trace": "{\"independence\": \"单一来源，且来自卖方账号自身营销，无任何独立第三方证实所称交易或好评\", \"quality_density\": \"低——正文未抓取，仅剩标题与互动计数，无可证伪细节(具体买家/机型/时间/地点)\", \"recency\": \"发布时间未留存，时效性无法判断\"}", "debate_trace": null, "credibility_id": "cred-26b414a95d5b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-887e067cdfeb", "facet": null, "proposition": "某中国无人机卖家(@UAV_drones)声称一名乌克兰买家收到其无人机产品并表示称赞，作为产品营销背书呈现", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-887e067cdfeb", "source_ref_ids": "[\"src-887e067cdfeb\"]", "verbatim_excerpt": "乌克兰美女收到我们的无人机表示很赞！", "cached_text_hash": "1a69167db0d295f3249592343ecb298f460d76f45eb32cb8a2e552c226256966", "analysis_note": "卡片级证据：笔记正文未抓取(规避风控)，仅留标题、作者与互动数(点赞463/评论466)。所称交易与赞语无法核实；来源为卖方自宣、利益相关。若用于俄乌战争主题，至多作为''中国民用无人机经商业渠道流入乌克兰''方向的弱信号，须独立来源印证。", "filter_trace": "{\"independence\": \"单一来源，且来自卖方账号自身营销，无任何独立第三方证实所称交易或好评\", \"quality_density\": \"低——正文未抓取，仅剩标题与互动计数，无可证伪细节(具体买家/机型/时间/地点)\", \"recency\": \"发布时间未留存，时效性无法判断\"}", "debate_trace": null, "credibility_id": "cred-f60799e3d45b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "cr