INSERT INTO "knowledge_change_log" VALUES(136,'l3_claim','sc-90ce42415df6','*','update','{"id": "sc-90ce42415df6", "facet": null, "proposition": "莫斯科遭遇了乌克兰发起的大规模无人机袭击。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-90ce42415df6", "source_ref_ids": "[\"src-90ce42415df6\"]", "verbatim_excerpt": "莫斯科遭遇乌克兰大规模无人机袭击", "cached_text_hash": "36aed7b3b25c9663956d41be09075acb718a489f700e0b4aa5b1be63991f6a2d", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅留标题与互动数据（221赞/31评），无具体时间、规模、战果或伤亡等可证伪细节；命题系基于标题蒸馏，信息密度受限，需后续多源印证后再决定是否纳入 L2。", "filter_trace": "{\"independence\": \"单一平台单一笔记，无跨源印证\", \"quality_density\": \"低——仅卡片标题与互动数据，缺时间/规模/伤亡等具体细节\", \"recency\": \"无明确发布时间戳，属快变地缘主题，易过期\"}", "debate_trace": null, "credibility_id": "cred-eba163600e59", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-90ce42415df6", "facet": null, "proposition": "莫斯科遭遇了乌克兰发起的大规模无人机袭击。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-90ce42415df6", "source_ref_ids": "[\"src-90ce42415df6\"]", "verbatim_excerpt": "莫斯科遭遇乌克兰大规模无人机袭击", "cached_text_hash": "36aed7b3b25c9663956d41be09075acb718a489f700e0b4aa5b1be63991f6a2d", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅留标题与互动数据（221赞/31评），无具体时间、规模、战果或伤亡等可证伪细节；命题系基于标题蒸馏，信息密度受限，需后续多源印证后再决定是否纳入 L2。", "filter_trace": "{\"independence\": \"单一平台单一笔记，无跨源印证\", \"quality_density\": \"低——仅卡片标题与互动数据，缺时间/规模/伤亡等具体细节\", \"recency\": \"无明确发布时间戳，属快变地缘主题，易过期\"}", "debate_trace": null, "credibility_id": "cred-84cb628f56ea", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2