INSERT INTO "knowledge_change_log" VALUES(140,'l3_claim','sc-989926319f5e','*','update','{"id": "sc-989926319f5e", "facet": null, "proposition": "The author argues Europe''s economic decline — industry leaving, innovation stalling, investment fleeing — is self-inflicted, caused by the EU prioritizing moral posturing and ''setting the right example'' on policies that no other country (e.g., China) followed.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-989926319f5e", "source_ref_ids": "[\"src-989926319f5e\"]", "verbatim_excerpt": "All because the EU wanted to be morally superior and give ''the right example'' which absolutely nobody followed.", "cached_text_hash": "b33f95203e7ebf3e7056e83fd6e4344d1a25cd7621cc201c86fb39268b51cde8", "analysis_note": "单条 X 推文，作者把欧洲经济衰退归因于欧盟的道德姿态性政策。属个人评论，正文截断（''You think China and other countries'' 未完），未提供数据或具体政策例证；归因是断言式因果，非可证伪证据。", "filter_trace": "{\"independence\": \"单条个人推文，无独立来源印证其因果主张\", \"quality_density\": \"空泛口号式表达，缺乏细节与可证伪数据，正文尚被截断\", \"recency\": \"无明确日期，但对快变地缘经济话题而言单一观点本身时效意义有限\"}", "debate_trace": null, "credibility_id": "cred-8c85bc6aa6e5", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-989926319f5e", "facet": null, "proposition": "The author argues Europe''s economic decline — industry leaving, innovation stalling, investment fleeing — is self-inflicted, caused by the EU prioritizing moral posturing and ''setting the right example'' on policies that no other country (e.g., China) followed.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-989926319f5e", "source_ref_ids": "[\"src-989926319f5e\"]", "verbatim_excerpt": "All because the EU wanted to be morally superior and give ''the right example'' which absolutely nobody followed.", "cached_text_hash": "b33f95203e7ebf3e7056e83fd6e4344d1a25cd7621cc201c86fb39268b51cde8", "analysis_note": "单条 X 推文，作者把欧洲经济衰退归因于欧盟的道德姿态性政策。属个人评论，正文截断（''You think China and other countries'' 未完），未提供数据或具体政策例证；归因是断言式因果，非可证伪证据。", "filter_trace": "{\"independence\": \"单条个人推文，无独立来源印证其因果主张\", \"quality_density\": \"空泛口号式表达，缺乏细节与可证伪数据，正文尚被截断\", \"recency\": \"无明确日期，但对快变地缘经济话题而言单一观点本身时效意义有限\"}", "debate_trace": null, "credibility_id": "cred-88a6c0d671cd", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=opinion facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(141,'l3_claim','sc-a5385c09a477','*','update','{"id": "sc-a5385c09a477", "facet": null, "proposition": "俄控乌克兰领土份额于2022年春季达到峰值(约25-27%),经2022年哈尔科夫/赫尔松反攻后回落,至2025年秋至2026年2月(开战4周年)稳定在约20%(低于2022年秋水平),且近期俄军推进明显放缓(最近测量周期推进同比下降46%)。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-a5385c09a477", "source_ref_ids": "[\"src-a5385c09a477\"]", "verbatim_excerpt": "至2025年秋季俄军控制约20%乌克兰领土——低于2022年秋季水平。", "cached_text_hash": "fbe8fadb6225f73dd905524bac70bb7660ca515c68d5edfbb12b16e7988c8d50", "analysis_note": "以量化时间线形式呈现领土控制轨迹:峰值→反攻回落→长期僵持在~20%,并给出近期推进衰减指标,可作为衡量战线动态的基线数据。百分比本身为估算,不同追踪机构(如ISW)数值或有出入。", "filter_trace": "{\"independence\": \"单一来源(PBS聚合报道),未见多平台独立交叉;但PBS为可信赖主流媒体。\", \"quality_density\": \"高:含具体百分比(25-27%/20%)、日期(2022-11、2025秋、2026-02)及推进量化指标(123平方英里、-46%),可证伪。\", \"recency\": \"时效良好:数据延伸至2025秋/2026年2月,对快变地缘主题仍有效;但战线持续变化,数值为快照。\"}", "debate_trace": null, "credibility_id": "cred-f065d7b2907f", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-a5385c09a477", "facet": null, "proposition": "俄控乌克兰领土份额于2022年春季达到峰值(约25-27%),经2022年哈尔科夫/赫尔松反攻后回落,至2025年秋至2026年2月(开战4周年)稳定在约20%(低于2022年秋水平),且近期俄军推进明显放缓(最近测量周期推进同比下降46%)。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-a5385c09a477", "source_ref_ids": "[\"src-a5385c09a477\"]", "verbatim_excerpt": "至2025年秋季俄军控制约20%乌克兰领土——低于2022年秋季水平。", "cached_text_hash": "fbe8fadb6225f73dd905524bac70bb7660ca515c68d5edfbb12b16e7988c8d50", "analysis_note": "以量化时间线形式呈现领土控制轨迹:峰值→反攻回落→长期僵持在~20%,并给出近期推进衰减指标,可作为衡量战线动态的基线数据。百分比本身为估算,不同追踪机构(如ISW)数值或有出入。", "filter_trace": "{\"independence\": \"单一来源(PBS聚合报道),未见多平台独立交叉;但PBS为可信赖主流媒体。\", \"quality_density\": \"高:含具体百分比(25-27%/20%)、日期(2022-11、2025秋、2026-02)及推进量化指标(123平方英里、-46%),可证伪。\", \"recency\": \"时效良好:数据延伸至2025秋/2026年2月,对快变地缘主题仍有效;但战线持续变化,数值为快照。\"}", "debate_trace": null, "credibility_id": "cred-ece9dd059b22", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=data facet=None','condense-distill','2026-06-29 11:48:07',NULL);
