INSERT INTO "knowledge_change_log" VALUES(155,'l3_claim','sc-bdb72a69a328','*','update','{"id": "sc-bdb72a69a328", "facet": null, "proposition": "俄罗斯卢布走弱部分对冲了该国石油生产商因 Urals 原油价格下跌（波罗的海与黑海港口约 $50/桶，较此前跌约 50%）而承受的收入压力，但远不足以完全弥补跌幅。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-bdb72a69a328", "source_ref_ids": "[\"src-bdb72a69a328\"]", "verbatim_excerpt": "Urals is likely trading around $50/bbl in Russia''s Baltic and Black Sea ports, down 50% from", "cached_text_hash": "9d7095045d6eb82da255161eab8809ab1d762a079e1c9731932b08d8109f8e00", "analysis_note": "来源为专注于俄油气领域的监测账号，给出了可证伪的量化判断（Urals≈$50/桶、较此前跌约 50%）；属单源分析，数值部分尚需其他独立报价源印证。", "filter_trace": "{\"independence\": \"单一 X 账号，无第二独立来源佐证\", \"quality_density\": \"含具体价格($50/bbl)与跌幅(≈50%)，可证伪\", \"recency\": \"推文未标日期，卢布/油价属快变变量，可能已过期\"}", "debate_trace": null, "credibility_id": "cred-79be38134203", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-bdb72a69a328", "facet": null, "proposition": "俄罗斯卢布走弱部分对冲了该国石油生产商因 Urals 原油价格下跌（波罗的海与黑海港口约 $50/桶，较此前跌约 50%）而承受的收入压力，但远不足以完全弥补跌幅。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-bdb72a69a328", "source_ref_ids": "[\"src-bdb72a69a328\"]", "verbatim_excerpt": "Urals is likely trading around $50/bbl in Russia''s Baltic and Black Sea ports, down 50% from", "cached_text_hash": "9d7095045d6eb82da255161eab8809ab1d762a079e1c9731932b08d8109f8e00", "analysis_note": "来源为专注于俄油气领域的监测账号，给出了可证伪的量化判断（Urals≈$50/桶、较此前跌约 50%）；属单源分析，数值部分尚需其他独立报价源印证。", "filter_trace": "{\"independence\": \"单一 X 账号，无第二独立来源佐证\", \"quality_density\": \"含具体价格($50/bbl)与跌幅(≈50%)，可证伪\", \"recency\": \"推文未标日期，卢布/油价属快变变量，可能已过期\"}", "debate_trace": null, "credibility_id": "cred-4c11afa39afd", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(156,'l3_claim','sc-c00527967443','*','update','{"id": "sc-c00527967443", "facet": null, "proposition": "完全切断美国军事与情报援助将严重削弱乌克兰的对俄作战能力，凸显其对西方支持的长期依赖；兵力与可持续性是乌克兰长期存续的关键问题。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-c00527967443", "source_ref_ids": "[\"src-c00527967443\"]", "verbatim_excerpt": "美国军事与情报援助的完全切断将严重损害乌克兰对俄作战能力……兵力与可持续性是长期存续的关键问题。", "cached_text_hash": "c746165f581aa29e9021afb47b770b10967302db73b1a8a6e1a76eabb4550b67", "analysis_note": "CSIS（战略与国际研究中心）机构分析，属对假想场景的前瞻性研判；印证需留待 L2 跨源完成", "filter_trace": "{\"independence\": \"单一机构观点（L3 单源，印证留待 L2 跨源）\", \"quality_density\": \"高：来源为 CSIS，论点具体、可证伪、有机构背书\", \"recency\": \"地缘快变主题，原文未含明确日期，存在时效衰减风险\"}", "debate_trace": null, "credibility_id": "cred-c11f5affb514", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-c00527967443", "facet": null, "proposition": "完全切断美国军事与情报援助将严重削弱乌克兰的对俄作战能力，凸显其对西方支持的长期依赖；兵力与可持续性是乌克兰长期存续的关键问题。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-c00527967443", "source_ref_ids": "[\"src-c00527967443\"]", "verbatim_excerpt": "美国军事与情报援助的完全切断将严重损害乌克兰对俄作战能力……兵力与可持续性是长期存续的关键问题。", "cached_text_hash": "c746165f581aa29e9021afb47b770b10967302db73b1a8a6e1a76eabb4550b67", "analysis_note": "CSIS（战略与国际研究中心）机构分析，属对假想场景的前瞻性研判；印证需留待 L2 跨源完成", "filter_trace": "{\"independence\": \"单一机构观点（L3 单源，印证留待 L2 跨源）\", \"quality_density\": \"高：来源为 CSIS，论点具体、可证伪、有机构背书\", \"recency\": \"地缘快变主题，原文未含明确日期，存在时效衰减风险\"}", "debate_trace": null, "credibility_id": "cred-8c4f4a41f78c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "conden