INSERT INTO "knowledge_change_log" VALUES(169,'l3_claim','sc-ea94b692a69d','*','update','{"id": "sc-ea94b692a69d", "facet": null, "proposition": "该小红书笔记以「俄罗斯不希望你看到的数字」为题，主张存在某些被俄罗斯压制的数字证据；但因正文未抓取（规避风控），其声称的具体数字与论据无法核验。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-ea94b692a69d", "source_ref_ids": "[\"src-ea94b692a69d\"]", "verbatim_excerpt": "俄罗斯不希望你看到的数字", "cached_text_hash": "f5523776d7ac4bfe9eecdf68e34de5d46ac365b95158d53d8695f376f14a5d8a", "analysis_note": "卡片级证据：仅捕获标题、作者、互动数（点赞30/评论7），正文缺失，无从判断所声称「数字」指向的领域（伤亡/经济/军备等）。作者为系统默认匿名ID、互动量低。建议后续凭留存的 xsec_token 经 xiaohongshu-mcp 补抓正文后重新蒸馏。", "filter_trace": "{\"independence\": \"单条匿名社媒笔记，无独立来源佐证；是否为回音室转发无法从单卡判断\", \"quality_density\": \"极低——仅卡片级元数据，无正文、无具体数字、无可证伪细节\", \"recency\": \"发布时间未知；地缘政治主题时效衰减快，过期风险高\"}", "debate_trace": null, "credibility_id": "cred-0ae4f4f32720", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-ea94b692a69d", "facet": null, "proposition": "该小红书笔记以「俄罗斯不希望你看到的数字」为题，主张存在某些被俄罗斯压制的数字证据；但因正文未抓取（规避风控），其声称的具体数字与论据无法核验。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-ea94b692a69d", "source_ref_ids": "[\"src-ea94b692a69d\"]", "verbatim_excerpt": "俄罗斯不希望你看到的数字", "cached_text_hash": "f5523776d7ac4bfe9eecdf68e34de5d46ac365b95158d53d8695f376f14a5d8a", "analysis_note": "卡片级证据：仅捕获标题、作者、互动数（点赞30/评论7），正文缺失，无从判断所声称「数字」指向的领域（伤亡/经济/军备等）。作者为系统默认匿名ID、互动量低。建议后续凭留存的 xsec_token 经 xiaohongshu-mcp 补抓正文后重新蒸馏。", "filter_trace": "{\"independence\": \"单条匿名社媒笔记，无独立来源佐证；是否为回音室转发无法从单卡判断\", \"quality_density\": \"极低——仅卡片级元数据，无正文、无具体数字、无可证伪细节\", \"recency\": \"发布时间未知；地缘政治主题时效衰减快，过期风险高\"}", "debate_trace": null, "credibility_id": "cred-d3368bf2f6db", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "