INSERT INTO "knowledge_change_log" VALUES(171,'l3_claim','sc-f26d039d177f','*','update','{"id": "sc-f26d039d177f", "facet": null, "proposition": "油价持续下跌、霍尔木兹海峡滞留油轮恢复通行、且伊朗据报正寻求新买家并扩大对亚洲的石油出口——这些供应增加的迹象共同对高度依赖石油收入的俄罗斯构成财政压力。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-f26d039d177f", "source_ref_ids": "[\"src-f26d039d177f\"]", "verbatim_excerpt": "The price of oil continues to fall, and an increasing number of previously stalled oil tankers are passing through the Strait of Hormuz.", "cached_text_hash": "9f436dc9a51c2037cfe8819f52793407d22f06e5538d2afc81b17060040f3ad8", "analysis_note": "该推文将三个可观察的市场/地缘事件(油价下跌、海峡油轮疏通、伊朗扩大对亚原油出口)组合并解读为''对俄罗斯的坏消息'',核心是因果推断而非单纯事实陈述。cached_text 在''Asian''处被截断,完整推文可能含更多细节。", "filter_trace": "{\"independence\": \"单条 X 推文,据称引自未具名''media reports'',无可对照的独立来源,独立性偏低。\", \"quality_density\": \"含具体要素(霍尔木兹海峡、油轮、伊朗对亚洲出口),但文本在''Asian''处截断,密度中等。\", \"recency\": \"油价与地缘事件属快变量,时效性强,来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-66044493ad17", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f26d039d177f", "facet": null, "proposition": "油价持续下跌、霍尔木兹海峡滞留油轮恢复通行、且伊朗据报正寻求新买家并扩大对亚洲的石油出口——这些供应增加的迹象共同对高度依赖石油收入的俄罗斯构成财政压力。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-f26d039d177f", "source_ref_ids": "[\"src-f26d039d177f\"]", "verbatim_excerpt": "The price of oil continues to fall, and an increasing number of previously stalled oil tankers are passing through the Strait of Hormuz.", "cached_text_hash": "9f436dc9a51c2037cfe8819f52793407d22f06e5538d2afc81b17060040f3ad8", "analysis_note": "该推文将三个可观察的市场/地缘事件(油价下跌、海峡油轮疏通、伊朗扩大对亚原油出口)组合并解读为''对俄罗斯的坏消息'',核心是因果推断而非单纯事实陈述。cached_text 在''Asian''处被截断,完整推文可能含更多细节。", "filter_trace": "{\"independence\": \"单条 X 推文,据称引自未具名''media reports'',无可对照的独立来源,独立性偏低。\", \"quality_density\": \"含具体要素(霍尔木兹海峡、油轮、伊朗对亚洲出口),但文本在''Asian''处截断,密度中等。\", \"recency\": \"油价与地缘事件属快变量,时效性强,来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-0222102706d9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 11:48:07',NULL);
INSERT INTO "knowledge_change_log" VALUES(172,'l3_claim','sc-f8237ffa44ff','*','update','{"id": "sc-f8237ffa44ff", "facet": null, "proposition": "一条小红书笔记流传俄乌战场两名俄军士兵生命最后五分钟的影像/叙述，并以「存活艰难」的情绪视角呈现其阵亡过程；但本条正文未抓取，事件的时间、地点、人物及影像真伪均无法核实。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-f8237ffa44ff", "source_ref_ids": "[\"src-f8237ffa44ff\"]", "verbatim_excerpt": "活下去太难：两俄军士兵的最后五分钟", "cached_text_hash": "b94039e7cddbd5639e195b21e1012121513f8842cc09a6ebeface40eb55a60f8", "analysis_note": "卡片级证据：正文为规避平台风控未抓取，仅留存标题与卡片元数据（作者@男极圈💘，点赞73、评论6）。xsec_token 已留存可追溯，建议后续通过 xiaohongshu-mcp 抓取正文以提升可核验度。", "filter_trace": "{\"independence\": \"单一平台单一笔记，仅靠卡片元数据，无可交叉核对的独立来源\", \"quality_density\": \"仅有标题与点赞/评论数，无正文细节，可证伪度几乎为零\", \"recency\": \"俄乌战事快变主题，无发布时间戳可判断时效\"}", "debate_trace": null, "credibility_id": "cred-713ea7eb0768", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f8237ffa44ff", "facet": null, "proposition": "一条小红书笔记流传俄乌战场两名俄军士兵生命最后五分钟的影像/叙述，并以「存活艰难」的情绪视角呈现其阵亡过程；但本条正文未抓取，事件的时间、地点、人物及影像真伪均无法核实。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-f8237ffa44ff", "source_ref_ids": "[\"src-f8237ffa44ff\"]", "verbatim_excerpt": "活下去太难：两俄军士兵的最后五分钟", "cached_text_hash": "b94039e7cddbd5639e195b21e1012121513f8842cc09a6ebeface40eb55a60f8", "analysis_note": "卡片级证据：正文为规避平台风控未抓取，仅留存标题与卡片元数据（作者@男极圈💘，点赞73、评论6）。xsec_token 已留存可追溯，建议后续通过 xiaohongshu-mcp 抓取正文以提升可核验度。", "filter_trace": "{\"independence\": \"单一平台单一笔记，仅靠卡片元数据，无可交叉核对的独立来源\", \"quality_density\": \"仅有标题与点赞/评论数，无正文细节，可证伪度几乎为零\", \"recency\": \"俄乌战事快变主题，无发布时间戳可判断时效\"}", "debate_trace": null, "credibility_id": "cred-c45ef55de134", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at":