INSERT INTO "knowledge_change_log" VALUES(175,'l3_claim','sc-fbe09c63a68a','*','update','{"id": "sc-fbe09c63a68a", "facet": null, "proposition": "该来源（小红书新闻聚合账号『刚刚发生了啥』）声称普京承认存在燃料短缺。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-fbe09c63a68a", "source_ref_ids": "[\"src-fbe09c63a68a\"]", "verbatim_excerpt": "普京承认燃料短缺", "cached_text_hash": "aea901e1b1623f5718a1e16300b56a09c4ef51933ffead675834f50655a4a9c6", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅留存标题与元数据（点赞2/评论0）及 xsec_token 供追溯；无法核实一手出处或具体时间，属未经验证的二手转发，须待独立来源印证后方可提升。", "filter_trace": "{\"independence\": \"单一小红书聚合账号，转发性质，未见一手信源引用。\", \"quality_density\": \"信息密度极低：仅标题一句，无细节、无可证伪依据、正文缺失。\", \"recency\": \"未标注时间；俄乌战争/燃料属快变主题，来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-166dbae04260", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:28:29", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-fbe09c63a68a", "facet": null, "proposition": "该来源（小红书新闻聚合账号『刚刚发生了啥』）声称普京承认存在燃料短缺。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-fbe09c63a68a", "source_ref_ids": "[\"src-fbe09c63a68a\"]", "verbatim_excerpt": "普京承认燃料短缺", "cached_text_hash": "aea901e1b1623f5718a1e16300b56a09c4ef51933ffead675834f50655a4a9c6", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅留存标题与元数据（点赞2/评论0）及 xsec_token 供追溯；无法核实一手出处或具体时间，属未经验证的二手转发，须待独立来源印证后方可提升。", "filter_trace": "{\"independence\": \"单一小红书聚合账号，转发性质，未见一手信源引用。\", \"quality_density\": \"信息密度极低：仅标题一句，无细节、无可证伪依据、正文缺失。\", \"recency\": \"未标注时间；俄乌战争/燃料属快变主题，来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-176ed9f04aae", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','kind=brea