INSERT INTO "knowledge_change_log" VALUES(183,'l3_claim','sc-180403731046','*','update','{"id": "sc-180403731046", "facet": null, "proposition": "俄罗斯前线一辆 KAMAZ 5350 军用卡车据称被摧毁（单一社媒帖断言，无地点/时间/可核验细节）。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-180403731046", "source_ref_ids": "[\"src-180403731046\"]", "verbatim_excerpt": "Destroyed Russian KAMAZ 5350 truck somewhere on the front line", "cached_text_hash": "0d2b7c965d4411461163b6358a5c458a71fc9c91854052b640d179d6e334e2f5", "analysis_note": "这是单一 OSINT/战况帖对一件俄军装备损失的视觉性断言。仅凭文本无法验证：未给出地点、日期、所属单位或损伤方式。此类平台上的装备损毁声称在俄乌战争中常见，需独立地理定位或多源印证后方可采信。作为单源未核实主张，可信度封顶为 low。", "filter_trace": "{\"independence\": \"单源（@MilitaryNewsUA 一帖），无第二独立来源印证\", \"quality_density\": \"低：仅''前线某处一辆卡车被毁''，无可核验的地点/时间/单位/弹道信息\", \"recency\": \"持续冲突中的实时战况帖，时效新但无时间戳\"}", "debate_trace": null, "credibility_id": "cred-6c3f89a1e912", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-180403731046", "facet": null, "proposition": "俄罗斯前线一辆 KAMAZ 5350 军用卡车据称被摧毁（单一社媒帖断言，无地点/时间/可核验细节）。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-180403731046", "source_ref_ids": "[\"src-180403731046\"]", "verbatim_excerpt": "Destroyed Russian KAMAZ 5350 truck somewhere on the front line", "cached_text_hash": "0d2b7c965d4411461163b6358a5c458a71fc9c91854052b640d179d6e334e2f5", "analysis_note": "这是单一 OSINT/战况帖对一件俄军装备损失的视觉性断言。仅凭文本无法验证：未给出地点、日期、所属单位或损伤方式。此类平台上的装备损毁声称在俄乌战争中常见，需独立地理定位或多源印证后方可采信。作为单源未核实主张，可信度封顶为 low。", "filter_trace": "{\"independence\": \"单源（@MilitaryNewsUA 一帖），无第二独立来源印证\", \"quality_density\": \"低：仅''前线某处一辆卡车被毁''，无可核验的地点/时间/单位/弹道信息\", \"recency\": \"持续冲突中的实时战况帖，时效新但无时间戳\"}", "debate_trace": null, "credibility_id": "cred-9f7e38147c7c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:05:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(184,'l3_claim','sc-190ce3895a76','*','update','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型等具体可证伪细节\", \"recency\": \"快变地缘/战场主题，装备部署信息易随战况更新而过期\"}", "debate_trace": null, "credibility_id": "cred-880bd087a45c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型