INSERT INTO "knowledge_change_log" VALUES(187,'l3_claim','sc-29df650e0cd9','*','update','{"id": "sc-29df650e0cd9", "facet": null, "proposition": "乌克兰战机正使用美国提供的 GBU-39/B 小直径炸弹（SDB，250 磅/110 公斤精确制导滑翔弹）对前线附近的俄军阵地实施空袭", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-29df650e0cd9", "source_ref_ids": "[\"src-29df650e0cd9\"]", "verbatim_excerpt": "A video compilation showing Ukrainian airstrikes with US-supplied GBU-39/B Small Diameter Bombs targeting Russian positions around the frontline.", "cached_text_hash": "05732c74ce0a38d99f686c5b7811358bbad94260ae0e112dccd5f88241fb0ecf", "analysis_note": "来自知名 OSINT/战况新闻账号（Status-6 / Archer83Able），附带视频汇编作为视觉证据；属战场动态报道，单源社媒，未经独立机构核实。", "filter_trace": "{\"independence\": \"单条 X 推文，无第二独立来源交叉确认\", \"quality_density\": \"高：给出具体弹种 GBU-39/B SDB、装药重量、载机型号及打击目标\", \"recency\": \"战场动态报道，时效性强\"}", "debate_trace": null, "credibility_id": "cred-35f6d9d1d32f", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-29df650e0cd9", "facet": null, "proposition": "乌克兰战机正使用美国提供的 GBU-39/B 小直径炸弹（SDB，250 磅/110 公斤精确制导滑翔弹）对前线附近的俄军阵地实施空袭", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-29df650e0cd9", "source_ref_ids": "[\"src-29df650e0cd9\"]", "verbatim_excerpt": "A video compilation showing Ukrainian airstrikes with US-supplied GBU-39/B Small Diameter Bombs targeting Russian positions around the frontline.", "cached_text_hash": "05732c74ce0a38d99f686c5b7811358bbad94260ae0e112dccd5f88241fb0ecf", "analysis_note": "来自知名 OSINT/战况新闻账号（Status-6 / Archer83Able），附带视频汇编作为视觉证据；属战场动态报道，单源社媒，未经独立机构核实。", "filter_trace": "{\"independence\": \"单条 X 推文，无第二独立来源交叉确认\", \"quality_density\": \"高：给出具体弹种 GBU-39/B SDB、装药重量、载机型号及打击目标\", \"recency\": \"战场动态报道，时效性强\"}", "debate_trace": null, "credibility_id": "cred-eed438d49ef8", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:05:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(188,'l3_claim','sc-2df254c71e7d','*','update','{"id": "sc-2df254c71e7d", "facet": null, "proposition": "特朗普2025年11月的28点乌克兰和平方案迫使基辅在东部割让更多领土、限制乌军规模、并禁止乌克兰加入北约,但对乌武器装备不做限制;CSIS逐条分析评价该方案\"亲俄且过于模糊\",AP报道方案将把领土割让给俄罗斯。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-2df254c71e7d", "source_ref_ids": "[\"src-2df254c71e7d\"]", "verbatim_excerpt": "迫使基辅在东部割让额外领土、限制乌克兰军队规模、禁止乌克兰加入北约、但对乌武器装备无限制", "cached_text_hash": "8e2c1c5c89daf6c4c8c936d317e1ab65c6693e67205ddb450db6f034d5a1a071", "analysis_note": "方案条款为可核验的具体政策点;CSIS与AP提供独立第三方佐证其\"领土割让\"与\"亲俄\"定性。", "filter_trace": "{\"independence\": \"Axios + CSIS + AP 三个相互独立的权威来源,对方案核心条款描述一致,非单一转发\", \"quality_density\": \"列出具体可证伪条款(割让领土/限军/禁北约/不限装备),非空泛口号\", \"recency\": \"2025年11月方案;地缘政治快变主题,但该方案条款仍是后续谈判与立场对照的基准\"}", "debate_trace": null, "credibility_id": "cred-adf377676821", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-2df254c71e7d", "facet": null, "proposition": "特朗普2025年11月的28点乌克兰和平方案迫使基辅在东部割让更多领土、限制乌军规模、并禁止乌克兰加入北约,但对乌武器装备不做限制;CSIS逐条分析评价该方案\"亲俄且过于模糊\",AP报道方案将把领土割让给俄罗斯。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-2df254c71e7d", "source_ref_ids": "[\"src-2df254c71e7d\"]", "verbatim_excerpt": "迫使基辅在东部割让额外领土、限制乌克兰军队规模、禁止乌克兰加入北约、但对乌武器装备无限制", "cached_text_hash": "8e2c1c5c89daf6c4c8c936d317e1ab65c6693e67205ddb450db6f034d5a1a071", "analysis_note": "方案条款为可核验的具体政策点;CSIS与AP提供独立第三方佐证其\"领土割让\"与\"亲俄\"定性。", "filter_trace": "{\"independence\": \"Axios + CSIS + AP 三个相互独立的权威来源,对方案核心条款描述一致,非单一转发\", \"quality_density\": \"列出具体可证伪条款(割让领土/限军/禁北约/不限装备),非空泛口号\", \"recency\": \"2025年11月方案;地缘政治快变主题,但该方案条款仍是后续谈判与立场对照的基准\"}", "debate_trace": null, "credibility_id": "cred-64fcb83ac5b4", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:05:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(189,'l3_claim','sc-2e92529ce93e','*','update','{"id": "sc-2e92529ce93e", "facet": null, "proposition": "俄军一艘20380型轻型护卫舰被乌军无人机击中——这是该小红书笔记在卡片级标题中提出的主张。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-2e92529ce93e", "source_ref_ids": "[\"src-2e92529ce93e\"]", "verbatim_excerpt": "◆俄军20380型护卫舰确认被乌军无人机击中", "cached_text_hash": "a411afeaed8cf57fc34b81e4ce8a6218fd923e325ee3fdc7d31d379868a794dc", "analysis_note": "仅卡片级证据：正文因风控未抓取，可评估的只有标题、作者与互动数（点赞11/评论29）。''确认被击中''属标题断言，无可见的细节、坐标、时间或影像佐证；事件本身在俄乌冲突背景下可信度尚可成立，但本条作为单源、低密度社媒信号，暂不足以独立采信，需后续独立来源（尤其开源情报/卫星/影像）交叉印证后才能升格。", "filter_trace": "{\"independence\": \"单条小红书笔记，未见独立来源交叉印证\", \"quality_density\": \"仅标题+互动数（赞11/评29），无正文/影像/时间细节，密度低\", \"recency\": \"未标注具体日期；俄乌冲突为快变主题，事件时效待复核\"}", "debate_trace": null, "credibility_id": "cred-8bd33ba17da0", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-2e92529ce93e", "facet": null, "proposition": "俄军一艘20380型轻型护卫舰被乌军无人机击中——这是该小红书笔记在卡片级标题中提出的主张。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-2e92529ce93e", "source_ref_ids": "[\"src-2e92529ce93e\"]", "verbatim_excerpt": "◆俄军20380型护卫舰确认被乌军无人机击中", "cached_text_hash": "a411afeaed8cf57fc34b81e4ce8a6218fd923e325ee3fdc7d31d379868a794dc", "analysis_note": "仅卡片级证据：正文因风控未抓取，可评估的只有标题、作者与互动数（点赞11/评论29）。''确认被击中''属标题断言，无可见的细节、坐标、时间或影像佐证；事件本身在俄乌冲突背景下可信度尚可成立，但本条作为单源、低密度社媒信号，暂不足以独立采信，需后续独立来源（尤其开源情报/卫星/影像）交叉印证后才能升格。", "filter_trace": "{\"independence\": \"单条小红书笔记，未见独立来源交叉印证\", \"quality_density\": \"仅标题+互动数（赞11/评29），无正文/影像/时间细节，密度低\", \"recency\": \"未标注具体日期；俄乌冲突为快变主题，事件时效待复核\"}", "debate_trace": null, "credibility_id": "cred-228bf0e24020", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": n