INSERT INTO "knowledge_change_log" VALUES(192,'l3_claim','sc-326d91c55f3a','*','update','{"id": "sc-326d91c55f3a", "facet": null, "proposition": "小红书博主 @百里sir 以质疑式标题「无人机这么好，俄罗斯咋不用？」发帖，传播「无人机作战效能突出、而俄方使用明显不足」这一叙事框架，并伴随中等互动量（点赞57、评论115），反映出该议题在中文社媒上的讨论热度。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-326d91c55f3a", "source_ref_ids": "[\"src-326d91c55f3a\"]", "verbatim_excerpt": "无人机这么好，俄罗斯咋不用？", "cached_text_hash": "d4175a6ab195349f9506fedb023db9e532d4c9561505f53a5a899be3c1b50490", "analysis_note": "卡片级证据：为规避风控正文未抓取，cached_text 仅含标题/作者/互动量，无可读正文。因此本条 L3 只能蒸馏出『该帖呈现的叙事框架 + 互动热度』这一主张，无法核实作者具体论据。若该叙事对主题重要，建议凭已留存 xsec_token 重新抓取正文后再补充蒸馏。", "filter_trace": "{\"independence\": \"单一笔记，本 unit 内无其他来源佐证。\", \"quality_density\": \"低——无可读正文，仅一句反问式标题 + 点赞/评论数，无可证伪的具体论据或细节。\", \"recency\": \"发布时间未在 payload 中标注；地缘冲突议题时效衰减快，结论易过期。\"}", "debate_trace": null, "credibility_id": "cred-5de3a57a7808", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-326d91c55f3a", "facet": null, "proposition": "小红书博主 @百里sir 以质疑式标题「无人机这么好，俄罗斯咋不用？」发帖，传播「无人机作战效能突出、而俄方使用明显不足」这一叙事框架，并伴随中等互动量（点赞57、评论115），反映出该议题在中文社媒上的讨论热度。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-326d91c55f3a", "source_ref_ids": "[\"src-326d91c55f3a\"]", "verbatim_excerpt": "无人机这么好，俄罗斯咋不用？", "cached_text_hash": "d4175a6ab195349f9506fedb023db9e532d4c9561505f53a5a899be3c1b50490", "analysis_note": "卡片级证据：为规避风控正文未抓取，cached_text 仅含标题/作者/互动量，无可读正文。因此本条 L3 只能蒸馏出『该帖呈现的叙事框架 + 互动热度』这一主张，无法核实作者具体论据。若该叙事对主题重要，建议凭已留存 xsec_token 重新抓取正文后再补充蒸馏。", "filter_trace": "{\"independence\": \"单一笔记，本 unit 内无其他来源佐证。\", \"quality_density\": \"低——无可读正文，仅一句反问式标题 + 点赞/评论数，无可证伪的具体论据或细节。\", \"recency\": \"发布时间未在 payload 中标注；地缘冲突议题时效衰减快，结论易过期。\"}", "debate_trace": null, "credibility_id": "cred-