INSERT INTO "knowledge_change_log" VALUES(205,'l3_claim','sc-4e893ca84bd7','*','update','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_density\": \"密度较高：点名系统名称、武器型号（M2 Browning）与目标（Shahed/Geran），但无影像/官方佐证\", \"recency\": \"俄乌战事属快变主题，部署消息时效性强\"}", "debate_trace": null, "credibility_id": "cred-55038b6e4502", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_dens