INSERT INTO "knowledge_change_log" VALUES(215,'l3_claim','sc-6b4af507be01','*','update','{"id": "sc-6b4af507be01", "facet": null, "proposition": "作者认为乌克兰之所以能扛住俄罗斯的军事压力，关键在于不对称作战（asymmetric warfare），而非对称兵力对抗。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-6b4af507be01", "source_ref_ids": "[\"src-6b4af507be01\"]", "verbatim_excerpt": "小乌为啥能扛住大俄？不对称作战很关键", "cached_text_hash": "c5fd5cca4c7ce45b25a75df0e217df439bff3e79a936f099cadf132be6694aa1", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题/作者/互动数据可供蒸馏。命题由标题归纳而成，缺乏原文论证细节支撑，可信度因此受限。xsec_token 已留存可追溯。", "filter_trace": "{\"independence\": \"单一小红书笔记，无其他独立来源印证\", \"quality_density\": \"极低：仅标题可用，正文未抓取，无可证伪的细节/数据/论据\", \"recency\": \"无明确时间戳；俄乌为快变主题，来源时效不明\"}", "debate_trace": null, "credibility_id": "cred-7242f7da1a35", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-6b4af507be01", "facet": null, "proposition": "作者认为乌克兰之所以能扛住俄罗斯的军事压力，关键在于不对称作战（asymmetric warfare），而非对称兵力对抗。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-6b4af507be01", "source_ref_ids": "[\"src-6b4af507be01\"]", "verbatim_excerpt": "小乌为啥能扛住大俄？不对称作战很关键", "cached_text_hash": "c5fd5cca4c7ce45b25a75df0e217df439bff3e79a936f099cadf132be6694aa1", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题/作者/互动数据可供蒸馏。命题由标题归纳而成，缺乏原文论证细节支撑，可信度因此受限。xsec_token 已留存可追溯。", "filter_trace": "{\"independence\": \"单一小红书笔记，无其他独立来源印证\", \"quality_density\": \"极低：仅标题可用，正文未抓取，无可证伪的细节/数据/论据\", \"recency\": \"无明确时间戳；俄乌为快变主题，来源时效不明\"}", "debate_trace": null, "credibility_id": "cred-90ebee2975d3", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "