INSERT INTO "knowledge_change_log" VALUES(223,'l3_claim','sc-88448fc33f10','*','update','{"id": "sc-88448fc33f10", "facet": null, "proposition": "俄罗斯提出建议，呼吁乌克兰与俄罗斯双方均停止打击对方领土的纵深目标（即相互限制对纵深/远程目标的打击）。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-88448fc33f10", "source_ref_ids": "[\"src-88448fc33f10\"]", "verbatim_excerpt": "俄罗斯建议乌俄均停止打击对方领土纵深目标", "cached_text_hash": "bb0424a04f41e9cee100b8ea4bb6f2a7ee399c363dffc57fdace2925bc6ef4a6", "analysis_note": "卡片级证据：正文因风控未抓取，仅有标题与作者/互动数；xsec_token 已留存可追溯。主张来自主流财经媒体（每日经济新闻）的小红书转载，缺少发言人、时间、条件、范围等细节，无法进一步核实具体情境。", "filter_trace": "{\"independence\": \"单一信源：每日经济新闻的小红书卡片转载，无独立来源交叉印证，互动量低（点赞4/评论6）不构成回音室。\", \"quality_density\": \"低密度：仅标题级证据，正文未抓取，缺少发言人、提出时间、互换条件、打击范围等可证伪细节。\", \"recency\": \"地缘政治快变主题，单条即时新闻易被后续进展覆盖或修正。\"}", "debate_trace": null, "credibility_id": "cred-9941ae3e0acc", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-88448fc33f10", "facet": null, "proposition": "俄罗斯提出建议，呼吁乌克兰与俄罗斯双方均停止打击对方领土的纵深目标（即相互限制对纵深/远程目标的打击）。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-88448fc33f10", "source_ref_ids": "[\"src-88448fc33f10\"]", "verbatim_excerpt": "俄罗斯建议乌俄均停止打击对方领土纵深目标", "cached_text_hash": "bb0424a04f41e9cee100b8ea4bb6f2a7ee399c363dffc57fdace2925bc6ef4a6", "analysis_note": "卡片级证据：正文因风控未抓取，仅有标题与作者/互动数；xsec_token 已留存可追溯。主张来自主流财经媒体（每日经济新闻）的小红书转载，缺少发言人、时间、条件、范围等细节，无法进一步核实具体情境。", "filter_trace": "{\"independence\": \"单一信源：每日经济新闻的小红书卡片转载，无独立来源交叉印证，互动量低（点赞4/评论6）不构成回音室。\", \"quality_density\": \"低密度：仅标题级证据，正文未抓取，缺少发言人、提出时间、互换条件、打击范围等可证伪细节。\", \"recency\": \"地缘政治快变主题，单条即时新闻易被后续进展覆盖或修正。\"}", "debate_trace": null, "credibility_id": "cred-df36c9fb6d3b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null,