INSERT INTO "knowledge_change_log" VALUES(230,'l3_claim','sc-92cca377a81c','*','update','{"id": "sc-92cca377a81c", "facet": null, "proposition": "普京称基辅将因库尔斯克地区的行动付出代价——以丧失俄方建立安全缓冲区所需的领土为代价,并明确表示俄罗斯无意''拯救''基辅政权。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-92cca377a81c", "source_ref_ids": "[\"src-92cca377a81c\"]", "verbatim_excerpt": "Putin: Kiev will pay for its actions in the Kursk region by losing territory needed for a security buffer zone. Saving the Kiev government is not part of Russia''s plans.", "cached_text_hash": "0b97e2c53fd776469d193c70e0c2b1ac93a48ea730cb75a29ffbb4350955634e", "analysis_note": "这是由亲俄聚合账号转述的普京公开表态:一是提出以乌克兰领土建立''安全缓冲区''的领土诉求,二是声明不以更迭基辅政权为目标。属威慑性政治宣示,非已发生的既成事实。", "filter_trace": "{\"independence\": \"单一信源(@RussiaNews / mog_russEN),为亲俄聚合账号,未见独立主流信源交叉印证。\", \"quality_density\": \"为带具体主张的直接引语(缓冲区+政权议题),信息密度尚可,但属威慑修辞而非可验证事实。\", \"recency\": \"当前热点战事相关,时点新鲜。\"}", "debate_trace": null, "credibility_id": "cred-c79ca3c13d55", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-92cca377a81c", "facet": null, "proposition": "普京称基辅将因库尔斯克地区的行动付出代价——以丧失俄方建立安全缓冲区所需的领土为代价,并明确表示俄罗斯无意''拯救''基辅政权。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-92cca377a81c", "source_ref_ids": "[\"src-92cca377a81c\"]", "verbatim_excerpt": "Putin: Kiev will pay for its actions in the Kursk region by losing territory needed for a security buffer zone. Saving the Kiev government is not part of Russia''s plans.", "cached_text_hash": "0b97e2c53fd776469d193c70e0c2b1ac93a48ea730cb75a29ffbb4350955634e", "analysis_note": "这是由亲俄聚合账号转述的普京公开表态:一是提出以乌克兰领土建立''安全缓冲区''的领土诉求,二是声明不以更迭基辅政权为目标。属威慑性政治宣示,非已发生的既成事实。", "filter_trace": "{\"independence\": \"单一信源(@RussiaNews / mog_russEN),为亲俄聚合账号,未见独立主流信源交叉印证。\", \"quality_density\": \"为带具体主张的直接引语(缓冲区+政权议题),信息密度尚可,但属威慑修辞而非可验证事实。\", \"recency\": \"当前热点战事相关,时点新鲜。\"}", "debate_trace": null, "credibility_id": "cred-1931366bc476", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 12:05:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(231,'l3_claim','sc-93f49315a162','*','update','{"id": "sc-93f49315a162", "facet": null, "proposition": "俄乌冲突中双方的无人机攻防战正在持续升级（仅来自笔记标题，正文未抓取，无法验证细节）。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-93f49315a162", "source_ref_ids": "[\"src-93f49315a162\"]", "verbatim_excerpt": "俄乌冲突最新战况：无人机攻防战持续升级", "cached_text_hash": "c0adaaffb9a259c2aed77b5eb5d978e35bb6987c064d9b9a55644bae9c1fb9ab", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅有标题/作者/互动数据可追溯。作者为财经评论类账号（K线与烟火🔥），非一手战地或官方信源；5赞0评论，互动极低。无法提取具体时间、地点、装备型号或战果等可证伪细节。", "filter_trace": "{\"independence\": \"单一社媒笔记，无任何独立来源交叉印证；作者为财经评论账号而非战地/官方信源。\", \"quality_density\": \"极低：仅标题一句话，正文缺失，无时间/地点/战果等可证伪细节。\", \"recency\": \"标题自称''最新战况''但无确切时间戳，地缘冲突类信息时效衰减快，无法确认仍有效。\"}", "debate_trace": null, "credibility_id": "cred-053bb671c212", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-93f49315a162", "facet": null, "proposition": "俄乌冲突中双方的无人机攻防战正在持续升级（仅来自笔记标题，正文未抓取，无法验证细节）。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-93f49315a162", "source_ref_ids": "[\"src-93f49315a162\"]", "verbatim_excerpt": "俄乌冲突最新战况：无人机攻防战持续升级", "cached_text_hash": "c0adaaffb9a259c2aed77b5eb5d978e35bb6987c064d9b9a55644bae9c1fb9ab", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅有标题/作者/互动数据可追溯。作者为财经评论类账号（K线与烟火🔥），非一手战地或官方信源；5赞0评论，互动极低。无法提取具体时间、地点、装备型号或战果等可证伪细节。", "filter_trace": "{\"independence\": \"单一社媒笔记，无任何独立来源交叉印证；作者为财经评论账号而非战地/官方信源。\", \"quality_density\": \"极低：仅标题一句话，正文缺失，无时间/地点/战果等可证伪细节。\", \"recency\": \"标题自称''最新战况''但无确切时间戳，地缘冲突类信息时效衰减快，无法确认仍有效。\"}", "debate_trace": null, "credibility_id": "cred-3419acc6bea6", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026