INSERT INTO "knowledge_change_log" VALUES(252,'l3_claim','sc-cc776423d9c2','*','update','{"id": "sc-cc776423d9c2", "facet": null, "proposition": "普京将俄罗斯当前处境定调为「命运攸关」的关键时刻，暗示国家/战局正处于重大抉择节点。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-cc776423d9c2", "source_ref_ids": "[\"src-cc776423d9c2\"]", "verbatim_excerpt": "普京：俄罗斯正处于命运攸关之际！", "cached_text_hash": "61d7facc545bbd0cb7060571e5e5337015000ffb803f3994a059cb1e8d051cd5", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题 + 互动数据（点赞347/评论60）+ 作者。无法核实原文措辞、语境与具体所指；本条 L3 仅基于标题级信号。", "filter_trace": "{\"independence\": \"华夏时报为转载媒体；原始声明可追溯至普京，但本条本身无独立核实链\", \"quality_density\": \"仅标题，无正文/细节/可证伪要素，无法判断「命运攸关」具体所指\", \"recency\": \"属当前俄乌战局议题，时效尚可，但卡片未含明确时间戳\"}", "debate_trace": null, "credibility_id": "cred-bf41a4d0c644", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-cc776423d9c2", "facet": null, "proposition": "普京将俄罗斯当前处境定调为「命运攸关」的关键时刻，暗示国家/战局正处于重大抉择节点。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-cc776423d9c2", "source_ref_ids": "[\"src-cc776423d9c2\"]", "verbatim_excerpt": "普京：俄罗斯正处于命运攸关之际！", "cached_text_hash": "61d7facc545bbd0cb7060571e5e5337015000ffb803f3994a059cb1e8d051cd5", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题 + 互动数据（点赞347/评论60）+ 作者。无法核实原文措辞、语境与具体所指；本条 L3 仅基于标题级信号。", "filter_trace": "{\"independence\": \"华夏时报为转载媒体；原始声明可追溯至普京，但本条本身无独立核实链\", \"quality_density\": \"仅标题，无正文/细节/可证伪要素，无法判断「命运攸关」具体所指\", \"recency\": \"属当前俄乌战局议题，时效尚可，但卡片未含明确时间戳\"}", "debate_trace": null, "credibility_id": "cred-ffd723547f58", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": n