INSERT INTO "knowledge_change_log" VALUES(264,'l3_claim','sc-f1c12cd19264','*','update','{"id": "sc-f1c12cd19264", "facet": null, "proposition": "一名小红书用户以图文笔记记录基辅当前的日常生活现状（标题『基辅生活现状』），该笔记获 464 赞、135 评论，反映中文社媒对基辅实地生活状况的一定关注度。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-f1c12cd19264", "source_ref_ids": "[\"src-f1c12cd19264\"]", "verbatim_excerpt": "基辅生活现状 · 作者 @lyy · 点赞464 评论135（正文未抓取以规避风控）", "cached_text_hash": "00b36cdcd433642407e4f3fb637255b12907c24d05c4c581eb69a96b758fd1f3", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅留存标题/作者/互动数与可追溯 xsec_token，无法核验笔记内部的具体主张。实质内容需回溯抓取后另行蒸馏；当前仅可作为『存在该话题关注』的弱信号。", "filter_trace": "{\"independence\": \"单条小红书笔记，无其他独立来源印证\", \"quality_density\": \"极低——仅有标题与互动数，无正文主张、无可证伪细节\", \"recency\": \"未留存发布时间，时效衰减无法判断\"}", "debate_trace": null, "credibility_id": "cred-90b15fc3151a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 11:48:07", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f1c12cd19264", "facet": null, "proposition": "一名小红书用户以图文笔记记录基辅当前的日常生活现状（标题『基辅生活现状』），该笔记获 464 赞、135 评论，反映中文社媒对基辅实地生活状况的一定关注度。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-f1c12cd19264", "source_ref_ids": "[\"src-f1c12cd19264\"]", "verbatim_excerpt": "基辅生活现状 · 作者 @lyy · 点赞464 评论135（正文未抓取以规避风控）", "cached_text_hash": "00b36cdcd433642407e4f3fb637255b12907c24d05c4c581eb69a96b758fd1f3", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅留存标题/作者/互动数与可追溯 xsec_token，无法核验笔记内部的具体主张。实质内容需回溯抓取后另行蒸馏；当前仅可作为『存在该话题关注』的弱信号。", "filter_trace": "{\"independence\": \"单条小红书笔记，无其他独立来源印证\", \"quality_density\": \"极低——仅有标题与互动数，无正文主张、无可证伪细节\", \"recency\": \"未留存发布时间，时效衰减无法判断\"}", "debate_trace": null, "credibility_id": "cred-aa3605cccc1e", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29