INSERT INTO "knowledge_change_log" VALUES(318,'l3_claim','sc-190ce3895a76','*','update','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型等具体可证伪细节\", \"recency\": \"快变地缘/战场主题，装备部署信息易随战况更新而过期\"}", "debate_trace": null, "credibility_id": "cred-31d2b4e2b222", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型等具体可证伪细节\", \"recency\": \"快变地缘/战场主题，装备部署信息易随战况更新而过期\"}", "debate_trace": null, "credibility_id": "cred-2567076317e0", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:40:37',NULL);
INSERT INTO "knowledge_change_log" VALUES(319,'l3_claim','sc-203e750d5c6f','*','update','{"id": "sc-203e750d5c6f", "facet": null, "proposition": "一篇小红书旅行博主笔记（@探险男孩在旅行啊，2238 赞 / 237 评）以亲历/观察视角呈现俄乌战争背景下「未逃离的乌克兰平民日常生活现状」这一议题；但其正文未被抓取，不构成可独立评估的实质主张，仅作卡片级线索留存（xsec_token 可追溯，可后续补抓正文二次蒸馏）。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-203e750d5c6f", "source_ref_ids": "[\"src-203e750d5c6f\"]", "verbatim_excerpt": "乌克兰没有逃离的人，日子过的怎么样", "cached_text_hash": "93ec5222433f163e50a557c96230b871d8172590621b8955e9b866e9919ea3e4", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题、作者、互动量。无法蒸馏出具体可证伪主张；标题指向「战时乌克兰留驻平民生活状况」facet 方向，实质命题待补抓正文后再蒸馏。", "filter_trace": "{\"independence\": \"单一旅行博主账号的社媒笔记，未见独立来源横向印证\", \"quality_density\": \"正文未抓取，仅余标题与点赞/评论数，无细节、无可证伪信息，信息密度无法判定\", \"recency\": \"发布时间未知，仅 2238 赞/237 评可作热度参考，时效衰减无法判定\"}", "debate_trace": null, "credibility_id": "cred-221d5adce016", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-203e750d5c6f", "facet": null, "proposition": "一篇小红书旅行博主笔记（@探险男孩在旅行啊，2238 赞 / 237 评）以亲历/观察视角呈现俄乌战争背景下「未逃离的乌克兰平民日常生活现状」这一议题；但其正文未被抓取，不构成可独立评估的实质主张，仅作卡片级线索留存（xsec_token 可追溯，可后续补抓正文二次蒸馏）。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-203e750d5c6f", "source_ref_ids": "[\"src-203e750d5c6f\"]", "verbatim_excerpt": "乌克兰没有逃离的人，日子过的怎么样", "cached_text_hash": "93ec5222433f163e50a557c96230b871d8172590621b8955e9b866e9919ea3e4", "analysis_note": "卡片级证据：正文未抓取（规避风控），仅有标题、作者、互动量。无法蒸馏出具体可证伪主张；标题指向「战时乌克兰留驻平民生活状况」facet 方向，实质命题待补抓正文后再蒸馏。", "filter_trace": "{\"independence\": \"单一旅行博主账号的社媒笔记，未见独立来源横向印证\", \"quality_density\": \"正文未抓取，仅余标题与点赞/评论数，无细节、无可证伪信息，信息密度无法判定\", \"recency\": \"发布时间未知，仅 2238 赞/237 评可作热度参考，时效衰减无法判定\"}", "debate_trace": null, "credibility_id": "cred-576704a4ce53", "parent_l2_id": nul