INSERT INTO "knowledge_change_log" VALUES(324,'l3_claim','sc-2ed4b44997f4','*','update','{"id": "sc-2ed4b44997f4", "facet": null, "proposition": "一篇小红书笔记（@-LU LU）分享/讨论从俄罗斯收汇（跨境收款）的相关内容，因风控仅抓取到卡片级元数据，正文未留存，具体方法或主张无法从文本核验。", "claim_kind": "other", "source_kind": "post", "single_source_ref_id": "src-2ed4b44997f4", "source_ref_ids": "[\"src-2ed4b44997f4\"]", "verbatim_excerpt": "俄罗斯收汇", "cached_text_hash": "8d4df6432a7d86440d26329924265f5a8bb5e1c08d9f37c02999fefbed5f1f30", "analysis_note": "卡片级证据：正文为规避风控未抓取，仅有标题「俄罗斯收汇」+ 互动数据（赞2/评20）。评论数显著高于点赞，提示该话题实操/讨论属性强，但实际主张不可核验。proposition 只能基于标题推断主题方向，不能断言正文细节。", "filter_trace": "{\"independence\": \"单一社媒笔记，原创性与是否转发自第三方未知\", \"quality_density\": \"低——只有标题与互动计数，无可证伪的事实/数据/操作细节\", \"recency\": \"笔记无明确时间戳，时效无法判定\"}", "debate_trace": null, "credibility_id": "cred-2f3218017a52", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-2ed4b44997f4", "facet": null, "proposition": "一篇小红书笔记（@-LU LU）分享/讨论从俄罗斯收汇（跨境收款）的相关内容，因风控仅抓取到卡片级元数据，正文未留存，具体方法或主张无法从文本核验。", "claim_kind": "other", "source_kind": "post", "single_source_ref_id": "src-2ed4b44997f4", "source_ref_ids": "[\"src-2ed4b44997f4\"]", "verbatim_excerpt": "俄罗斯收汇", "cached_text_hash": "8d4df6432a7d86440d26329924265f5a8bb5e1c08d9f37c02999fefbed5f1f30", "analysis_note": "卡片级证据：正文为规避风控未抓取，仅有标题「俄罗斯收汇」+ 互动数据（赞2/评20）。评论数显著高于点赞，提示该话题实操/讨论属性强，但实际主张不可核验。proposition 只能基于标题推断主题方向，不能断言正文细节。", "filter_trace": "{\"independence\": \"单一社媒笔记，原创性与是否转发自第三方未知\", \"quality_density\": \"低——只有标题与互动计数，无可证伪的事实/数据/操作细节\", \"recency\": \"笔记无明确时间戳，时效无法判定\"}", "debate_trace": null, "credibility_id": "cred-e7ed4848ad83", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-2