INSERT INTO "knowledge_change_log" VALUES(329,'l3_claim','sc-35b5b46bb66f','*','update','{"id": "sc-35b5b46bb66f", "facet": null, "proposition": "2025年西方能源制裁导致俄罗斯石油收入同比下降约20%，乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队与替代供应链承压。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-35b5b46bb66f", "source_ref_ids": "[\"src-35b5b46bb66f\"]", "verbatim_excerpt": "俄罗斯石油收入：2025年因制裁石油收入下降约20%。乌拉尔原油相对布伦特折价扩大至每桶逾24美元。", "cached_text_hash": "7a6ab35dfbc77ef8a4acb2864e8ec802647f140f26d16fa20006e6e6be0b5c80", "analysis_note": "数据为FT援引，叠加Riddle Russia与GIS分析，反映制裁对俄财政的累积杀伤与价格上限机制效果。", "filter_trace": "{\"independence\": \"聚合FT、Riddle Russia、GIS三方观点，但均收敛于同一制裁叙事，独立性中等\", \"quality_density\": \"高密度：含具体收入降幅与折价数值，可证伪\", \"recency\": \"2025年数据，时效性强、未过期\"}", "debate_trace": null, "credibility_id": "cred-3c6fb23d6807", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-35b5b46bb66f", "facet": null, "proposition": "2025年西方能源制裁导致俄罗斯石油收入同比下降约20%，乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队与替代供应链承压。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-35b5b46bb66f", "source_ref_ids": "[\"src-35b5b46bb66f\"]", "verbatim_excerpt": "俄罗斯石油收入：2025年因制裁石油收入下降约20%。乌拉尔原油相对布伦特折价扩大至每桶逾24美元。", "cached_text_hash": "7a6ab35dfbc77ef8a4acb2864e8ec802647f140f26d16fa20006e6e6be0b5c80", "analysis_note": "数据为FT援引，叠加Riddle Russia与GIS分析，反映制裁对俄财政的累积杀伤与价格上限机制效果。", "filter_trace": "{\"independence\": \"聚合FT、Riddle Russia、GIS三方观点，但均收敛于同一制裁叙事，独立性中等\", \"quality_density\": \"高密度：含具体收入降幅与折价数值，可证伪\", \"recency\": \"2025年数据，时效性强、未过期\"}", "debate_trace": null, "credibility_id": "cred-ad6759ad689d", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=data facet=None','condense-distill','2026-06-29 12:40:37',NULL);
INSERT INTO "knowledge_change_log" VALUES(330,'l3_claim','sc-3a6bff93c0af','*','update','{"id": "sc-3a6bff93c0af", "facet": null, "proposition": "一名 X 用户断言俄军已实际占领 Kostyantynivka 与 Lyman，并将随后包围 Slovyansk 与 Kramatorsk、从而控制整个顿巴斯，同时声称西方主流媒体关于乌克兰以无人机攻势击败俄罗斯的报道系捏造叙事。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-3a6bff93c0af", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "verbatim_excerpt": "the capture of Kostyantynivka and Lyman is a fact.", "cached_text_hash": "61516246129f260c8aa8161f4e318694308c4816b326fa0114a3d3986698fc11", "analysis_note": "单个未标明资质的社媒账号对战局进展作出的带强倾向性（pro-Russia）解读：将争议性领土占领陈述为''事实''，并以''捏造叙事''否定相反报道。地名具体（信息密度尚可），但无任何独立证据或来源支撑，且属快速过期的战场断言，需独立多源印证后方可采信。", "filter_trace": "{\"independence\": \"仅单条个人推文，post 内无任何独立来源佐证其领土占领或''媒体捏造''之断言。\", \"quality_density\": \"提及具体地名（Kostyantynivka/Lyman/Slovyansk/Kramatorsk）有一定密度，但无出处、无可证伪细节，''fabricated narrative''式措辞削弱质量。\", \"recency\": \"为快速移动的战场进展断言，属高 recency_decay 类型，信息极易随战线变化而过期。\"}", "debate_trace": null, "credibility_id": "cred-a0a4ba4ba6c0", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-3a6bff93c0af", "facet": null, "proposition": "一名 X 用户断言俄军已实际占领 Kostyantynivka 与 Lyman，并将随后包围 Slovyansk 与 Kramatorsk、从而控制整个顿巴斯，同时声称西方主流媒体关于乌克兰以无人机攻势击败俄罗斯的报道系捏造叙事。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-3a6bff93c0af", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "verbatim_excerpt": "the capture of Kostyantynivka and Lyman is a fact.", "cached_text_hash": "61516246129f260c8aa8161f4e318694308c4816b326fa0114a3d3986698fc11", "analysis_note": "单个未标明资质的社媒账号对战局进展作出的带强倾向性（pro-Russia）解读：将争议性领土占领陈述为''事实''，并以''捏造叙事''否定相反报道。地名具体（信息密度尚可），但无任何独立证据或来源支撑，且属快速过期的战场断言，需独立多源印证后方可采信。", "filter_trace": "{\"independence\": \"仅单条个人推文，post 内无任何独立来源佐证其领土占领或''媒体捏造''之断言。\", \"quality_density\": \"提及具体地名（Kostyantynivka/Lyman/Slovyansk/Kramatorsk）有一定密度，但无出处、无可证伪细节，''fabricated narrative''式措辞削弱质量。\", \"recency\": \"为快速移动的战场进展断言，属高 recency_decay 类型，信息极易随战线变化而过期。\"}", "debate_trace": null, "credibility_id": "cred-07ef2a414e31", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 12:40:37',NULL);
