INSERT INTO "knowledge_change_log" VALUES(372,'l3_claim','sc-ad1ae14d84e0','*','update','{"id": "sc-ad1ae14d84e0", "facet": null, "proposition": "小红书军事分析账号 @军武解码 发布笔记，主张无人机是俄乌冲突中的致命/杀伤性武器（卡片级证据，正文未抓取，具体论据与数据不可考）", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-ad1ae14d84e0", "source_ref_ids": "[\"src-ad1ae14d84e0\"]", "verbatim_excerpt": "【小红书笔记】俄乌冲突中死亡无人机 作者: @军武解码 | 点赞5155 评论806（正文未抓取，无实质原文可引）", "cached_text_hash": "2027696d2a548e48150b7fecdb86087deb171fd256d072df51d7db262d6146b8", "analysis_note": "仅有卡片级证据：标题『俄乌冲突中死亡无人机』+ 作者 + 互动数据（点赞5155/评论806），正文为规避风控未抓取。无法核实其具体论点、论据或引用，命题仅为标题所指向的主题方向，不构成可证伪的实质主张。xsec_token 已留存，必要时可回溯重抓。", "filter_trace": "{\"independence\": \"单源社媒笔记，无其他独立来源印证\", \"quality_density\": \"仅卡片标题，正文未抓取，信息密度低、不可证伪\", \"recency\": \"无时间戳，发布时间未知；俄乌战况快速变化，时效性不可考\"}", "debate_trace": null, "credibility_id": "cred-850b93c62297", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-ad1ae14d84e0", "facet": null, "proposition": "小红书军事分析账号 @军武解码 发布笔记，主张无人机是俄乌冲突中的致命/杀伤性武器（卡片级证据，正文未抓取，具体论据与数据不可考）", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-ad1ae14d84e0", "source_ref_ids": "[\"src-ad1ae14d84e0\"]", "verbatim_excerpt": "【小红书笔记】俄乌冲突中死亡无人机 作者: @军武解码 | 点赞5155 评论806（正文未抓取，无实质原文可引）", "cached_text_hash": "2027696d2a548e48150b7fecdb86087deb171fd256d072df51d7db262d6146b8", "analysis_note": "仅有卡片级证据：标题『俄乌冲突中死亡无人机』+ 作者 + 互动数据（点赞5155/评论806），正文为规避风控未抓取。无法核实其具体论点、论据或引用，命题仅为标题所指向的主题方向，不构成可证伪的实质主张。xsec_token 已留存，必要时可回溯重抓。", "filter_trace": "{\"independence\": \"单源社媒笔记，无其他独立来源印证\", \"quality_density\": \"仅卡片标题，正文未抓取，信息密度低、不可证伪\", \"recency\": \"无时间戳，发布时间未知；俄乌战况快速变化，时效性不可考\"}", "debate_trace": null, "credibility_id": "cred-2ce380e69142", "parent_l2_id": null, "lifecycle": null, "status": "active", "run