INSERT INTO "knowledge_change_log" VALUES(373,'l3_claim','sc-ad9cdb6444c8','*','update','{"id": "sc-ad9cdb6444c8", "facet": null, "proposition": "2024年8月6日约1.1万乌军发起库尔斯克攻势,为2022年俄乌冲突以来乌方最大跨境攻击;峰值乌控俄领土约1000平方公里,至2025年初俄军反攻将其缩至峰值约四分之一,2025年1月又有第二次较小规模库尔斯克推进。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-ad9cdb6444c8", "source_ref_ids": "[\"src-ad9cdb6444c8\"]", "verbatim_excerpt": "2024年8月6日乌武装力量约1.1万人突袭俄库尔斯克州……峰值乌控约1000平方公里俄领土。至2025年初俄军反攻将乌控区缩减至峰值约四分之一。", "cached_text_hash": "88d5d75a7f9ef256e3bcc8a5386d64d4c8c465d22024dae4d5f199d2ff81172e", "analysis_note": "维基百科条目对库尔斯克攻势的百科式摘要,给出可证伪的具体数字(兵力约1.1万、峰值约1000平方公里、缩至约1/4)与明确时间线;属历史事实陈述,非截断。", "filter_trace": "{\"independence\": \"维基为三级聚合来源,综合多路既有报道,非单一回声\", \"quality_density\": \"高:兵力约1.1万、峰值约1000平方公里、缩至约1/4、2025年1月二次推进等具体可核验细节\", \"recency\": \"中等:事件截至2025年初,快变地缘主题当前态势可能已变动,但历史经过稳定\"}", "debate_trace": null, "credibility_id": "cred-db74e529e3a9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:05:45", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-ad9cdb6444c8", "facet": null, "proposition": "2024年8月6日约1.1万乌军发起库尔斯克攻势,为2022年俄乌冲突以来乌方最大跨境攻击;峰值乌控俄领土约1000平方公里,至2025年初俄军反攻将其缩至峰值约四分之一,2025年1月又有第二次较小规模库尔斯克推进。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-ad9cdb6444c8", "source_ref_ids": "[\"src-ad9cdb6444c8\"]", "verbatim_excerpt": "2024年8月6日乌武装力量约1.1万人突袭俄库尔斯克州……峰值乌控约1000平方公里俄领土。至2025年初俄军反攻将乌控区缩减至峰值约四分之一。", "cached_text_hash": "88d5d75a7f9ef256e3bcc8a5386d64d4c8c465d22024dae4d5f199d2ff81172e", "analysis_note": "维基百科条目对库尔斯克攻势的百科式摘要,给出可证伪的具体数字(兵力约1.1万、峰值约1000平方公里、缩至约1/4)与明确时间线;属历史事实陈述,非截断。", "filter_trace": "{\"independence\": \"维基为三级聚合来源,综合多路既有报道,非单一回声\", \"quality_density\": \"高:兵力约1.1万、峰值约1000平方公里、缩至约1/4、2025年1月二次推进等具体可核验细节\", \"recency\": \"中等:事件截至2025年初,快变地缘主题当前态势可能已变动,但历史经过稳定\"}", "debate_trace": null, "credibility_id": "cred-713cd6363d7e", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:05:45", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:40:37',NULL);
