INSERT INTO "knowledge_change_log" VALUES(375,'l3_claim','sc-af2be8ea61e3','*','update','{"id": "sc-af2be8ea61e3", "facet": null, "proposition": "普京公开宣称乌克兰将因在库尔斯克（Kursk）的「罪行」付出失去领土的代价，并誓言俄罗斯不会允许敌方阻断俄军的推进。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-af2be8ea61e3", "source_ref_ids": "[\"src-af2be8ea61e3\"]", "verbatim_excerpt": "Putin afirmou que o regime ucraniano VAI PAGAR pelos seus crimes em Kursk com a perda de território. O presidente russo afirmou que a Rússia não permitirá que o inimigo interrompa o avanço de suas tropas.", "cached_text_hash": "5a6586c064799460cf54829d9bb479db3a5e764f23f5d03bc1f2dec8209e6fdd", "analysis_note": "此为俄方官方立场/施压性表态的信号，反映俄对库尔斯克战事的公开态度，但作为客观军事事实需独立来源印证。", "filter_trace": "{\"independence\": \"单一来源；RT 为俄国家媒体，是克宫立场的传声筒，缺乏独立第三方印证。\", \"quality_density\": \"直接转述普京具体声明（库尔斯克、领土代价、不阻断推进），信息密度中等且可证伪。\", \"recency\": \"涉及库尔斯克战事的即时事态，属快变地缘主题，时效性强、来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-a18943931530", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-af2be8ea61e3", "facet": null, "proposition": "普京公开宣称乌克兰将因在库尔斯克（Kursk）的「罪行」付出失去领土的代价，并誓言俄罗斯不会允许敌方阻断俄军的推进。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-af2be8ea61e3", "source_ref_ids": "[\"src-af2be8ea61e3\"]", "verbatim_excerpt": "Putin afirmou que o regime ucraniano VAI PAGAR pelos seus crimes em Kursk com a perda de território. O presidente russo afirmou que a Rússia não permitirá que o inimigo interrompa o avanço de suas tropas.", "cached_text_hash": "5a6586c064799460cf54829d9bb479db3a5e764f23f5d03bc1f2dec8209e6fdd", "analysis_note": "此为俄方官方立场/施压性表态的信号，反映俄对库尔斯克战事的公开态度，但作为客观军事事实需独立来源印证。", "filter_trace": "{\"independence\": \"单一来源；RT 为俄国家媒体，是克宫立场的传声筒，缺乏独立第三方印证。\", \"quality_density\": \"直接转述普京具体声明（库尔斯克、领土代价、不阻断推进），信息密度中等且可证伪。\", \"recency\": \"涉及库尔斯克战事的即时事态，属快变地缘主题，时效性强、来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-c47126b769ec", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 12:40:37',NULL);
INSERT INTO "knowledge_change_log" VALUES(376,'l3_claim','sc-b0f6d13376c6','*','update','{"id": "sc-b0f6d13376c6", "facet": null, "proposition": "一条高热度小红书笔记（3.53万赞、78评）提出疑问:俄罗斯在长期制裁下经济为何仍未崩溃——但笔记正文未抓取(规避风控),仅余标题、作者与互动数据作为卡片级证据,无实质论据可评估。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-b0f6d13376c6", "source_ref_ids": "[\"src-b0f6d13376c6\"]", "verbatim_excerpt": "被制裁了那么久,大俄经济为啥还没崩溃?", "cached_text_hash": "9f7675156f2acab89edb54e7068c7eb744a52f2b295db1e5e6b977fa998512e7", "analysis_note": "卡片级证据:cached_text 仅含标题与点赞/评论数,正文未抓取。因此本 L3 只能记录该笔记的『存在性 + 议题主张/框定』,无法蒸馏出作者的实际论据链路。该笔记应为 topics/russia_ukraine_war 下关于『制裁下俄经济韧性』的社媒热度信号,而非可独立采信的事实。", "filter_trace": "{\"independence\": \"单条笔记卡片级证据,正文缺失,无法判断是原创分析还是搬运/转发,独立性未知。\", \"quality_density\": \"低——正文缺失,仅有标题 + 赞/评数,无可证伪的实质性论据或数据。\", \"recency\": \"笔记确切发布时间未知(content_hash/笔记ID 无法可靠反推日期);俄制裁为快变地缘主题,需后续核验时效,可能已过期。\"}", "debate_trace": null, "credibility_id": "cred-8b59aa0163c6", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-b0f6d13376c6", "facet": null, "proposition": "一条高热度小红书笔记（3.53万赞、78评）提出疑问:俄罗斯在长期制裁下经济为何仍未崩溃——但笔记正文未抓取(规避风控),仅余标题、作者与互动数据作为卡片级证据,无实质论据可评估。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-b0f6d13376c6", "source_ref_ids": "[\"src-b0f6d13376c6\"]", "verbatim_excerpt": "被制裁了那么久,大俄经济为啥还没崩溃?", "cached_text_hash": "9f7675156f2acab89edb54e7068c7eb744a52f2b295db1e5e6b977fa998512e7", "analysis_note": "卡片级证据:cached_text 仅含标题与点赞/评论数,正文未抓取。因此本 L3 只能记录该笔记的『存在性 + 议题主张/框定』,无法蒸馏出作者的实际论据链路。该笔记应为 topics/russia_ukraine_war 下关于『制裁下俄经济韧性』的社媒热度信号,而非可独立采信的事实。", "filter_trace": "{\"independence\": \"单条笔记卡片级证据,正文缺失,无法判断是原创分析还是搬运/转发,独立性未知。\", \"quality_density\": \"低——正文缺失,仅有标题 + 赞/评数,无可证伪的实质性论据或数据。\", \"recency\": \"笔记确切发布时间未知(content_hash/笔记ID 无法可靠反推日期);俄制裁