INSERT INTO "knowledge_change_log" VALUES(381,'l3_claim','sc-baa2a4619ead','*','update','{"id": "sc-baa2a4619ead", "facet": null, "proposition": "小红书博主「老金」于6.28断言：乌克兰单日有3架米格-29战机被摧毁（仅卡片级证据，正文未留存，无支撑细节）。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-baa2a4619ead", "source_ref_ids": "[\"src-baa2a4619ead\"]", "verbatim_excerpt": "乌克兰一日3架米格29被摧毁", "cached_text_hash": "b1813232ce21ddc44860f7f3db56d6340cd358c2f3a3ab24f136444bed94d170", "analysis_note": "卡片级证据：仅有标题与互动元数据，正文未抓取。属「沙盘」类日更军情自媒体的单方战果断言，未经独立核实，无具体时间/地点/损失机制/来源链条。该账号疑似转发/聚合型，独立性存疑。", "filter_trace": "{\"independence\": \"单源单账号，payload 内无第二独立来源印证；「沙盘」类账号多为转发聚合，原创独立性不足。\", \"quality_density\": \"低——仅标题级断言，正文未留存，无时间/地点/机型核验/官方或OSINT佐证，信息密度不足以支撑该量级战果主张。\", \"recency\": \"标注6.28，时效新；但快变地缘主题下单源战果类主张极易被后续修正或证伪。\"}", "debate_trace": null, "credibility_id": "cred-2d3b21961267", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-baa2a4619ead", "facet": null, "proposition": "小红书博主「老金」于6.28断言：乌克兰单日有3架米格-29战机被摧毁（仅卡片级证据，正文未留存，无支撑细节）。", "claim_kind": "rumor", "source_kind": "post", "single_source_ref_id": "src-baa2a4619ead", "source_ref_ids": "[\"src-baa2a4619ead\"]", "verbatim_excerpt": "乌克兰一日3架米格29被摧毁", "cached_text_hash": "b1813232ce21ddc44860f7f3db56d6340cd358c2f3a3ab24f136444bed94d170", "analysis_note": "卡片级证据：仅有标题与互动元数据，正文未抓取。属「沙盘」类日更军情自媒体的单方战果断言，未经独立核实，无具体时间/地点/损失机制/来源链条。该账号疑似转发/聚合型，独立性存疑。", "filter_trace": "{\"independence\": \"单源单账号，payload 内无第二独立来源印证；「沙盘」类账号多为转发聚合，原创独立性不足。\", \"quality_density\": \"低——仅标题级断言，正文未留存，无时间/地点/机型核验/官方或OSINT佐证，信息密度不足以支撑该量级战果主张。\", \"recency\": \"标注6.28，时效新；但快变地缘主题下单源战果类主张极易被后续修正或证伪。\"}", "debate_trace": null, "credibility_id": "cred-dab9d1f9acf1", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": n