INSERT INTO "knowledge_change_log" VALUES(390,'l3_claim','sc-d4fd7651d27d','*','update','{"id": "sc-d4fd7651d27d", "facet": null, "proposition": "制裁背景下俄罗斯药品国产化率显著上升（标题称国产药占比 63%，并提及 86% 的另一组数据但被截断），呈现医药自给趋势。", "claim_kind": "data", "source_kind": "post", "single_source_ref_id": "src-d4fd7651d27d", "source_ref_ids": "[\"src-d4fd7651d27d\"]", "verbatim_excerpt": "制裁下的俄罗斯：国产药占 63%，86%药品实", "cached_text_hash": "50e1d9f88a3944fc2698d286784e2658b530893ff9be1dafa9efedb3a32b5f01", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅有标题与互动数据；标题在「86%药品实」处被截断，第二组数据不完整。该数字无原始出处与支撑细节，可信度受限，建议后续凭已留存的 xsec_token 重抓正文核验。", "filter_trace": "{\"independence\": \"单条小红书笔记，无独立佐证来源。\", \"quality_density\": \"极低——仅有截断标题与点赞/评论数，正文缺失，无细节、无可证伪信息。\", \"recency\": \"标题与卡片未标注发布/数据时间，无法判断时效。\"}", "debate_trace": null, "credibility_id": "cred-37d8673d011e", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-d4fd7651d27d", "facet": null, "proposition": "制裁背景下俄罗斯药品国产化率显著上升（标题称国产药占比 63%，并提及 86% 的另一组数据但被截断），呈现医药自给趋势。", "claim_kind": "data", "source_kind": "post", "single_source_ref_id": "src-d4fd7651d27d", "source_ref_ids": "[\"src-d4fd7651d27d\"]", "verbatim_excerpt": "制裁下的俄罗斯：国产药占 63%，86%药品实", "cached_text_hash": "50e1d9f88a3944fc2698d286784e2658b530893ff9be1dafa9efedb3a32b5f01", "analysis_note": "卡片级证据：正文未抓取以规避风控，仅有标题与互动数据；标题在「86%药品实」处被截断，第二组数据不完整。该数字无原始出处与支撑细节，可信度受限，建议后续凭已留存的 xsec_token 重抓正文核验。", "filter_trace": "{\"independence\": \"单条小红书笔记，无独立佐证来源。\", \"quality_density\": \"极低——仅有截断标题与点赞/评论数，正文缺失，无细节、无可证伪信息。\", \"recency\": \"标题与卡片未标注发布/数据时间，无法判断时效。\"}", "debate_trace": null, "credibility_id": "cred-36ed4df0d320", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-