INSERT INTO "knowledge_change_log" VALUES(394,'l3_claim','sc-dbe9c95547e7','*','update','{"id": "sc-dbe9c95547e7", "facet": null, "proposition": "一条小红书热门笔记(约5千赞、800+评论)以「在乌克兰的女孩」第一人称视角呈现其个人眼中的乌克兰现状,提供了当事人主观体验侧的民间视角;正文按风控策略未抓取(仅卡片级证据)。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-dbe9c95547e7", "source_ref_ids": "[\"src-dbe9c95547e7\"]", "verbatim_excerpt": "一个乌克兰女孩视角下的乌克兰现状(点赞5046 评论822)", "cached_text_hash": "08a765c4970806ab8091ec794f53895e577509cd1ad04faca96c1d7b49a9eaee", "analysis_note": "卡片级证据:仅留存标题/作者/互动数与xsec_token,正文未抓取。因此只能蒸馏出该笔记的「定位/框架」——当事人主观视角的民间表达——而无法对其正文内的具体事实主张做可信度判断。高互动数反映传播热度,不代表信息密度或独立性。", "filter_trace": "{\"independence\": \"单一小红书个人账号,无独立来源;高赞/高评论属传播热度而非独立性\", \"quality_density\": \"正文缺失,仅卡片元数据,信息密度低,无可证伪的具体细节\", \"recency\": \"标注为「现状」类内容,但无发布时间戳,时效性无法确认\"}", "debate_trace": null, "credibility_id": "cred-23ad0efcb2ee", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-dbe9c95547e7", "facet": null, "proposition": "一条小红书热门笔记(约5千赞、800+评论)以「在乌克兰的女孩」第一人称视角呈现其个人眼中的乌克兰现状,提供了当事人主观体验侧的民间视角;正文按风控策略未抓取(仅卡片级证据)。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-dbe9c95547e7", "source_ref_ids": "[\"src-dbe9c95547e7\"]", "verbatim_excerpt": "一个乌克兰女孩视角下的乌克兰现状(点赞5046 评论822)", "cached_text_hash": "08a765c4970806ab8091ec794f53895e577509cd1ad04faca96c1d7b49a9eaee", "analysis_note": "卡片级证据:仅留存标题/作者/互动数与xsec_token,正文未抓取。因此只能蒸馏出该笔记的「定位/框架」——当事人主观视角的民间表达——而无法对其正文内的具体事实主张做可信度判断。高互动数反映传播热度,不代表信息密度或独立性。", "filter_trace": "{\"independence\": \"单一小红书个人账号,无独立来源;高赞/高评论属传播热度而非独立性\", \"quality_density\": \"正文缺失,仅卡片元数据,信息密度低,无可证伪的具体细节\", \"recency\": \"标注为「现状」类内容,但无发布时间戳,时效性无法确认\"}", "debate_trace": null, "credibility_id": "cred-efc70a5ed875", "parent_l2_id": null, "lifecycle": null, "status": "activ