INSERT INTO "knowledge_change_log" VALUES(398,'l3_claim','sc-e4fdde487c76','*','update','{"id": "sc-e4fdde487c76", "facet": null, "proposition": "普京表示俄罗斯当前正处于一个命运攸关的关键时刻。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-e4fdde487c76", "source_ref_ids": "[\"src-e4fdde487c76\"]", "verbatim_excerpt": "普京：俄罗斯正面临命运攸关时刻", "cached_text_hash": "80b50b456fe9348709d46798f45fae5f9beff0238ca49a4d028ee8db71ddd804", "analysis_note": "卡片级证据：澎湃新闻在小红书的聚合帖，正文为规避风控未抓取，xsec_token 已留存可追溯。本主张仅由标题蒸馏而来，缺乏正文细节与发言场合/时间等上下文支撑，需后续抓取或印证补强。", "filter_trace": "{\"independence\": \"单一来源：澎湃新闻经小红书聚合，非一手原始报道，真正一手出处（普京发言场合/时间）缺失\", \"quality_density\": \"低密度：正文未抓取，仅标题+互动数据（点赞265/评论30），无可证伪细节与上下文\", \"recency\": \"快变地缘政治主题，标题级陈述时效性强，需后续多源印证防止过期\"}", "debate_trace": null, "credibility_id": "cred-ef8b13987d4b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-e4fdde487c76", "facet": null, "proposition": "普京表示俄罗斯当前正处于一个命运攸关的关键时刻。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-e4fdde487c76", "source_ref_ids": "[\"src-e4fdde487c76\"]", "verbatim_excerpt": "普京：俄罗斯正面临命运攸关时刻", "cached_text_hash": "80b50b456fe9348709d46798f45fae5f9beff0238ca49a4d028ee8db71ddd804", "analysis_note": "卡片级证据：澎湃新闻在小红书的聚合帖，正文为规避风控未抓取，xsec_token 已留存可追溯。本主张仅由标题蒸馏而来，缺乏正文细节与发言场合/时间等上下文支撑，需后续抓取或印证补强。", "filter_trace": "{\"independence\": \"单一来源：澎湃新闻经小红书聚合，非一手原始报道，真正一手出处（普京发言场合/时间）缺失\", \"quality_density\": \"低密度：正文未抓取，仅标题+互动数据（点赞265/评论30），无可证伪细节与上下文\", \"recency\": \"快变地缘政治主题，标题级陈述时效性强，需后续多源印证防止过期\"}", "debate_trace": null, "credibility_id": "cred-dea582a035f5", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 12:40:37", "update