INSERT INTO "knowledge_change_log" VALUES(401,'l3_claim','sc-f26d039d177f','*','update','{"id": "sc-f26d039d177f", "facet": null, "proposition": "油价持续下跌、霍尔木兹海峡滞留油轮恢复通行、且伊朗据报正寻求新买家并扩大对亚洲的石油出口——这些供应增加的迹象共同对高度依赖石油收入的俄罗斯构成财政压力。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-f26d039d177f", "source_ref_ids": "[\"src-f26d039d177f\"]", "verbatim_excerpt": "The price of oil continues to fall, and an increasing number of previously stalled oil tankers are passing through the Strait of Hormuz.", "cached_text_hash": "9f436dc9a51c2037cfe8819f52793407d22f06e5538d2afc81b17060040f3ad8", "analysis_note": "该推文将三个可观察的市场/地缘事件(油价下跌、海峡油轮疏通、伊朗扩大对亚原油出口)组合并解读为''对俄罗斯的坏消息'',核心是因果推断而非单纯事实陈述。cached_text 在''Asian''处被截断,完整推文可能含更多细节。", "filter_trace": "{\"independence\": \"单条 X 推文,据称引自未具名''media reports'',无可对照的独立来源,独立性偏低。\", \"quality_density\": \"含具体要素(霍尔木兹海峡、油轮、伊朗对亚洲出口),但文本在''Asian''处截断,密度中等。\", \"recency\": \"油价与地缘事件属快变量,时效性强,来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-8ebff402de30", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f26d039d177f", "facet": null, "proposition": "油价持续下跌、霍尔木兹海峡滞留油轮恢复通行、且伊朗据报正寻求新买家并扩大对亚洲的石油出口——这些供应增加的迹象共同对高度依赖石油收入的俄罗斯构成财政压力。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-f26d039d177f", "source_ref_ids": "[\"src-f26d039d177f\"]", "verbatim_excerpt": "The price of oil continues to fall, and an increasing number of previously stalled oil tankers are passing through the Strait of Hormuz.", "cached_text_hash": "9f436dc9a51c2037cfe8819f52793407d22f06e5538d2afc81b17060040f3ad8", "analysis_note": "该推文将三个可观察的市场/地缘事件(油价下跌、海峡油轮疏通、伊朗扩大对亚原油出口)组合并解读为''对俄罗斯的坏消息'',核心是因果推断而非单纯事实陈述。cached_text 在''Asian''处被截断,完整推文可能含更多细节。", "filter_trace": "{\"independence\": \"单条 X 推文,据称引自未具名''media reports'',无可对照的独立来源,独立性偏低。\", \"quality_density\": \"含具体要素(霍尔木兹海峡、油轮、伊朗对亚洲出口),但文本在''Asian''处截断,密度中等。\", \"recency\": \"油价与地缘事件属快变量,时效性强,来源易过期。\"}", "debate_trace": null, "credibility_id": "cred-41e57d9dfe4c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 12:40:37',NULL);
INSERT INTO "knowledge_change_log" VALUES(402,'l3_claim','sc-f29686317a53','*','update','{"id": "sc-f29686317a53", "facet": null, "proposition": "认为卢比奥的对俄举措使俄罗斯重陷被动，普京的外交期望随之落空。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-f29686317a53", "source_ref_ids": "[\"src-f29686317a53\"]", "verbatim_excerpt": "卢比奥，将俄罗斯打回原型，普京希望破灭！", "cached_text_hash": "2123d13fd9fbc6407cde20177e7a5c8b5dd09950d330d9190c334d34c723429f", "analysis_note": "卡片级证据：正文未抓取以规避风控，蒸馏仅基于标题/作者/互动数据；来源为低互动（91赞0评）的评论性笔记，标题为情绪化表述，无可证伪的细节或数据。", "filter_trace": "{\"independence\": \"单条笔记，无其他独立来源交叉印证；账号为个人自媒体。\", \"quality_density\": \"正文未抓取，仅有情绪化标题，无可证伪细节、数据或具体事实，信息密度低。\", \"recency\": \"快变地缘政治主题，笔记无明确时间戳，主张时效性不确定。\"}", "debate_trace": null, "credibility_id": "cred-1442685b8fb9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:05:45", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f29686317a53", "facet": null, "proposition": "认为卢比奥的对俄举措使俄罗斯重陷被动，普京的外交期望随之落空。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-f29686317a53", "source_ref_ids": "[\"src-f29686317a53\"]", "verbatim_excerpt": "卢比奥，将俄罗斯打回原型，普京希望破灭！", "cached_text_hash": "2123d13fd9fbc6407cde20177e7a5c8b5dd09950d330d9190c334d34c723429f", "analysis_note": "卡片级证据：正文未抓取以规避风控，蒸馏仅基于标题/作者/互动数据；来源为低互动（91赞0评）的评论性笔记，标题为情绪化表述，无可证伪的细节或数据。", "filter_trace": "{\"independence\": \"单条笔记，无其他独立来源交叉印证；账号为个人自媒体。\", \"quality_density\": \"正文未抓取，仅有情绪化标题，无可证伪细节、数据或具体事实，信息密度低。\", \"recency\": \"快变地缘政治主题，笔记无明确时间戳，主张时效性不确定。\"}", "debate_trace": null, "credibility_id": "cred-7a17efc8856a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:05:45", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=opinio