INSERT INTO "knowledge_change_log" VALUES(404,'l3_claim','sc-f86f0a02b7bb','*','update','{"id": "sc-f86f0a02b7bb", "facet": null, "proposition": "俄罗斯2024–2025年的经济增长由战时国防开支驱动（2025年联邦国防预算约15.5万亿卢布、占GDP 7.2%），但建立在脆弱基础之上：世界银行2025秋季预测显示实际GDP增速较2024年4.3%放缓，央行维持紧缩政策对抗顽固通胀，且军事动员与移民外流造成严重劳动力短缺。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-f86f0a02b7bb", "source_ref_ids": "[\"src-f86f0a02b7bb\"]", "verbatim_excerpt": "2025年联邦预算国防开支15.5万亿卢布(约1600亿美元)占GDP 7.2%", "cached_text_hash": "3ae180f30d7c91b6b5a230f1b30c2e8330af4b4f977fe8cc01a22f6c1ae1034a", "analysis_note": "该文为智库分析框架，将宏观硬数据（国防开支/GDP占比、世界银行增速预测、劳动力短缺）解读为''增长不可持续''的判断；硬数据本身可证伪、可独立核验，但''脆弱基础''属编辑性结论而非硬事实。", "filter_trace": "{\"independence\": \"单一来源(Vision of Humanity)，但底层引用世界银行预测等独立机构数据\", \"quality_density\": \"高——含具体可证伪数字(15.5万亿卢布、占GDP 7.2%、4.3%→放缓)\", \"recency\": \"当期/2025秋季数据，地缘快变主题下时效性强且仍有效\"}", "debate_trace": null, "credibility_id": "cred-aa64959f8b08", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:05:45", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-f86f0a02b7bb", "facet": null, "proposition": "俄罗斯2024–2025年的经济增长由战时国防开支驱动（2025年联邦国防预算约15.5万亿卢布、占GDP 7.2%），但建立在脆弱基础之上：世界银行2025秋季预测显示实际GDP增速较2024年4.3%放缓，央行维持紧缩政策对抗顽固通胀，且军事动员与移民外流造成严重劳动力短缺。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-f86f0a02b7bb", "source_ref_ids": "[\"src-f86f0a02b7bb\"]", "verbatim_excerpt": "2025年联邦预算国防开支15.5万亿卢布(约1600亿美元)占GDP 7.2%", "cached_text_hash": "3ae180f30d7c91b6b5a230f1b30c2e8330af4b4f977fe8cc01a22f6c1ae1034a", "analysis_note": "该文为智库分析框架，将宏观硬数据（国防开支/GDP占比、世界银行增速预测、劳动力短缺）解读为''增长不可持续''的判断；硬数据本身可证伪、可独立核验，但''脆弱基础''属编辑性结论而非硬事实。", "filter_trace": "{\"independence\": \"单一来源(Vision of Humanity)，但底层引用世界银行预测等独立机构数据\", \"quality_density\": \"高——含具体可证伪数字(15.5万亿卢布、占GDP 7.2%、4.3%→放缓)\", \"recency\": \"当期/2025秋季数据，地缘快变主题下时效性强且仍有效\"}", "debate_trace": null, "credibility_id": "cred-aaae5d3a9afd", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 12:40:37',NULL);
