INSERT INTO "knowledge_change_log" VALUES(407,'l2_finding','sf-65fcae87d5e1','*','update','{"id": "sf-65fcae87d5e1", "facet": "_unfileted", "finding_type": "fact", "statement": "西方对俄能源制裁持续生效并压制俄石油收入：美国恢复对俄石油制裁，2025年西方能源制裁使俄石油收入同比下降约20%、乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队承压；另有来源泛指欧盟对俄实施经济制裁。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 3, "cross_platform_count": 2, "corroboration_sources": "[\"xiaohongshu\", \"web\"]", "conflict_note": null, "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\"]", "credibility_id": "cred-16ab146de0a9", "l3_ids": "[\"sc-04b976e998b7\", \"sc-35b5b46bb66f\", \"sc-41e03bc94a1d\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:13:31", "updated_by": "condense-aggregate", "audit_note": null}','{"id": "sf-65fcae87d5e1", "facet": "_unfileted", "finding_type": "fact", "statement": "西方对俄能源制裁持续生效并压制俄石油收入：美国恢复对俄石油制裁，2025年西方能源制裁使俄石油收入同比下降约20%、乌拉尔原油相对布伦特折价扩大至每桶逾24美元，影子舰队承压；另有来源泛指欧盟对俄实施经济制裁。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 3, "cross_platform_count": 2, "corroboration_sources": "[\"xiaohongshu\", \"web\"]", "conflict_note": null, "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\"]", "credibility_id": "cred-6f58eb685b88", "l3_ids": "[\"sc-04b976e998b7\", \"sc-35b5b46bb66f\", \"sc-41e03bc94a1d\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-aggregate", "audit_note": null}','type=fact corrob=3/2','condense-aggregate','2026-06-29 12:43:20',NULL);
