INSERT INTO "knowledge_change_log" VALUES(419,'l2_finding','sf-ba4f38adf1c9','*','update','{"id": "sf-ba4f38adf1c9", "facet": "_unfileted", "finding_type": "event", "statement": "俄罗斯与乌克兰在 2025 年维持活跃的停火/谈判轨道：4–6 月两轮伊斯坦布尔谈判仅就战俘交换达成一致而未突破；俄方 6 月备忘录向乌方提供两种 30 天停火方案（其一要求重大让步，据 Chatham House 分析含乌克兰正式放弃加入北约）；俄方并提议双方互限对纵深目标的打击；乌方（泽连斯基致普京公开信）亦有外交动作。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 4, "cross_platform_count": 2, "corroboration_sources": "[\"web\", \"xiaohongshu\"]", "conflict_note": null, "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\"]", "credibility_id": "cred-a8816b2bd40b", "l3_ids": "[\"sc-7bcb95db7c9e\", \"sc-65378bb4a0ce\", \"sc-88448fc33f10\", \"sc-6a4598c1b723\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:13:31", "updated_by": "condense-aggregate", "audit_note": null}','{"id": "sf-ba4f38adf1c9", "facet": "_unfileted", "finding_type": "event", "statement": "俄罗斯与乌克兰在 2025 年维持活跃的停火/谈判轨道：4–6 月两轮伊斯坦布尔谈判仅就战俘交换达成一致而未突破；俄方 6 月备忘录向乌方提供两种 30 天停火方案（其一要求重大让步，据 Chatham House 分析含乌克兰正式放弃加入北约）；俄方并提议双方互限对纵深目标的打击；乌方（泽连斯基致普京公开信）亦有外交动作。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 4, "cross_platform_count": 2, "corroboration_sources": "[\"web\", \"xiaohongshu\"]", "conflict_note": null, "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\"]", "credibility_id": "cred-9e735c024f21", "l3_ids": "[\"sc-7bcb95db7c9e\", \"sc-65378bb4a0ce\", \"sc-88448fc33f10\", \"sc-6a4598c1b723\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-aggregate", "au