INSERT INTO "knowledge_change_log" VALUES(449,'l2_finding','sf-08d37cf2d5b6','*','update','{"id": "sf-08d37cf2d5b6", "facet": "_unfileted", "finding_type": "trend", "statement": "俄罗斯2024–2025年经济呈现战时国防开支驱动但脆弱的增长：2025年联邦国防预算约15.5万亿卢布(占GDP约7.2%)，世界银行2025秋季预测实际GDP增速较2024年4.3%放缓，央行紧缩对抗顽固通胀，动员与移民外流造成严重劳动力短缺；叠加油价下跌、霍尔木兹海峡油轮恢复通行及伊朗扩大对亚洲石油出口带来的供应增加，对高度依赖石油收入的俄财政构成外部压力。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 2, "cross_platform_count": 2, "corroboration_sources": "[\"web\", \"x\"]", "conflict_note": null, "source_ref_ids": "[\"src-f86f0a02b7bb\", \"src-f26d039d177f\"]", "credibility_id": "cred-1e1a1604fa56", "l3_ids": "[\"sc-f86f0a02b7bb\", \"sc-f26d039d177f\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:13:31", "updated_by": "condense-aggregate", "audit_note": null}','{"id": "sf-08d37cf2d5b6", "facet": "_unfileted", "finding_type": "trend", "statement": "俄罗斯2024–2025年经济呈现战时国防开支驱动但脆弱的增长：2025年联邦国防预算约15.5万亿卢布(占GDP约7.2%)，世界银行2025秋季预测实际GDP增速较2024年4.3%放缓，央行紧缩对抗顽固通胀，动员与移民外流造成严重劳动力短缺；叠加油价下跌、霍尔木兹海峡油轮恢复通行及伊朗扩大对亚洲石油出口带来的供应增加，对高度依赖石油收入的俄财政构成外部压力。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 2, "cross_platform_count": 2, "corroboration_sources": "[\"web\", \"x\"]", "conflict_note": null, "source_ref_ids": "[\"src-f86f0a02b7bb\", \"src-f26d039d177f\"]", "credibility_id": "cred-33645658e50d", "l3_ids": "[\"sc-f86f0a02b7bb\", \"sc-f26d039d177f\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:13:31", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-aggregate", "audit_note": null}','type=trend corrob=2/2','condense-aggregate','2026-06-29 12:43:20',NULL);
