INSERT INTO "knowledge_change_log" VALUES(462,'l1_viewpoint','vp-6cddb0826fc0','*','update','{"id": "vp-6cddb0826fc0", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "俄罗斯战时经济是本主题最显著的张力点，存在两种难以调和的叙事。韧性叙事以小红书观点（「制裁下反而越来越富」「罗斯福式国家动员」）与俄方「仍增长约1%、结构耗竭论被夸大」论调呈现；承压叙事则由 web 端智库将 2026 军费下调预算定性为「非胜利预算/受控停滞」、Adam Tooze 将其定性为脆弱的「纸牌屋」，并由普京承认国内能源紧张、莫斯科约四成汽油断供等信号共同支撑。硬数据层面：2025 年联邦国防预算约 15.5 万亿卢布（占 GDP 约 7.2%），油价下跌与外部供应增加压制石油收入，乌拉尔原油相对布伦特折价扩大至逾 24 美元/桶，叠加重动员与移民外流造成的劳动力短缺。两种叙事并存——制裁确实在压制收入并制造燃料短缺，但短期增长尚存；真正的分歧在于「耐久性」的时间尺度。", "stance": "contested", "l2_ids": "[\"sf-65fcae87d5e1\", \"sf-b98ecb1db8a1\", \"sf-22b41160809b\", \"sf-08d37cf2d5b6\", \"sf-13fb8f5483ad\", \"sf-d798959130a9\", \"sf-272bf447056b\"]", "open_questions": "[\"俄战时经济在 2026 财年是进入「受控停滞」还是仍能支撑战争——需更权威的财政赤字、通胀与劳动力数据以裁决两种叙事\", \"制裁对俄石油收入与燃料供给的实际量化影响，独立于中文社媒转述的来源核验\"]", "confidence": "medium", "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\", \"src-02c2a9805a91\", \"src-3fdc904ca23a\", \"src-57716a69cc86\", \"src-892677e1d3e1\", \"src-7e38f8f1c038\", \"src-8e691f9c959f\", \"src-5ced799861a4\", \"src-7434fb7500ab\", \"src-f86f0a02b7bb\", \"src-f26d039d177f\", \"src-f89329c832ec\", \"src-fbe09c63a68a\", \"src-3d42acbf1ed2\", \"src-3406f384a8d2\", \"src-5a2a337a9bc0\", \"src-848bff010797\"]", "credibility_id": "cred-74a5275a5168", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-6cddb0826fc0", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "俄罗斯战时经济是本主题最显著的张力点，存在两种难以调和的叙事。韧性叙事以小红书观点（「制裁下反而越来越富」「罗斯福式国家动员」）与俄方「仍增长约1%、结构耗竭论被夸大」论调呈现；承压叙事则由 web 端智库将 2026 军费下调预算定性为「非胜利预算/受控停滞」、Adam Tooze 将其定性为脆弱的「纸牌屋」，并由普京承认国内能源紧张、莫斯科约四成汽油断供等信号共同支撑。硬数据层面：2025 年联邦国防预算约 15.5 万亿卢布（占 GDP 约 7.2%），油价下跌与外部供应增加压制石油收入，乌拉尔原油相对布伦特折价扩大至逾 24 美元/桶，叠加重动员与移民外流造成的劳动力短缺。两种叙事并存——制裁确实在压制收入并制造燃料短缺，但短期增长尚存；真正的分歧在于「耐久性」的时间尺度。", "stance": "contested", "l2_ids": "[\"sf-65fcae87d5e1\", \"sf-b98ecb1db8a1\", \"sf-22b41160809b\", \"sf-08d37cf2d5b6\", \"sf-13fb8f5483ad\", \"sf-d798959130a9\", \"sf-272bf447056b\"]", "open_questions": "[\"俄战时经济在 2026 财年是进入「受控停滞」还是仍能支撑战争——需更权威的财政赤字、通胀与劳动力数据以裁决两种叙事\", \"制裁对俄石油收入与燃料供给的实际量化影响，独立于中文社媒转述的来源核验\"]", "confidence": "medium", "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\", \"src-02c2a9805a91\", \"src-3fdc904ca23a\", \"src-57716a69cc86\", \"src-892677e1d3e1\", \"src-7e38f8f1c038\", \"src-8e691f9c959f\", \"src-5ced799861a4\", \"src-7434fb7500ab\", \"src-f86f0a02b7bb\", \"src-f26d039d177f\", \"src-f89329c832ec\", \"src-fbe09c63a68a\", \"src-3d42acbf1ed2\", \"src-3406f384a8d2\", \"src-5a2a337a9bc0\", \"src-848bff010797\"]", "credibility_id": "cred-2d87a8125c38", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:34", "updated_by": "condense-synthesize", "audit_note": null}','kind=contrarian stance=contested','condense-synthesize','2026-06-29 12:43:34',NULL);
INSERT INTO "knowledge_change_log" VALUES(463,'l1_viewpoint','vp-683c60abb678','*','update','{"id": "vp-683c60abb678", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "无人机已系统性地重塑战场形态：交战从传统前线转向由无人机覆盖的「灰色地带」，乌克兰无人机据多源信号有效瓦解俄南部后勤。攻防规模持续升级（报道一夜出动约 370 架的大规模袭击、莫斯科遭大规模无人机袭击），俄方纵深目标（圣彼得堡上空无人机、KAMAZ 卡车被毁等）亦受袭。乌方在实战部署具名系统——美制 GBU-39/B SDB 空袭前线阵地、「Sky Sentinel」遥控炮塔搭载 M2 重机枪专打 Shahed/Geran 自杀式无人机。需保留的张力：Sky Sentinel 效能存在争议（需实战验证、自身易受无人机攻击、自动化有误伤风险）。整体上「无人机主导」是本主题交叉印证最强的趋势之一，但不少事件报告缺地点/时间，且存在中国卖家以「乌克兰买家称赞」为自利营销、无独立核实的信号。", "stance": "established", "l2_ids": "[\"sf-07d94e42e19d\", \"sf-a7f7e24ba7f5\", \"sf-848488e3bebb\", \"sf-29c6fb7c6d01\", \"sf-ccc25f6be903\", \"sf-580bde168440\", \"sf-40c240b2be05\"]", "open_questions": "[\"大规模无人机袭击（如 370 架）的方向、目标与战果的可核验细节\", \"Sky Sentinel 等反无人机系统的实战效能是否如宣称，需独立战果数据\"]", "confidence": "medium", "source_ref_ids": "[\"src-144db63a9d52\", \"src-326d91c55f3a\", \"src-2e92529ce93e\", \"src-2f3f0e2fad11\", \"src-29df650e0cd9\", \"src-190ce3895a76\", \"src-93f49315a162\", \"src-d1ce88d68a88\", \"src-90ce42415df6\", \"src-4e893ca84bd7\", \"src-4f82a42b4c15\", \"src-180403731046\", \"src-0b92b07afbcd\", \"src-887e067cdfeb\"]", "credibility_id": "cred-76361ce8bbf3", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-683c60abb678", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "无人机已系统性地重塑战场形态：交战从传统前线转向由无人机覆盖的「灰色地带」，乌克兰无人机据多源信号有效瓦解俄南部后勤。攻防规模持续升级（报道一夜出动约 370 架的大规模袭击、莫斯科遭大规模无人机袭击），俄方纵深目标（圣彼得堡上空无人机、KAMAZ 卡车被毁等）亦受袭。乌方在实战部署具名系统——美制 GBU-39/B SDB 空袭前线阵地、「Sky Sentinel」遥控炮塔搭载 M2 重机枪专打 Shahed/Geran 自杀式无人机。需保留的张力：Sky Sentinel 效能存在争议（需实战验证、自身易受无人机攻击、自动化有误伤风险）。整体上「无人机主导」是本主题交叉印证最强的趋势之一，但不少事件报告缺地点/时间，且存在中国卖家以「乌克兰买家称赞」为自利营销、无独立核实的信号。", "stance": "established", "l2_ids": "[\"sf-07d94e42e19d\", \"sf-a7f7e24ba7f5\", \"sf-848488e3bebb\", \"sf-29c6fb7c6d01\", \"sf-ccc25f6be903\", \"sf-580bde168440\", \"sf-40c240b2be05\"]", "open_questions": "[\"大规模无人机袭击（如 370 架）的方向、目标与战果的可核验细节\", \"Sky Sentinel 等反无人机系统的实战效能是否如宣称，需独立战果数据\"]", "confidence": "medium", "source_ref_ids": "[\"src-144db63a9d52\", \"src-326d91c55f3a\", \"src-2e92529ce93e\", \"src-2f3f0e2fad11\", \"src-29df650e0cd9\", \"src-190ce3895a76\", \"src-93f49315a162\", \"src-d1ce88d68a88\", \"src-90ce42415df6\", \"src-4e893ca84bd7\", \"src-4f82a42b4c15\", \"src-180403731046\", \"src-0b92b07afbcd\", \"src-887e067cdfeb\"]", "credibility_id": "cred-b0d3a77af821", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:34", "updated_by": "condense-synthesize", "audit_note": null}','kind=theme stance=established','condense-synthesize','2026-06-29 12:43:34',NULL);
INSERT INTO "knowledge_change_log" VALUES(464,'l1_viewpoint','vp-e53eb581d605','*','update','{"id": "vp-e53eb581d605", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "viewpoint", "narrative": "乌克兰得以持续抵抗的核心支撑被多源归纳为西方援助+不对称作战：web 端梳理 2022–24 年欧盟及成员国逾 1450 亿美元援助、军援从便携系统升级为 HIMARS/爱国者/F-16 并叠加本土（尤其无人机）创新，小红书侧以「不对称作战」「乌经济未崩溃」同向佐证。但该视角存在显著薄弱点：西方军援供应链出现断档（F-16 曾连续三周以上无法获得美制导弹，致其难以击落俄无人机与导弹），暗示援助并非无缝；同时一条亲俄叙事直接断言俄已占领 Kostyantynivka 与 Lyman 并将包围 Slovyansk/Kramatorsk、控制整个顿巴斯，并称「乌以无人机攻势击败俄」系捏造——这与无人机主导叙事正面对立，且为单一来源、无独立佐证。中文社媒中「乌为何能坚持」关注度高但正文多未抓取，论点不可核验。", "stance": "emerging", "l2_ids": "[\"sf-ae3187333e8a\", \"sf-df6e40fd3e22\", \"sf-77f0a6b01648\", \"sf-404390f2702d\"]", "open_questions": "[\"西方军援供应链断档（F-16 导弹）是临时物流问题还是结构性缺口\", \"亲俄叙事声称的顿巴斯占领进展（Kostyantynivka/Lyman/包围 Slovyansk-Kramatorsk）是否有独立地理佐证，还是宣传\"]", "confidence": "low", "source_ref_ids": "[\"src-5e652caee352\", \"src-6b4af507be01\", \"src-804693cbd100\", \"src-43f57fedfa87\", \"src-054ba6dc7d00\", \"src-229fef399f44\", \"src-3fd6ca20c26e\", \"src-3a6bff93c0af\"]", "credibility_id": "cred-08f00352942e", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-e53eb581d605", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "viewpoint", "narrative": "乌克兰得以持续抵抗的核心支撑被多源归纳为西方援助+不对称作战：web 端梳理 2022–24 年欧盟及成员国逾 1450 亿美元援助、军援从便携系统升级为 HIMARS/爱国者/F-16 并叠加本土（尤其无人机）创新，小红书侧以「不对称作战」「乌经济未崩溃」同向佐证。但该视角存在显著薄弱点：西方军援供应链出现断档（F-16 曾连续三周以上无法获得美制导弹，致其难以击落俄无人机与导弹），暗示援助并非无缝；同时一条亲俄叙事直接断言俄已占领 Kostyantynivka 与 Lyman 并将包围 Slovyansk/Kramatorsk、控制整个顿巴斯，并称「乌以无人机攻势击败俄」系捏造——这与无人机主导叙事正面对立，且为单一来源、无独立佐证。中文社媒中「乌为何能坚持」关注度高但正文多未抓取，论点不可核验。", "stance": "emerging", "l2_ids": "[\"sf-ae3187333e8a\", \"sf-df6e40fd3e22\", \"sf-77f0a6b01648\", \"sf-404390f2702d\"]", "open_questions": "[\"西方军援供应链断档（F-16 导弹）是临时物流问题还是结构性缺口\", \"亲俄叙事声称的顿巴斯占领进展（Kostyantynivka/Lyman/包围 Slovyansk-Kramatorsk）是否有独立地理佐证，还是宣传\"]", "confidence": "low", "source_ref_ids": "[\"src-5e652caee352\", \"src-6b4af507be01\", \"src-804693cbd100\", \"src-43f57fedfa87\", \"src-054ba6dc7d00\", \"src-229fef399f44\", \"src-3fd6ca20c26e\", \"src-3a6bff93c0af\"]", "credibility_id": "cred-2f92a442cd38", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:34", "updated_by": "condense-synthesize", "audit_note": null}','kind=viewpoint stance=emerging','condense-synthesize','2026-06-29 12:43:34',NULL);
INSERT INTO "knowledge_change_log" VALUES(465,'l1_viewpoint','vp-5931fc0994d1','*','update','{"id": "vp-5931fc0994d1", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "2025 年俄乌维持着活跃但未突破的外交/谈判轨道：4–6 月两轮伊斯坦布尔谈判仅就战俘交换达成一致；俄方 6 月备忘录提出两种 30 天停火方案（其一要求重大让步，据 Chatham House 分析含乌正式放弃入北约）并提议互限纵深打击，乌方泽连斯基以公开信等方式回应。领土是谈判的核心硬骨头：普京反复要求乌为库尔斯克攻势付出领土代价、夺取相关土地建「安全区」，并警告乌将「永久失去领土」；库尔斯克攻势本身（2024 年 8 月约 1.1 万人、峰值控制约 1000 平方公里、2025 年初俄反攻缩至约四分之一）形成的俄方缓冲分量不足以充当迫使乌让出顿巴斯的筹码。与此同时，特朗普/美方 11–12 月和平方案要求基辅割让领土（冻结赫尔松与扎波罗热前线、乌军从所控顿涅茨克撤出、限制乌军规模、禁入北约），CSIS 评其「亲俄且过于模糊」，泽连斯基提出反提案。需保留的张力：该轨道信息密度高但真伪混杂——「普京称停火需中国安全担保」为单一小红书转述、「卢比奥使俄被动」为单一评论性观点，均不可核验。", "stance": "contested", "l2_ids": "[\"sf-ba4f38adf1c9\", \"sf-c1d0fde47d96\", \"sf-5e31241587f7\", \"sf-d92e74d66c77\", \"sf-7cf4444be95c\", \"sf-7e3c60bd0b9d\", \"sf-bee4ded1202b\", \"sf-c01d40264b2e\", \"sf-a12d8362d9de\"]", "open_questions": "[\"伊斯坦布尔谈判与俄方备忘录之后，停火的真实前景与各方底线（领土、北约、军备上限）究竟为何\", \"普京「需中国安全担保」与「命运攸关时刻」等框架性言论是否属实及真实意图\"]", "confidence": "medium", "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\", \"src-2df254c71e7d\", \"src-334cc1ca247f\", \"src-5f6cd2d39ac2\", \"src-03ffbc1d6338\", \"src-b69eba4f1b93\", \"src-ad9cdb6444c8\", \"src-ab71ebaae693\", \"src-47d36b56c17f\", \"src-8d064e2faca7\", \"src-f29686317a53\", \"src-e4fdde487c76\"]", "credibility_id": "cred-42b0e9541b39", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-5931fc0994d1", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "2025 年俄乌维持着活跃但未突破的外交/谈判轨道：4–6 月两轮伊斯坦布尔谈判仅就战俘交换达成一致；俄方 6 月备忘录提出两种 30 天停火方案（其一要求重大让步，据 Chatham House 分析含乌正式放弃入北约）并提议互限纵深打击，乌方泽连斯基以公开信等方式回应。领土是谈判的核心硬骨头：普京反复要求乌为库尔斯克攻势付出领土代价、夺取相关土地建「安全区」，并警告乌将「永久失去领土」；库尔斯克攻势本身（2024 年 8 月约 1.1 万人、峰值控制约 1000 平方公里、2025 年初俄反攻缩至约四分之一）形成的俄方缓冲分量不足以充当迫使乌让出顿巴斯的筹码。与此同时，特朗普/美方 11–12 月和平方案要求基辅割让领土（冻结赫尔松与扎波罗热前线、乌军从所控顿涅茨克撤出、限制乌军规模、禁入北约），CSIS 评其「亲俄且过于模糊」，泽连斯基提出反提案。需保留的张力：该轨道信息密度高但真伪混杂——「普京称停火需中国安全担保」为单一小红书转述、「卢比奥使俄被动」为单一评论性观点，均不可核验。", "stance": "contested", "l2_ids": "[\"sf-ba4f38adf1c9\", \"sf-c1d0fde47d96\", \"sf-5e31241587f7\", \"sf-d92e74d66c77\", \"sf-7cf4444be95c\", \"sf-7e3c60bd0b9d\", \"sf-bee4ded1202b\", \"sf-c01d40264b2e\", \"sf-a12d8362d9de\"]", "open_questions": "[\"伊斯坦布尔谈判与俄方备忘录之后，停火的真实前景与各方底线（领土、北约、军备上限）究竟为何\", \"普京「需中国安全担保」与「命运攸关时刻」等框架性言论是否属实及真实意图\"]", "confidence": "medium", "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\", \"src-2df254c71e7d\", \"src-334cc1ca247f\", \"src-5f6cd2d39ac2\", \"src-03ffbc1d6338\", \"src-b69eba4f1b93\", \"src-ad9cdb6444c8\", \"src-ab71ebaae693\", \"src-47d36b56c17f\", \"src-8d064e2faca7\", \"src-f29686317a53\", \"src-e4fdde487c76\"]", "credibility_id": "cred-9c05855452f7", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:34", "updated_by": "condense-synthesize", "audit_note": null}','kind=theme stance=contested','condense-synthesize','2026-06-29 12:43:34',NULL);
INSERT INTO "knowledge_change_log" VALUES(466,'l1_viewpoint','vp-cd5684ba16aa','*','update','{"id": "vp-cd5684ba16aa", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "中文社媒（以小红书为主）是本主题一个体量不小但当前质量受限的覆盖面：它显示俄乌议题在中文受众中确有较高关注与互动——平民视角（未逃离乌平民生活、基辅生活现状、一家三口移民乌「是否后悔」）、跨境实务（从俄收汇讨论）、制裁合规梳理（受制裁产品清单）等。但本视角的方法论价值不在于已证实的事实，而在于暴露覆盖度/抓取缺口：大量笔记（@猎人战情室「俄乌沙盘」、《俄乌战争 2026 年 6 月》、福卡智库等）仅完成卡片级抓取、正文缺失，无法蒸馏出可印证主张；另有情绪化/悬念框架内容（「俄罗斯不希望你看到的数字」、士兵最后五分钟）真伪无法核实。这些条目说明下一步应优先补抓正文，而非据标题下结论。", "stance": "uncertain", "l2_ids": "[\"sf-e3dd91c87ed5\", \"sf-2544f98bca03\", \"sf-be0e44044da1\", \"sf-c76dde95a0f1\", \"sf-6eca83623fcc\", \"sf-2937acd89a3b\"]", "open_questions": "[\"小红书卡片级笔记补抓正文后，是否出现改变现有结论的新主张（覆盖度缺口待补）\", \"战时平民生活与跨境收汇等中文社媒内容是否含可印证的实质性信息\"]", "confidence": "low", "source_ref_ids": "[\"src-203e750d5c6f\", \"src-1197f691f12d\", \"src-f1c12cd19264\", \"src-2ed4b44997f4\", \"src-ea94b692a69d\", \"src-f8237ffa44ff\", \"src-e07623d8e4a3\", \"src-3d2bd074f154\", \"src-de1c80d16df0\", \"src-819b761634f4\", \"src-4a3e59ac95a9\", \"src-617e73ef09a7\", \"src-8082b83893a3\", \"src-888c6708efbf\"]", "credibility_id": "cred-6f04154e9072", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:20", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-cd5684ba16aa", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "中文社媒（以小红书为主）是本主题一个体量不小但当前质量受限的覆盖面：它显示俄乌议题在中文受众中确有较高关注与互动——平民视角（未逃离乌平民生活、基辅生活现状、一家三口移民乌「是否后悔」）、跨境实务（从俄收汇讨论）、制裁合规梳理（受制裁产品清单）等。但本视角的方法论价值不在于已证实的事实，而在于暴露覆盖度/抓取缺口：大量笔记（@猎人战情室「俄乌沙盘」、《俄乌战争 2026 年 6 月》、福卡智库等）仅完成卡片级抓取、正文缺失，无法蒸馏出可印证主张；另有情绪化/悬念框架内容（「俄罗斯不希望你看到的数字」、士兵最后五分钟）真伪无法核实。这些条目说明下一步应优先补抓正文，而非据标题下结论。", "stance": "uncertain", "l2_ids": "[\"sf-e3dd91c87ed5\", \"sf-2544f98bca03\", \"sf-be0e44044da1\", \"sf-c76dde95a0f1\", \"sf-6eca83623fcc\", \"sf-2937acd89a3b\"]", "open_questions": "[\"小红书卡片级笔记补抓正文后，是否出现改变现有结论的新主张（覆盖度缺口待补）\", \"战时平民生活与跨境收汇等中文社媒内容是否含可印证的实质性信息\"]", "confidence": "low", "source_ref_ids": "[\"src-203e750d5c6f\", \"src-1197f691f12d\", \"src-f1c12cd19264\", \"src-2ed4b44997f4\", \"src-ea94b692a69d\", \"src-f8237ffa44ff\", \"src-e07623d8e4a3\", \"src-3d2bd074f154\", \"src-de1c80d16df0\", \"src-819b761634f4\", \"src-4a3e59ac95a9\", \"src-617e73ef09a7\", \"src-8082b83893a3\", \"src-888c6708efbf\"]", "credibility_id": "cred-7de8715f9c28", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:22:23", "updated_at": "2026-06-29 12:43:34", "updated_by": "condense-synthesize", "audit_note": null}','kind=sub_question stance=uncertain','condense-synthesize','2026-06-29 12:43:34',NULL);
INSERT INTO "knowledge_change_log" VALUES(467,'l0_worldview','wv-ef03364758384dd9','*','update','{"id": "wv-ef03364758384dd9", "summary_kind": "tension", "proposition": "截至 2025–2026 年中，俄乌战争处于「军事僵持中的无人机化转型」与「外交谈判活跃但未突破」并存的张力状态：无人机已系统性重塑战场形态并成为乌方不对称优势的核心载体，但西方军援供应链出现断档、反无人机新系统效能待验；外交轨道（伊斯坦布尔谈判、俄方停火备忘录、美方割地方案）持续运转却卡在领土这一不可妥协的硬骨头上，普京以库尔斯克为由索取「安全区」领土。与之并行的最大认知张力在俄战时经济——制裁确在压制石油收入与制造燃料短缺，但短期增长尚存，「耐久性」时间尺度仍是开放分歧。中文社媒覆盖面虽广却大量正文未抓取，构成显著的覆盖度缺口，当前不足以据其下战场事实结论。", "scope": null, "key_findings": "[\"sf-22b41160809b\", \"sf-07d94e42e19d\", \"sf-ba4f38adf1c9\", \"sf-65fcae87d5e1\", \"sf-ae3187333e8a\", \"sf-08d37cf2d5b6\"]", "open_questions": "[\"俄战时经济 2026 财年走向「受控停滞」还是仍能支撑战争，需权威财政/通胀/劳动力数据裁决\", \"无人机大规模袭击与反无人机系统的实战战果需独立可核验细节\", \"特朗普方案与俄方备忘录之后，停火谈判的真实前景与各方在领土/北约/军备上限上的底线\", \"亲俄叙事声称的顿巴斯占领进展是否有独立地理佐证，抑或宣传\", \"西方军援供应链断档是临时还是结构性\", \"小红书卡片级笔记补抓正文后是否改变现有结论（覆盖度缺口）\"]", "confidence": "medium", "supersedes_id": "wv-ef03364758384dd9", "l1_ids": "[\"vp-6cddb0826fc0\", \"vp-683c60abb678\", \"vp-e53eb581d605\", \"vp-5931fc0994d1\", \"vp-cd5684ba16aa\"]", "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\", \"src-02c2a9805a91\", \"src-3fdc904ca23a\", \"src-57716a69cc86\", \"src-892677e1d3e1\", \"src-7e38f8f1c038\", \"src-8e691f9c959f\", \"src-5ced799861a4\", \"src-7434fb7500ab\", \"src-f86f0a02b7bb\", \"src-f26d039d177f\", \"src-f89329c832ec\", \"src-fbe09c63a68a\", \"src-3d42acbf1ed2\", \"src-3406f384a8d2\", \"src-5a2a337a9bc0\", \"src-848bff010797\", \"src-144db63a9d52\", \"src-326d91c55f3a\", \"src-2e92529ce93e\", \"src-2f3f0e2fad11\", \"src-29df650e0cd9\", \"src-190ce3895a76\", \"src-93f49315a162\", \"src-d1ce88d68a88\", \"src-90ce42415df6\", \"src-4e893ca84bd7\", \"src-4f82a42b4c15\", \"src-180403731046\", \"src-0b92b07afbcd\", \"src-887e067cdfeb\", \"src-5e652caee352\", \"src-6b4af507be01\", \"src-804693cbd100\", \"src-43f57fedfa87\", \"src-054ba6dc7d00\", \"src-229fef399f44\", \"src-3fd6ca20c26e\", \"src-3a6bff93c0af\", \"src-7bcb95db7c9e\", \"src-653