INSERT INTO "knowledge_change_log" VALUES(476,'l3_claim','sc-02c2a9805a91','*','update','{"id": "sc-02c2a9805a91", "facet": null, "proposition": "Russia''s Q1 GDP contraction of 0.2% does not mean the war economy is broken — the author argues Russia will still grow ~1% this year and Putin can keep funding the war, framing Western think-tank (Kiel Institute) talk of ''structural exhaustion'' as misleading.", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-02c2a9805a91", "source_ref_ids": "[\"src-02c2a9805a91\"]", "verbatim_excerpt": "That 0.2% is misleading. Russia will grow about 1% this year and Putin can keep funding the war — Economist.", "cached_text_hash": "e9cb960d8bebf05da5d8406c44d12012e115c1904b43d0b88413a172e1b3136a", "analysis_note": "Contrarian interpretive take that disputes a Western-think-tank consensus (Kiel ''structural exhaustion''). Author is Tymofiy Mylovanov (economist; president of Kyiv School of Economics, former Ukrainian economy minister) — domain-credentialed. The 1% growth figure is attributed to The Economist, so the supporting data is a secondary citation, not original reporting.", "filter_trace": "{\"independence\": \"One author; numbers rest on a single secondary citation (The Economist) and the counterclaim targets another single institution (Kiel). No independent corroboration presented in-post.\", \"quality_density\": \"High density: specific figures, named sources, falsifiable claim (growth rate, funding capacity).\", \"recency\": \"Time-sensitive macro/geopolitical data (Q1 GDP, 2024 outlook) — decays; annual figures can be revised.\"}", "debate_trace": null, "credibility_id": "cred-c26c7db8261a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-02c2a9805a91", "facet": null, "proposition": "Russia''s Q1 GDP contraction of 0.2% does not mean the war economy is broken — the author argues Russia will still grow ~1% this year and Putin can keep funding the war, framing Western think-tank (Kiel Institute) talk of ''structural exhaustion'' as misleading.", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-02c2a9805a91", "source_ref_ids": "[\"src-02c2a9805a91\"]", "verbatim_excerpt": "That 0.2% is misleading. Russia will grow about 1% this year and Putin can keep funding the war — Economist.", "cached_text_hash": "e9cb960d8bebf05da5d8406c44d12012e115c1904b43d0b88413a172e1b3136a", "analysis_note": "Contrarian interpretive take that disputes a Western-think-tank consensus (Kiel ''structural exhaustion''). Author is Tymofiy Mylovanov (economist; president of Kyiv School of Economics, former Ukrainian economy minister) — domain-credentialed. The 1% growth figure is attributed to The Economist, so the supporting data is a secondary citation, not original reporting.", "filter_trace": "{\"independence\": \"One author; numbers rest on a single secondary citation (The Economist) and the counterclaim targets another single institution (Kiel). No independent corroboration presented in-post.\", \"quality_density\": \"High density: specific figures, named sources, falsifiable claim (growth rate, funding capacity).\", \"recency\": \"Time-sensitive macro/geopolitical data (Q1 GDP, 2024 outlook) — decays; annual figures can be revised.\"}", "debate_trace": null, "credibility_id": "cred-e20ca5392c6b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(477,'l3_claim','sc-03ffbc1d6338','*','update','{"id": "sc-03ffbc1d6338", "facet": null, "proposition": "普京称乌克兰须为其在库尔斯克的行动付出领土代价,俄方将夺取这些领土用于建立安全区(对其入侵库尔斯克的报复性领土主张)", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-03ffbc1d6338", "source_ref_ids": "[\"src-03ffbc1d6338\"]", "verbatim_excerpt": "Ukraine WILL PAY for CRIMES in Kursk with LOSS of territory that we need to create a security zone — #Putin", "cached_text_hash": "5baaeab4cfa98e5569629158a014f6e52b894de96954f0ddfb4b6c76bf0cf0f1", "analysis_note": "经 RT(俄罗斯国家媒体)传播、由聚合账号「World News」与 @ferozwala 转发的普京言论;属俄方官方叙事框架下的口头威胁/意图声明。命题本身是『普京作出了这一表态』,而非『该领土后果必将兑现』——后者需独立军事进展佐证,本源未提供。", "filter_trace": "{\"independence\": \"低:单一来源链,源头为俄罗斯国家媒体 RT,经匿名聚合账号二次转发,无任何独立信源。\", \"quality_density\": \"中:是一句具体、可指向的领土威胁(库尔斯克→安全区),信息可证伪;但全大写、情绪化措辞(『WILL PAY』『CRIMES』)带有明显宣传修辞,密度被框架稀释。\", \"recency\": \"当期:涉及进行中的库尔斯克态势,时效性强,主张当前仍有效。\"}", "debate_trace": null, "credibility_id": "cred-85df46b11b37", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-03ffbc1d6338", "facet": null, "proposition": "普京称乌克兰须为其在库尔斯克的行动付出领土代价,俄方将夺取这些领土用于建立安全区(对其入侵库尔斯克的报复性领土主张)", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-03ffbc1d6338", "source_ref_ids": "[\"src-03ffbc1d6338\"]", "verbatim_excerpt": "Ukraine WILL PAY for CRIMES in Kursk with LOSS of territory that we need to create a security zone — #Putin", "cached_text_hash": "5baaeab4cfa98e5569629158a014f6e52b894de96954f0ddfb4b6c76bf0cf0f1", "analysis_note": "经 RT(俄罗斯国家媒体)传播、由聚合账号「World News」与 @ferozwala 转发的普京言论;属俄方官方叙事框架下的口头威胁/意图声明。命题本身是『普京作出了这一表态』,而非『该领土后果必将兑现』——后者需独立军事进展佐证,本源未提供。", "filter_trace": "{\"independence\": \"低:单一来源链,源头为俄罗斯国家媒体 RT,经匿名聚合账号二次转发,无任何独立信源。\", \"quality_density\": \"中:是一句具体、可指向的领土威胁(库尔斯克→安全区),信息可证伪;但全大写、情绪化措辞(『WILL PAY』『CRIMES』)带有明显宣传修辞,密度被框架稀释。\", \"recency\": \"当期:涉及进行中的库尔斯克态势,时效性强,主张当前仍有效。\"}", "debate_trace": null, "credibility_id": "cred-969c83b1d34f", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 13:07:45',NULL);
