INSERT INTO "knowledge_change_log" VALUES(481,'l3_claim','sc-1197f691f12d','*','update','{"id": "sc-1197f691f12d", "facet": null, "proposition": "一则小红书笔记以「是否后悔」为叙事框架，记述一家三口从深圳移民乌克兰的个人经历；正文未抓取，仅卡片级证据，其结论（是否后悔及具体内容）无法被验证。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-1197f691f12d", "source_ref_ids": "[\"src-1197f691f12d\"]", "verbatim_excerpt": "一家三口从深圳移民乌克兰，后悔了吗？", "cached_text_hash": "c3a7c043045069f7a6ae7e2db5a14216f97f92e6913e072de9cbfe21490ea335", "analysis_note": "卡片级证据：为规避风控正文未抓取，仅留存标题与互动数据（点赞6/评论10）。本次蒸馏仅锁定「该个人移民叙事存在」这一层面，无法判断当事人是否真后悔、移民时间与背景等具体内容，需后续抓取全文后方可提升。", "filter_trace": "{\"independence\": \"单一小红书笔记，无独立来源交叉印证\", \"quality_density\": \"正文缺失，仅有标题与互动数，密度极低且不可证伪\", \"recency\": \"未含明确时间，乌克兰局势快速变化，时效存疑\"}", "debate_trace": null, "credibility_id": "cred-4309117d1746", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-1197f691f12d", "facet": null, "proposition": "一则小红书笔记以「是否后悔」为叙事框架，记述一家三口从深圳移民乌克兰的个人经历；正文未抓取，仅卡片级证据，其结论（是否后悔及具体内容）无法被验证。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-1197f691f12d", "source_ref_ids": "[\"src-1197f691f12d\"]", "verbatim_excerpt": "一家三口从深圳移民乌克兰，后悔了吗？", "cached_text_hash": "c3a7c043045069f7a6ae7e2db5a14216f97f92e6913e072de9cbfe21490ea335", "analysis_note": "卡片级证据：为规避风控正文未抓取，仅留存标题与互动数据（点赞6/评论10）。本次蒸馏仅锁定「该个人移民叙事存在」这一层面，无法判断当事人是否真后悔、移民时间与背景等具体内容，需后续抓取全文后方可提升。", "filter_trace": "{\"independence\": \"单一小红书笔记，无独立来源交叉印证\", \"quality_density\": \"正文缺失，仅有标题与互动数，密度极低且不可证伪\", \"recency\": \"未含明确时间，乌克兰局势快速变化，时效存疑\"}", "debate_trace": null, "credibility_id": "cred-0b5e3d09b938", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-2