INSERT INTO "knowledge_change_log" VALUES(483,'l3_claim','sc-180403731046','*','update','{"id": "sc-180403731046", "facet": null, "proposition": "俄罗斯前线一辆 KAMAZ 5350 军用卡车据称被摧毁（单一社媒帖断言，无地点/时间/可核验细节）。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-180403731046", "source_ref_ids": "[\"src-180403731046\"]", "verbatim_excerpt": "Destroyed Russian KAMAZ 5350 truck somewhere on the front line", "cached_text_hash": "0d2b7c965d4411461163b6358a5c458a71fc9c91854052b640d179d6e334e2f5", "analysis_note": "这是单一 OSINT/战况帖对一件俄军装备损失的视觉性断言。仅凭文本无法验证：未给出地点、日期、所属单位或损伤方式。此类平台上的装备损毁声称在俄乌战争中常见，需独立地理定位或多源印证后方可采信。作为单源未核实主张，可信度封顶为 low。", "filter_trace": "{\"independence\": \"单源（@MilitaryNewsUA 一帖），无第二独立来源印证\", \"quality_density\": \"低：仅''前线某处一辆卡车被毁''，无可核验的地点/时间/单位/弹道信息\", \"recency\": \"持续冲突中的实时战况帖，时效新但无时间戳\"}", "debate_trace": null, "credibility_id": "cred-ce82eee9e0ed", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-180403731046", "facet": null, "proposition": "俄罗斯前线一辆 KAMAZ 5350 军用卡车据称被摧毁（单一社媒帖断言，无地点/时间/可核验细节）。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-180403731046", "source_ref_ids": "[\"src-180403731046\"]", "verbatim_excerpt": "Destroyed Russian KAMAZ 5350 truck somewhere on the front line", "cached_text_hash": "0d2b7c965d4411461163b6358a5c458a71fc9c91854052b640d179d6e334e2f5", "analysis_note": "这是单一 OSINT/战况帖对一件俄军装备损失的视觉性断言。仅凭文本无法验证：未给出地点、日期、所属单位或损伤方式。此类平台上的装备损毁声称在俄乌战争中常见，需独立地理定位或多源印证后方可采信。作为单源未核实主张，可信度封顶为 low。", "filter_trace": "{\"independence\": \"单源（@MilitaryNewsUA 一帖），无第二独立来源印证\", \"quality_density\": \"低：仅''前线某处一辆卡车被毁''，无可核验的地点/时间/单位/弹道信息\", \"recency\": \"持续冲突中的实时战况帖，时效新但无时间戳\"}", "debate_trace": null, "credibility_id": "cred-36831fe8c088", "parent_l2_id": null, "lifecycle": null, "status": "active", 