INSERT INTO "knowledge_change_log" VALUES(484,'l3_claim','sc-190ce3895a76','*','update','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型等具体可证伪细节\", \"recency\": \"快变地缘/战场主题，装备部署信息易随战况更新而过期\"}", "debate_trace": null, "credibility_id": "cred-2567076317e0", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-190ce3895a76", "facet": null, "proposition": "乌克兰部署了名为「Sky Sentinel」的遥控炮塔（搭载 M2 勃朗宁重机枪），专门用于击落 Shahed 型（Geran）自杀式无人机。", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-190ce3895a76", "source_ref_ids": "[\"src-190ce3895a76\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "ec81d0941942310d25e70ac7d278b869badca76ab75d40a8c5dda4feaa933420", "analysis_note": "单条媒体推文陈述一项具体装备部署事实（型号、用途、目标机型均明确、可证伪），但该 payload 内无独立印证，未经官方或第三方核验。", "filter_trace": "{\"independence\": \"单源（The Caspian Post 一条推文），payload 内无独立来源印证\", \"quality_density\": \"高：M2 Browning / 遥控炮塔 / Shahed(Geran) 目标机型