INSERT INTO "knowledge_change_log" VALUES(487,'l3_claim','sc-29df650e0cd9','*','update','{"id": "sc-29df650e0cd9", "facet": null, "proposition": "乌克兰战机正使用美国提供的 GBU-39/B 小直径炸弹（SDB，250 磅/110 公斤精确制导滑翔弹）对前线附近的俄军阵地实施空袭", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-29df650e0cd9", "source_ref_ids": "[\"src-29df650e0cd9\"]", "verbatim_excerpt": "A video compilation showing Ukrainian airstrikes with US-supplied GBU-39/B Small Diameter Bombs targeting Russian positions around the frontline.", "cached_text_hash": "05732c74ce0a38d99f686c5b7811358bbad94260ae0e112dccd5f88241fb0ecf", "analysis_note": "来自知名 OSINT/战况新闻账号（Status-6 / Archer83Able），附带视频汇编作为视觉证据；属战场动态报道，单源社媒，未经独立机构核实。", "filter_trace": "{\"independence\": \"单条 X 推文，无第二独立来源交叉确认\", \"quality_density\": \"高：给出具体弹种 GBU-39/B SDB、装药重量、载机型号及打击目标\", \"recency\": \"战场动态报道，时效性强\"}", "debate_trace": null, "credibility_id": "cred-77b7af657b93", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-29df650e0cd9", "facet": null, "proposition": "乌克兰战机正使用美国提供的 GBU-39/B 小直径炸弹（SDB，250 磅/110 公斤精确制导滑翔弹）对前线附近的俄军阵地实施空袭", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-29df650e0cd9", "source_ref_ids": "[\"src-29df650e0cd9\"]", "verbatim_excerpt": "A video compilation showing Ukrainian airstrikes with US-supplied GBU-39/B Small Diameter Bombs targeting Russian positions around the frontline.", "cached_text_hash": "05732c74ce0a38d99f686c5b7811358bbad94260ae0e112dccd5f88241fb0ecf", "analysis_note": "来自知名 OSINT/战况新闻账号（Status-6 / Archer83Able），附带视频汇编作为视觉证据；属战场动态报道，单源社媒，未经独立机构核实。", "filter_trace": "{\"independence\": \"单条 X 推文，无第二独立来源交叉确认\", \"quality_density\": \"高：给出具体弹种 GBU-39/B SDB、装药重量、载机型号及打击目标\", \"recency\": \"战场动态报道，时效性强\"}", "debate_trace": null, "credibility_id": "cred-33