INSERT INTO "knowledge_change_log" VALUES(501,'l3_claim','sc-3fdc904ca23a','*','update','{"id": "sc-3fdc904ca23a", "facet": null, "proposition": "Adam Tooze将俄罗斯战时经济定性为脆弱的''纸牌屋''：油气收入停滞叠加持续的能源制裁不断消耗其资源，war economy虽在短期显现韧性但结构性脆弱正在累积。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-3fdc904ca23a", "source_ref_ids": "[\"src-3fdc904ca23a\"]", "verbatim_excerpt": "俄罗斯战时经济呈''纸牌屋''特征，油气收入停滞+能源制裁持续消耗资源", "cached_text_hash": "9bb8aace829849db731accb3f38822eeb4aac6057769a65e82c772c799d63985", "analysis_note": "原文同时援引Bruegel工作论文（2022–2025俄经济在战争成本攀升与广泛制裁下仍具韧性）与Stratfor/RANE（俄战争经济正在动摇）作为佐证视角；Tooze的判断侧重中长期结构性脆弱而非短期韧性。", "filter_trace": "{\"independence\": \"单一来源（Tooze个人分析），但原文内部交叉引用了Bruegel工作论文与Stratfor/RANE作为佐证，具备一定独立性基础\", \"quality_density\": \"信息密度中等偏高，给出机制性解释（油气停滞+制裁消耗）并引用学术工作论文\", \"recency\": \"2025年当年文章，时效性强，适用于快变的地缘经济主题\"}", "debate_trace": null, "credibility_id": "cred-484602ebdf9f", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-3fdc904ca23a", "facet": null, "proposition": "Adam Tooze将俄罗斯战时经济定性为脆弱的''纸牌屋''：油气收入停滞叠加持续的能源制裁不断消耗其资源，war economy虽在短期显现韧性但结构性脆弱正在累积。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-3fdc904ca23a", "source_ref_ids": "[\"src-3fdc904ca23a\"]", "verbatim_excerpt": "俄罗斯战时经济呈''纸牌屋''特征，油气收入停滞+能源制裁持续消耗资源", "cached_text_hash": "9bb8aace829849db731accb3f38822eeb4aac6057769a65e82c772c799d63985", "analysis_note": "原文同时援引Bruegel工作论文（2022–2025俄经济在战争成本攀升与广泛制裁下仍具韧性）与Stratfor/RANE（俄战争经济正在动摇）作为佐证视角；Tooze的判断侧重中长期结构性脆弱而非短期韧性。", "filter_trace": "{\"independence\": \"单一来源（Tooze个人分析），但原文内部交叉引用了Bruegel工作论文与Stratfor/RANE作为佐证，具备一定独立性基础\", \"quality_density\": \"信息密度中等偏高，给出机制性解释（油气停滞+制裁消耗）并引用学术工作论文\", \"recency\": \"2025年当年文章，时效性强，适用于快变的地缘经济主题\"}", "debate_trace": null, "credibility_id": "cred-37a07c89833b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 13:07:45',NULL);
