INSERT INTO "knowledge_change_log" VALUES(504,'l3_claim','sc-457fc3be2e00','*','update','{"id": "sc-457fc3be2e00", "facet": null, "proposition": "据该推文，普京宣称乌克兰将以领土为代价为其在库尔斯克地区的「罪行」付出代价，即俄罗斯将在苏梅州建立一个「缓冲区」。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-457fc3be2e00", "source_ref_ids": "[\"src-457fc3be2e00\"]", "verbatim_excerpt": "L''Ucraina pagherà per i suoi crimini nella regione di Kursk con il territorio necessario per creare una \"zona cuscinetto\" della Russia nella regione di Sumy", "cached_text_hash": "7fc9bf31f779f49721c7a602a3a33ff7d2191ce914e67fff1dd88e197aca3e28", "analysis_note": "转述普京表态的二手推文，作者立场鲜明（称普京为「战犯」），属带框架的政治转述，非中立报道；核心信息点是普京将库尔斯克战事与在苏梅建缓冲区/吞并领土相挂钩。", "filter_trace": "{\"independence\": \"单源、党派账号转述，无第二来源印证\", \"quality_density\": \"有具体地理指向（库尔斯克→苏梅缓冲区），但为二手转述且文本被截断\", \"recency\": \"地缘冲突快变主题，需以一手表态核实时效\"}", "debate_trace": null, "credibility_id": "cred-4c930e7911ef", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:40:37", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-457fc3be2e00", "facet": null, "proposition": "据该推文，普京宣称乌克兰将以领土为代价为其在库尔斯克地区的「罪行」付出代价，即俄罗斯将在苏梅州建立一个「缓冲区」。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-457fc3be2e00", "source_ref_ids": "[\"src-457fc3be2e00\"]", "verbatim_excerpt": "L''Ucraina pagherà per i suoi crimini nella regione di Kursk con il territorio necessario per creare una \"zona cuscinetto\" della Russia nella regione di Sumy", "cached_text_hash": "7fc9bf31f779f49721c7a602a3a33ff7d2191ce914e67fff1dd88e197aca3e28", "analysis_note": "转述普京表态的二手推文，作者立场鲜明（称普京为「战犯」），属带框架的政治转述，非中立报道；核心信息点是普京将库尔斯克战事与在苏梅建缓冲区/吞并领土相挂钩。", "filter_trace": "{\"independence\": \"单源、党派账号转述，无第二来源印证\", \"quality_density\": \"有具体地理指向（库尔斯克→苏梅缓冲区），但为二手转述且文本被截断\", \"recency\": \"地缘冲突快变主题，需以一手表态核实时效\"}", "debate_trace": null, "credibility_id": "cred-7bdf7ecb3307", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:40:37", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 13:07:45',NULL);
