INSERT INTO "knowledge_change_log" VALUES(507,'l3_claim','sc-4e893ca84bd7','*','update','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_density\": \"密度较高：点名系统名称、武器型号（M2 Browning）与目标（Shahed/Geran），但无影像/官方佐证\", \"recency\": \"俄乌战事属快变主题，部署消息时效性强\"}", "debate_trace": null, "credibility_id": "cred-c1e7a3edc31a", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-4e893ca84bd7", "facet": null, "proposition": "乌克兰正在部署一种名为「Sky Sentinel」的遥控炮塔，搭载 M2 勃朗宁重机枪，专门用于击落 Shahed（Geran）型自杀式无人机。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-4e893ca84bd7", "source_ref_ids": "[\"src-4e893ca84bd7\"]", "verbatim_excerpt": "Ukraine deploys the Sky Sentinel, a remote-operated turret mounting an M2 Browning machine gun, designed to shoot down Shahed-type (Geran) kamikaze drones.", "cached_text_hash": "07b6736def24850ebef3504e48d994c36f5ddca4d9ac8c2db39704e6c9006c34", "analysis_note": "来自军事新闻聚合账号 Clash Report 的单一来源战况报道，点名了系统、武器型号与打击目标，但推文未附带可核验的影像或官方来源；属单一社媒信源，需更多独立来源印证。", "filter_trace": "{\"independence\": \"单一来源（Clash Report 一个 X 账号），本 payload 内无独立印证\", \"quality_density\": \"密度较高：点名系统名称、武器型号（M2 Browning）与目标（Shahed/Geran），但无影像/官方佐证\", \"recency\": \"俄乌战事属快变主题，部署消息时效性强\"}", "debate_trace": null, "credibility_id": "cred-5e3d9ff8a279", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(508,'l3_claim','sc-4f82a42b4c15','*','update','{"id": "sc-4f82a42b4c15", "facet": null, "proposition": "An anonymous X user expresses skepticism about an unspecified (likely drone/anti-drone) system, arguing it must be proven in operation, is itself vulnerable to drone attack, and that automation risks friendly-fire incidents.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-4f82a42b4c15", "source_ref_ids": "[\"src-4f82a42b4c15\"]", "verbatim_excerpt": "Interesting, but need to see it in operation. It can, itself, get attacked by drones, and if automated, could result in friendly-fire.", "cached_text_hash": "29b6c08c747fb9d1760d9fac722f5835ad5a7d89f87f4a5b5ed954fa2aa7b83b", "analysis_note": "The post''s referent (which system) is not captured in this single unit; it is a speculative reaction, not a verifiable claim. Author handle (''MAGAtard'') is an anonymous/pseudonymous account with no institutional standing.", "filter_trace": "{\"independence\": \"Single pseudonymous account; no independent sources or corroboration cited.\", \"quality_density\": \"Short speculative reaction — no data, evidence, or specifics, pure conjecture.\", \"recency\": \"Concern is timeless (not time-bound); recency is not the binding constraint here.\"}", "debate_trace": null, "credibility_id": "cred-49da026b11d7", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-4f82a42b4c15", "facet": null, "proposition": "An anonymous X user expresses skepticism about an unspecified (likely drone/anti-drone) system, arguing it must be proven in operation, is itself vulnerable to drone attack, and that automation risks friendly-fire incidents.", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-4f82a42b4c15", "source_ref_ids": "[\"src-4f82a42b4c15\"]", "verbatim_excerpt": "Interesting, but need to see it in operation. It can, itself, get attacked by drones, and if automated, could result in friendly-fire.", "cached_text_hash": "29b6c08c747fb9d1760d9fac722f5835ad5a7d89f87f4a5b5ed954fa2aa7b83b", "analysis_note": "The post''s referent (which system) is not captured in this single unit; it is a speculative reaction, not a verifiable claim. Author handle (''MAGAtard'') is an anonymous/pseudonymous account with no institutional standing.", "filter_trace": "{\"independence\": \"Single pseudonymous account; no independent sources or corroboration cited.\", \"quality_density\": \"Short speculative reaction — no data, evidence, or specifics, pure conjecture.\", \"recency\": \"Concern is timeless (not time-bound); recency is not the binding constraint here.\"}", "debate_trace": null, "credibility_id": "cred-657c045944a5", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=opinion facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(509,'l3_claim','sc-57716a69cc86','*','update','{"id": "sc-57716a69cc86", "facet": null, "proposition": "小红书一条由义乌供应链公司发布的笔记以『被制裁后的俄罗斯是怎么过的』为题，主张关注/分析俄罗斯在制裁后的应对情况（仅卡片级证据，正文未抓取）。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-57716a69cc86", "source_ref_ids": "[\"src-57716a69cc86\"]", "verbatim_excerpt": "💥大瓜！被制裁后的俄罗斯，是怎么过的？", "cached_text_hash": "e3d718439c5f24484d5555f7a9df6b6b5eef33495f3c312a171bb66f623f95c7", "analysis_note": "正文未抓取以规避风控（仅留存标题、作者、互动量等卡片级元数据；xsec_token可追溯），无法核验具体论点，本条 L3 仅反映标题所暗示的主张框架。", "filter_trace": "{\"independence\": \"单条小红书帖，无独立来源印证，正文缺失无法判断其引用关系或是否转发。\", \"quality_density\": \"仅标题与元数据，无可证伪细节，标题为诱导性标题党，信息密度低。\", \"recency\": \"发布日期缺失，且属快速变化的地缘政治主题，时效性无法确认。\"}", "debate_trace": null, "credibility_id": "cred-d35374665b86", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-57716a69cc86", "facet": null, "proposition": "小红书一条由义乌供应链公司发布的笔记以『被制裁后的俄罗斯是怎么过的』为题，主张关注/分析俄罗斯在制裁后的应对情况（仅卡片级证据，正文未抓取）。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-57716a69cc86", "source_ref_ids": "[\"src-57716a69cc86\"]", "verbatim_excerpt": "💥大瓜！被制裁后的俄罗斯，是怎么过的？", "cached_text_hash": "e3d718439c5f24484d5555f7a9df6b6b5eef33495f3c312a171bb66f623f95c7", "analysis_note": "正文未抓取以规避风控（仅留存标题、作者、互动量等卡片级元数据；xsec_token可追溯），无法核验具体论点，本条 L3 仅反映标题所暗示的主张框架。", "filter_trace": "{\"independence\": \"单条小红书帖，无独立来源印证，正文缺失无法判断其引用关系或是否转发。\", \"quality_density\": \"仅标题与元数据，无可证伪细节，标题为诱导性标题党，信息密度低。\", \"recency\": \"发布日期缺失，且属快速变化的地缘政治主题，时效性无法确认。\"}", "debate_trace": null, "credibility_id": "cred-f20713780e7d", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_a