INSERT INTO "knowledge_change_log" VALUES(511,'l3_claim','sc-5ced799861a4','*','update','{"id": "sc-5ced799861a4", "facet": null, "proposition": "弗拉基米尔·普京公开承认俄罗斯正面临国内能源紧张（加油站排长队、基础标号燃油从泵口消失），这一迹象被作者解读为施压俄罗斯的策略正在奏效。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-5ced799861a4", "source_ref_ids": "[\"src-5ced799861a4\"]", "verbatim_excerpt": "Vladimir Putin just publicly admitted that Russia is facing a domestic energy squeeze, with long lines forming at gas stations and basic fuel grades vanishing from the pumps.", "cached_text_hash": "65e8b41e56c0e3c6c9b21f5cda08b38c0a9aeb7f0b0ba50e3238c962310a49c7", "analysis_note": "该主张把「普京公开承认能源紧张」这一未经原文核实的断言，框定为对俄施压策略奏效的佐证；属于解读性叙述而非冷事实陈述。原推文被截断（''To keep the''），无法看到完整论证与是否引用普京原话。", "filter_trace": "{\"independence\": \"单一社媒来源，无独立来源印证，亦无指向普京原声/官方声明的可追溯出处\", \"quality_density\": \"有具体画面（排队、标号消失）但属二手渲染，无可证伪的原始凭据\", \"recency\": \"属快变地缘话题的即时断言，无明确时间戳且易过期\"}", "debate_trace": null, "credibility_id": "cred-bba7ff2649f8", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-5ced799861a4", "facet": null, "proposition": "弗拉基米尔·普京公开承认俄罗斯正面临国内能源紧张（加油站排长队、基础标号燃油从泵口消失），这一迹象被作者解读为施压俄罗斯的策略正在奏效。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-5ced799861a4", "source_ref_ids": "[\"src-5ced799861a4\"]", "verbatim_excerpt": "Vladimir Putin just publicly admitted that Russia is facing a domestic energy squeeze, with long lines forming at gas stations and basic fuel grades vanishing from the pumps.", "cached_text_hash": "65e8b41e56c0e3c6c9b21f5cda08b38c0a9aeb7f0b0ba50e3238c962310a49c7", "analysis_note": "该主张把「普京公开承认能源紧张」这一未经原文核实的断言，框定为对俄施压策略奏效的佐证；属于解读性叙述而非冷事实陈述。原推文被截断（''To keep the''），无法看到完整论证与是否引用普京原话。", "filter_trace": "{\"independence\": \"单一社媒来源，无独立来源印证，亦无指向普京原声/官方声明的可追溯出处\", \"quality_density\": \"有具体画面（排队、标号消失）但属二手渲染，无可证伪的原始凭据\", \"recency\": \"属快变地缘话题的即时断言，无明确时间戳且易过期\"}", "debate_trace": null, "credibility_id": "cred-126bcfcb30b5", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(512,'l3_claim','sc-5e652caee352','*','update','{"id": "sc-5e652caee352", "facet": null, "proposition": "2022-24 年欧盟及成员国向乌克兰提供逾 1450 亿美元财政/军事/人道/难民援助，且军援从早期便携式系统（标枪反坦克导弹）升级为 HIMARS、爱国者、F-16 等高端装备，构成乌克兰得以持续抵抗的核心支撑；乌方据此结合本土创新（尤其无人机）形成动态防御模式。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-5e652caee352", "source_ref_ids": "[\"src-5e652caee352\"]", "verbatim_excerpt": "2022-24年欧盟及成员国向乌克兰提供逾1450亿美元财政/军事/人道/难民援助。早期军援优先便携式系统(标枪反坦克导弹)，后演进为HIMARS精确打击、爱国者防空、F-16战机等高端系统。", "cached_text_hash": "2b51e9143aceb36ea4a3a77c4dca7ad085d82137c6ee708a31bd40dec585b583", "analysis_note": "CEPA 的概括性判断：援助规模与装备升级路径是乌支撑力的核心。含具体数据点（1450 亿美元、装备演进序列），但''核心支撑''属解释性框架而非单一硬事实；印证度留给 aggregate 阶段机械计数。", "filter_trace": "{\"independence\": \"单一来源（CEPA 单篇报告），尚未与其他独立来源交叉印证。\", \"quality_density\": \"高：含具体金额（1450 亿美元）与装备演进序列（标枪→HIMARS→爱国者→F-16），可证伪。\", \"recency\": \"数据覆盖 2022-24 年，对本主题仍有效；但战时援助持续变化，存在后续更新空间。\"}", "debate_trace": null, "credibility_id": "cred-b51a035a7d5c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-5e652caee352", "facet": null, "proposition": "2022-24 年欧盟及成员国向乌克兰提供逾 1450 亿美元财政/军事/人道/难民援助，且军援从早期便携式系统（标枪反坦克导弹）升级为 HIMARS、爱国者、F-16 等高端装备，构成乌克兰得以持续抵抗的核心支撑；乌方据此结合本土创新（尤其无人机）形成动态防御模式。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-5e652caee352", "source_ref_ids": "[\"src-5e652caee352\"]", "verbatim_excerpt": "2022-24年欧盟及成员国向乌克兰提供逾1450亿美元财政/军事/人道/难民援助。早期军援优先便携式系统(标枪反坦克导弹)，后演进为HIMARS精确打击、爱国者防空、F-16战机等高端系统。", "cached_text_hash": "2b51e9143aceb36ea4a3a77c4dca7ad085d82137c6ee708a31bd40dec585b583", "analysis_note": "CEPA 的概括性判断：援助规模与装备升级路径是乌支撑力的核心。含具体数据点（1450 亿美元、装备演进序列），但''核心支撑''属解释性框架而非单一硬事实；印证度留给 aggregate 阶段机械计数。", "filter_trace": "{\"independence\": \"单一来源（CEPA 单篇报告），尚未与其他独立来源交叉印证。\", \"quality_density\": \"高：含具体金额（1450 亿美元）与装备演进序列（标枪→HIMARS→爱国者→F-16），可证伪。\", \"recency\": \"数据覆盖 2022-24 年，对本主题仍有效；但战时援助持续变化，存在后续更新空间。\"}", "debate_trace": null, "credibility_id": "cred-bbea86836268", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(513,'l3_claim','sc-5f6cd2d39ac2','*','update','{"id": "sc-5f6cd2d39ac2", "facet": null, "proposition": "Putin warned that Ukraine will permanently lose territory as a consequence of its Kursk incursion, stating Russia would seize the land to establish a necessary border security zone.", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-5f6cd2d39ac2", "source_ref_ids": "[\"src-5f6cd2d39ac2\"]", "verbatim_excerpt": "He stated Russia will seize the land to create a necessary border security zone.", "cached_text_hash": "c29eca511e2fefcfedbfa49e2a7ff270d8eed6d67ed0b4fb0293ddf0a7d16914", "analysis_note": "Reports a public declaration by a head of state; the territorial seizure itself is future-tense and not yet realized, but the fact that the statement was made is the core claim being distilled.", "filter_trace": "{\"independence\": \"Only one source in the payload; a single tweet, no basis here to confirm independent corroboration.\", \"quality_density\": \"Specific and falsifiable: permanent territorial loss plus an explicitly stated border security buffer zone.\", \"recency\": \"Fast-moving geopolitics; whether the threatened seizure actually materializes is unresolved, though the record that the statement was made remains valid.\"}", "debate_trace": null, "credibility_id": "cred-21988a1ca219", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-5f6cd2d39ac2", "facet": null, "proposition": "Putin warned that Ukraine will permanently lose territory as a consequence of its Kursk incursion, stating Russia would seize the land to establish a necessary border security zone.", "claim_kind": "fact", "source_kind": "post", "single_source_ref_id": "src-5f6cd2d39ac2", "source_ref_ids": "[\"src-5f6cd2d39ac2\"]", "verbatim_excerpt": "He stated Russia will seize the land to create a necessary border security zone.", "cached_text_hash": "c29eca511e2fefcfedbfa49e2a7ff270d8eed6d67ed0b4fb0293ddf0a7d16914", "analysis_note": "Reports a public declaration by a head of state; the territorial seizure itself is future-tense and not yet realized, but the fact that the statement was made is the core claim being distilled.", "filter_trace": "{\"independence\": \"Only one source in the payload; a single tweet, no basis here to confirm independent corroboration.\", \"quality_density\": \"Specific and falsifiable: permanent territorial loss plus an explicitly stated border security buffer zone.\", \"recency\": \"Fast-moving geopolitics; whether the threatened seizure actually materializes is unresolved, though the record that the statement was made remains valid.\"}", "debate_trace": null, "credibility_id": "cred-3edd9744e19c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 13:07:45',NULL);
