INSERT INTO "knowledge_change_log" VALUES(515,'l3_claim','sc-65378bb4a0ce','*','update','{"id": "sc-65378bb4a0ce", "facet": null, "proposition": "普京据称提出了最新一轮停战条件，且俄罗斯方面据称再次做出让步。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-65378bb4a0ce", "source_ref_ids": "[\"src-65378bb4a0ce\"]", "verbatim_excerpt": "普京开出最新停战条件，俄罗斯再次让步", "cached_text_hash": "750e535fda22bc986f83a15a35a3421de034277330ce77b97e1793036d04058a", "analysis_note": "卡片级证据：正文未抓取以规避风控，本条主张仅源自标题，无具体停战条件内容或佐证，信息密度极低，可信度受限。", "filter_trace": "{\"independence\": \"单一聚合账号「1点知」，疑似二次转发，无原始一手来源（如普京/Kremlin 声明）入档。\", \"quality_density\": \"极低——仅有标题，无任何停战条件或让步的具体内容，无可证伪细节。\", \"recency\": \"标题含「最新」但未留存发布日期；停战谈判类快变信息易过期。\"}", "debate_trace": null, "credibility_id": "cred-995ec30d6a8c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-65378bb4a0ce", "facet": null, "proposition": "普京据称提出了最新一轮停战条件，且俄罗斯方面据称再次做出让步。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-65378bb4a0ce", "source_ref_ids": "[\"src-65378bb4a0ce\"]", "verbatim_excerpt": "普京开出最新停战条件，俄罗斯再次让步", "cached_text_hash": "750e535fda22bc986f83a15a35a3421de034277330ce77b97e1793036d04058a", "analysis_note": "卡片级证据：正文未抓取以规避风控，本条主张仅源自标题，无具体停战条件内容或佐证，信息密度极低，可信度受限。", "filter_trace": "{\"independence\": \"单一聚合账号「1点知」，疑似二次转发，无原始一手来源（如普京/Kremlin 声明）入档。\", \"quality_density\": \"极低——仅有标题，无任何停战条件或让步的具体内容，无可证伪细节。\", \"recency\": \"标题含「最新」但未留存发布日期；停战谈判类快变信息易过期。\"}", "debate_trace": null, "credibility_id": "cred-cdc0a48e8a81", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=breaking fac