INSERT INTO "knowledge_change_log" VALUES(518,'l3_claim','sc-7434fb7500ab','*','update','{"id": "sc-7434fb7500ab", "facet": null, "proposition": "俄罗斯2026年联邦预算计划将军费从2025年的约16万亿卢布(占GDP约7.5%)下调至12.8万亿卢布(占GDP约5.5%)，多家俄罗斯智库据此将该预算定性为''非胜利预算''和''受控停滞''而非战时扩张。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-7434fb7500ab", "source_ref_ids": "[\"src-7434fb7500ab\"]", "verbatim_excerpt": "2026年计划略降至12.8万亿卢布(占GDP 5.5%)……Re:Russia称2026预算为''非胜利预算''。NEST Centre称2026-28预算显示''受控停滞''。", "cached_text_hash": "c44cb34ab6b66dc94e0f26a486d174db82878b4f0360be869aa0fe62d6446c88", "analysis_note": "核心为可证伪的财政数据(战前2021年仅3.6% GDP为基线)；定性标签(非胜利预算/受控停滞)来自Re:Russia、NEST Centre等俄智库的专家判断，属分析层而非事实层。L3层为单源。", "filter_trace": "{\"independence\": \"SIPRI原始预算分析，并独立援引Riddle Russia、Re:Russia、NEST Centre等多家相互独立的俄智库，非回音室转发。\", \"quality_density\": \"高密度：16万亿/12.8万亿卢布、7.5%/5.5%/3.6% GDP占比等具体可证伪数据。\", \"recency\": \"2026年预算，当前有效；地缘快变主题但预算窗口短，衰减风险低。\"}", "debate_trace": null, "credibility_id": "cred-e8fcb4a3bce9", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-7434fb7500ab", "facet": null, "proposition": "俄罗斯2026年联邦预算计划将军费从2025年的约16万亿卢布(占GDP约7.5%)下调至12.8万亿卢布(占GDP约5.5%)，多家俄罗斯智库据此将该预算定性为''非胜利预算''和''受控停滞''而非战时扩张。", "claim_kind": "data", "source_kind": "article", "single_source_ref_id": "src-7434fb7500ab", "source_ref_ids": "[\"src-7434fb7500ab\"]", "verbatim_excerpt": "2026年计划略降至12.8万亿卢布(占GDP 5.5%)……Re:Russia称2026预算为''非胜利预算''。NEST Centre称2026-28预算显示''受控停滞''。", "cached_text_hash": "c44cb34ab6b66dc94e0f26a486d174db82878b4f0360be869aa0fe62d6446c88", "analysis_note": "核心为可证伪的财政数据(战前2021年仅3.6% GDP为基线)；定性标签(非胜利预算/受控停滞)来自Re:Russia、NEST Centre等俄智库的专家判断，属分析层而非事实层。L3层为单源。", "filter_trace": "{\"independence\": \"SIPRI原始预算分析，并独立援引Riddle Russia、Re:Russia、NEST Centre等多家相互独立的俄智库，非回音室转发。\", \"quality_density\": \"高密度：16万亿/12.8万亿卢布、7.5%/5.5%/3.6% GDP占比等具体可证伪数据。\", \"recency\": \"2026年预算，当前有效；地缘快变主题但预算窗口短，衰减风险低。\"}", "debate_trace": null, "credibility_id": "cred-5f5638705fb2", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=data facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(519,'l3_claim','sc-7bcb95db7c9e','*','update','{"id": "sc-7bcb95db7c9e", "facet": null, "proposition": "2025年4-6月两轮伊斯坦布尔俄乌谈判均未取得突破，仅在战俘交换上达成一致；俄方6月提交的备忘录向乌方提供两种30天停火方案，其中之一要求重大让步，据Chatham House分析包括乌克兰正式放弃加入北约且领土上无北约军事存在或演习。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-7bcb95db7c9e", "source_ref_ids": "[\"src-7bcb95db7c9e\"]", "verbatim_excerpt": "俄罗斯在6月伊斯坦布尔谈判提交的备忘录向乌克兰提供两种30天停火方案，其中之一要求重大让步。", "cached_text_hash": "a83923d5a64f2932e3b380c0ee9ce66f68468dd6080bc29c1e33d44934f4bb4a", "analysis_note": "英国议会研究简报为机构综合性信源；''放弃北约''及''无北约军事存在/演习''部分系援引Chatham House对备忘录的分析，属解读而非原文条款原文。", "filter_trace": "{\"independence\": \"单一议会简报信源，但综合了谈判事件事实与Chatham House分析，属机构原创而非转发。\", \"quality_density\": \"高密度：具体到两轮谈判、战俘交换、两种30天方案及放弃北约/无北约驻军等可证伪细节。\", \"recency\": \"事件为2025年4-6月，时新；属快变地缘主题，需后续轮次核验进展。\"}", "debate_trace": null, "credibility_id": "cred-a40b60aa40db", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-7bcb95db7c9e", "facet": null, "proposition": "2025年4-6月两轮伊斯坦布尔俄乌谈判均未取得突破，仅在战俘交换上达成一致；俄方6月提交的备忘录向乌方提供两种30天停火方案，其中之一要求重大让步，据Chatham House分析包括乌克兰正式放弃加入北约且领土上无北约军事存在或演习。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-7bcb95db7c9e", "source_ref_ids": "[\"src-7bcb95db7c9e\"]", "verbatim_excerpt": "俄罗斯在6月伊斯坦布尔谈判提交的备忘录向乌克兰提供两种30天停火方案，其中之一要求重大让步。", "cached_text_hash": "a83923d5a64f2932e3b380c0ee9ce66f68468dd6080bc29c1e33d44934f4bb4a", "analysis_note": "英国议会研究简报为机构综合性信源；''放弃北约''及''无北约军事存在/演习''部分系援引Chatham House对备忘录的分析，属解读而非原文条款原文。", "filter_trace": "{\"independence\": \"单一议会简报信源，但综合了谈判事件事实与Chatham House分析，属机构原创而非转发。\", \"quality_density\": \"高密度：具体到两轮谈判、战俘交换、两种30天方案及放弃北约/无北约驻军等可证伪细节。\", \"recency\": \"事件为2025年4-6月，时新；属快变地缘主题，需后续轮次核验进展。\"}", "debate_trace": null, "credibility_id": "cred-f8d03715d70c", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(520,'l3_claim','sc-7e38f8f1c038','*','update','{"id": "sc-7e38f8f1c038", "facet": null, "proposition": "（分析视角）该笔记将俄罗斯在制裁压力下的经济表现，类比为一种『罗斯福式』——即国家强力动员/统制型的生存法则。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-7e38f8f1c038", "source_ref_ids": "[\"src-7e38f8f1c038\"]", "verbatim_excerpt": "制裁下的俄罗斯经济，罗斯福式的生存法则", "cached_text_hash": "013cc799aa9ad975dfbd8def0c8555f22aee73740a09fd26f26d6cd35ea92555", "analysis_note": "卡片级证据：笔记正文未抓取（规避平台风控），本条 L3 仅依据标题框架蒸馏，具体论证、数据与机制细节均不可得。xsec_token 已留存可追溯，可在后续轮次重抓正文补强。", "filter_trace": "{\"independence\": \"单一社媒笔记，无其他来源印证\", \"quality_density\": \"仅标题/卡片级证据，正文未抓取，信息密度低、无可证伪细节\", \"recency\": \"近期发布（点赞63/评论70），时点新鲜，但属快变的地缘经济主题\"}", "debate_trace": null, "credibility_id": "cred-aa15b0135865", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-7e38f8f1c038", "facet": null, "proposition": "（分析视角）该笔记将俄罗斯在制裁压力下的经济表现，类比为一种『罗斯福式』——即国家强力动员/统制型的生存法则。", "claim_kind": "analysis", "source_kind": "post", "single_source_ref_id": "src-7e38f8f1c038", "source_ref_ids": "[\"src-7e38f8f1c038\"]", "verbatim_excerpt": "制裁下的俄罗斯经济，罗斯福式的生存法则", "cached_text_hash": "013cc799aa9ad975dfbd8def0c8555f22aee73740a09fd26f26d6cd35ea92555", "analysis_note": "卡片级证据：笔记正文未抓取（规避平台风控），本条 L3 仅依据标题框架蒸馏，具体论证、数据与机制细节均不可得。xsec_token 已留存可追溯，可在后续轮次重抓正文补强。", "filter_trace": "{\"independence\": \"单一社媒笔记，无其他来源印证\", \"quality_density\": \"仅标题/卡片级证据，正文未抓取，信息密度低、无可证伪细节\", \"recency\": \"近期发布（点赞63/评论70），时点新鲜，但属快变的地缘经济主题\"}", "debate_trace": null, "credibility_id": "cred-1a8fbed34122", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "conden