INSERT INTO "knowledge_change_log" VALUES(524,'l3_claim','sc-848bff010797','*','update','{"id": "sc-848bff010797", "facet": null, "proposition": "一名小红书用户（@风之少年）自整理并发布了一份《俄罗斯受制裁产品清单》，获 177 赞 54 评，显示俄受制裁产品这一主题在中文社媒上以用户自发整理清单的形式传播。", "claim_kind": "data", "source_kind": "post", "single_source_ref_id": "src-848bff010797", "source_ref_ids": "[\"src-848bff010797\"]", "verbatim_excerpt": "最全俄罗斯受制裁产品清单（自整理）", "cached_text_hash": "b4dc5230ce26f997e8fb810654a78006e9e0e41416e81a4f5cf264057c20e997", "analysis_note": "卡片级证据：仅抓取到标题与互动数，正文未抓取（规避风控，xsec_token 已留存可追溯）。只能作为「中文社媒上俄受制裁话题以用户自整理清单形式存在并获关注」的弱信号，不可作为具体清单条目/准确性的依据。", "filter_trace": "{\"independence\": \"单一社媒来源、用户自整理，无独立来源印证清单具体内容\", \"quality_density\": \"仅标题+互动数，正文缺失，无法判断清单的完整性与准确性\", \"recency\": \"制裁清单为快变主题，该帖发布时间未知，清单时效性无法判断\"}", "debate_trace": null, "credibility_id": "cred-5939814bc285", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-848bff010797", "facet": null, "proposition": "一名小红书用户（@风之少年）自整理并发布了一份《俄罗斯受制裁产品清单》，获 177 赞 54 评，显示俄受制裁产品这一主题在中文社媒上以用户自发整理清单的形式传播。", "claim_kind": "data", "source_kind": "post", "single_source_ref_id": "src-848bff010797", "source_ref_ids": "[\"src-848bff010797\"]", "verbatim_excerpt": "最全俄罗斯受制裁产品清单（自整理）", "cached_text_hash": "b4dc5230ce26f997e8fb810654a78006e9e0e41416e81a4f5cf264057c20e997", "analysis_note": "卡片级证据：仅抓取到标题与互动数，正文未抓取（规避风控，xsec_token 已留存可追溯）。只能作为「中文社媒上俄受制裁话题以用户自整理清单形式存在并获关注」的弱信号，不可作为具体清单条目/准确性的依据。", "filter_trace": "{\"independence\": \"单一社媒来源、用户自整理，无独立来源印证清单具体内容\", \"quality_density\": \"仅标题+互动数，正文缺失，无法判断清单的完整性与准确性\", \"recency\": \"制裁清单为快变主题，该帖发布时间未知，清单时效性无法判断\"}", "debate_trace": null, "credibility_id": "cred-4e9add815e5b", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "crea