INSERT INTO "knowledge_change_log" VALUES(527,'l3_claim','sc-888c6708efbf','*','update','{"id": "sc-888c6708efbf", "facet": null, "proposition": "一篇小红书笔记将当代战争框定为「远程接单」式的远程/按需作业（指向俄乌战争语境下无人机远程作战等叙事），但正文未抓取，仅有标题层面的框架性表达。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-888c6708efbf", "source_ref_ids": "[\"src-888c6708efbf\"]", "verbatim_excerpt": "当战争变成\"远程接单\"", "cached_text_hash": "1849d53f4768ce866e33a65f9cac443097dfb2a6e1546a1025ee5210ee89d3c9", "analysis_note": "卡片级证据：为规避风控未抓取正文，仅有标题、作者与互动数据（点赞12/评论19）；xsec_token 已留存可追溯。命题基于标题框架推断，缺乏正文支撑，实质论点不可核实。", "filter_trace": "{\"independence\": \"单一小红书笔记，无交叉来源；仅卡片级元数据可用。\", \"quality_density\": \"低——只有标题与点赞/评论数，无正文论据，标题为口号式框架，缺乏可证伪细节。\", \"recency\": \"无明确发布时间戳，主题（远程作战/战争形态演变）属快变领域，时效性无法确认。\"}", "debate_trace": null, "credibility_id": "cred-a3a2cb561363", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-888c6708efbf", "facet": null, "proposition": "一篇小红书笔记将当代战争框定为「远程接单」式的远程/按需作业（指向俄乌战争语境下无人机远程作战等叙事），但正文未抓取，仅有标题层面的框架性表达。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-888c6708efbf", "source_ref_ids": "[\"src-888c6708efbf\"]", "verbatim_excerpt": "当战争变成\"远程接单\"", "cached_text_hash": "1849d53f4768ce866e33a65f9cac443097dfb2a6e1546a1025ee5210ee89d3c9", "analysis_note": "卡片级证据：为规避风控未抓取正文，仅有标题、作者与互动数据（点赞12/评论19）；xsec_token 已留存可追溯。命题基于标题框架推断，缺乏正文支撑，实质论点不可核实。", "filter_trace": "{\"independence\": \"单一小红书笔记，无交叉来源；仅卡片级元数据可用。\", \"quality_density\": \"低——只有标题与点赞/评论数，无正文论据，标题为口号式框架，缺乏可证伪细节。\", \"recency\": \"无明确发布时间戳，主题（远程作战/战争形态演变）属快变领域，时效性无法确认。\"}", "debate_trace": null, "credibility_id": "cred-63ee9977c671", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-