INSERT INTO "knowledge_change_log" VALUES(532,'l3_claim','sc-92cca377a81c','*','update','{"id": "sc-92cca377a81c", "facet": null, "proposition": "普京称基辅将因库尔斯克地区的行动付出代价——以丧失俄方建立安全缓冲区所需的领土为代价,并明确表示俄罗斯无意''拯救''基辅政权。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-92cca377a81c", "source_ref_ids": "[\"src-92cca377a81c\"]", "verbatim_excerpt": "Putin: Kiev will pay for its actions in the Kursk region by losing territory needed for a security buffer zone. Saving the Kiev government is not part of Russia''s plans.", "cached_text_hash": "0b97e2c53fd776469d193c70e0c2b1ac93a48ea730cb75a29ffbb4350955634e", "analysis_note": "这是由亲俄聚合账号转述的普京公开表态:一是提出以乌克兰领土建立''安全缓冲区''的领土诉求,二是声明不以更迭基辅政权为目标。属威慑性政治宣示,非已发生的既成事实。", "filter_trace": "{\"independence\": \"单一信源(@RussiaNews / mog_russEN),为亲俄聚合账号,未见独立主流信源交叉印证。\", \"quality_density\": \"为带具体主张的直接引语(缓冲区+政权议题),信息密度尚可,但属威慑修辞而非可验证事实。\", \"recency\": \"当前热点战事相关,时点新鲜。\"}", "debate_trace": null, "credibility_id": "cred-8ca970e5fd52", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-92cca377a81c", "facet": null, "proposition": "普京称基辅将因库尔斯克地区的行动付出代价——以丧失俄方建立安全缓冲区所需的领土为代价,并明确表示俄罗斯无意''拯救''基辅政权。", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-92cca377a81c", "source_ref_ids": "[\"src-92cca377a81c\"]", "verbatim_excerpt": "Putin: Kiev will pay for its actions in the Kursk region by losing territory needed for a security buffer zone. Saving the Kiev government is not part of Russia''s plans.", "cached_text_hash": "0b97e2c53fd776469d193c70e0c2b1ac93a48ea730cb75a29ffbb4350955634e", "analysis_note": "这是由亲俄聚合账号转述的普京公开表态:一是提出以乌克兰领土建立''安全缓冲区''的领土诉求,二是声明不以更迭基辅政权为目标。属威慑性政治宣示,非已发生的既成事实。", "filter_trace": "{\"independence\": \"单一信源(@RussiaNews / mog_russEN),为亲俄聚合账号,未见独立主流信源交叉印证。\", \"quality_density\": \"为带具体主张的直接引语(缓冲区+政权议题),信息密度尚可,但属威慑修辞而非可验证事实。\", \"recency\": \"当前热点战事相关,时点新鲜。\"}", "debate_trace": null, "credibility_id": "cred-b650a05e3b56", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=breaking facet=None','condense-distill','2026-06-29 13:07:45',NULL);
