INSERT INTO "knowledge_change_log" VALUES(555,'l3_claim','sc-cf81acaeb25d','*','update','{"id": "sc-cf81acaeb25d", "facet": null, "proposition": "ISW 在 2026 年 6 月的每日评估中判断:俄军持续扩大对乌克兰哈尔科夫州的 FPV(第一视角)无人机打击、乌方防御承压,并于 6 月 20-21 日夜间对乌发动一轮远程无人机与导弹打击;同时俄白正为俄军从白俄罗斯领土发起无人机打击创造条件,库尔斯克仍是重要跨境战线。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-cf81acaeb25d", "source_ref_ids": "[\"src-cf81acaeb25d\"]", "verbatim_excerpt": "乌当局正努力保护哈尔科夫州免受俄不断扩大的FPV(第一视角)无人机打击……俄白正设置条件为俄从白俄罗斯领土向乌发动无人机打击制造理由。", "cached_text_hash": "56b518acab62c54b2268ea69a995db26fc32327ab5063d5511dcb99465b84122", "analysis_note": "该原文是 ISW 单日战场评估的概要,串联了哈尔科夫 FPV 无人机压力、远程打击、白俄罗斯潜在打击矢量与库尔斯克战线四条线索,核心是『俄军进攻压力持续并可能在扩大打击维度』这一分析判断,而非单一可证伪事实。", "filter_trace": "{\"independence\": \"单源(ISW 自身评估),无本 payload 内的第三方印证。\", \"quality_density\": \"高:具体到哈尔科夫州、FPV 无人机、6 月 20-21 夜远程打击、白俄罗斯矢量、库尔斯克战线。\", \"recency\": \"时效新(2026 年 6 月,接近今日 2026-06-29),对快变地缘主题有效;但内嵌的『5 月 26 日评估』为较旧判断点。\"}", "debate_trace": null, "credibility_id": "cred-10636d475d24", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-cf81acaeb25d", "facet": null, "proposition": "ISW 在 2026 年 6 月的每日评估中判断:俄军持续扩大对乌克兰哈尔科夫州的 FPV(第一视角)无人机打击、乌方防御承压,并于 6 月 20-21 日夜间对乌发动一轮远程无人机与导弹打击;同时俄白正为俄军从白俄罗斯领土发起无人机打击创造条件,库尔斯克仍是重要跨境战线。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-cf81acaeb25d", "source_ref_ids": "[\"src-cf81acaeb25d\"]", "verbatim_excerpt": "乌当局正努力保护哈尔科夫州免受俄不断扩大的FPV(第一视角)无人机打击……俄白正设置条件为俄从白俄罗斯领土向乌发动无人机打击制造理由。", "cached_text_hash": "56b518acab62c54b2268ea69a995db26fc32327ab5063d5511dcb99465b84122", "analysis_note": "该原文是 ISW 单日战场评估的概要,串联了哈尔科夫 FPV 无人机压力、远程打击、白俄罗斯潜在打击矢量与库尔斯克战线四条线索,核心是『俄军进攻压力持续并可能在扩大打击维度』这一分析判断,而非单一可证伪事实。", "filter_trace": "{\"independence\": \"单源(ISW 自身评估),无本 payload 内的第三方印证。\", \"quality_density\": \"高:具体到哈尔科夫州、FPV 无人机、6 月 20-21 夜远程打击、白俄罗斯矢量、库尔斯克战线。\", \"recency\": \"时效新(2026 年 6 月,接近今日 2026-06-29),对快变地缘主题有效;但内嵌的『5 月 26 日评估』为较旧判断点。\"}", "debate_trace": null, "credibility_id": "cred-5d24a739e6f5", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(556,'l3_claim','sc-d1ce88d68a88','*','update','{"id": "sc-d1ce88d68a88", "facet": null, "proposition": "据该笔记标题，乌克兰发动了一夜内最大规模的无人机袭击，出动约370架无人机（攻击方向与目标未在正文展开，存在歧义）", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-d1ce88d68a88", "source_ref_ids": "[\"src-d1ce88d68a88\"]", "verbatim_excerpt": "370架！乌克兰一夜最大规模无人机袭击", "cached_text_hash": "6a450f6ce99ffe1b9962b97ef18830418227dd60ae67c8a975a130aa800df882", "analysis_note": "卡片级证据：正文未抓取，仅有标题与互动数据可读。「乌克兰…无人机袭击」在中文标题里方向略有歧义（乌克兰发起 / 针对乌克兰），因无正文佐证无法确定，需后续印证。", "filter_trace": "{\"independence\": \"单一平台、单一聚合账号（@数字拾光者）转载，未见其他独立来源\", \"quality_density\": \"仅标题可得，无正文；''370架''''最大规模''为可证伪的具体数字，但缺乏支撑细节\", \"recency\": \"地缘军事快变主题，单次袭击事件时效衰减快\"}", "debate_trace": null, "credibility_id": "cred-c4782af7c7ed", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-d1ce88d68a88", "facet": null, "proposition": "据该笔记标题，乌克兰发动了一夜内最大规模的无人机袭击，出动约370架无人机（攻击方向与目标未在正文展开，存在歧义）", "claim_kind": "breaking", "source_kind": "post", "single_source_ref_id": "src-d1ce88d68a88", "source_ref_ids": "[\"src-d1ce88d68a88\"]", "verbatim_excerpt": "370架！乌克兰一夜最大规模无人机袭击", "cached_text_hash": "6a450f6ce99ffe1b9962b97ef18830418227dd60ae67c8a975a130aa800df882", "analysis_note": "卡片级证据：正文未抓取，仅有标题与互动数据可读。「乌克兰…无人机袭击」在中文标题里方向略有歧义（乌克兰发起 / 针对乌克兰），因无正文佐证无法确定，需后续印证。", "filter_trace": "{\"independence\": \"单一平台、单一聚合账号（@数字拾光者）转载，未见其他独立来源\", \"quality_density\": \"仅标题可得，无正文；''370架''''最大规模''为可证伪的具体数字，但缺乏支撑细节\", \"recency\": \"地缘军事快变主题，单次袭击事件时效衰减快\"}", "debate_trace": null, "credibility_id": "cred-43b5707ece36", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:48:07", "updated_at": "2026-06-29 13