INSERT INTO "knowledge_change_log" VALUES(560,'l3_claim','sc-dbc73395ef8a','*','update','{"id": "sc-dbc73395ef8a", "facet": null, "proposition": "俄乌战争自2022年2月24日俄罗斯三线全面入侵以来，呈现阶段性拉锯：乌军在基辅与哈尔科夫两度成功反攻，俄军则在马里乌波尔、巴赫穆特等围城/血腥消耗战中夺地，而乌军2023夏季反攻受阻于俄军防线、2024年8月反向突袭库尔斯克——总体是双方互有攻守、缺乏决定性突破的长期消耗战。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-dbc73395ef8a", "source_ref_ids": "[\"src-dbc73395ef8a\"]", "verbatim_excerpt": "2022年2月24日俄罗斯从白俄罗斯、俄罗斯本土、克里米亚三线发动全面入侵，为二战以来欧洲最大军事行动。", "cached_text_hash": "14811c1dd302c3aa15c8631d46554224f262a2bef3f0aa85f8ddb0f7bf1780bc", "analysis_note": "Britannica 概览提供的是战争阶段的结构性骨架（六个阶段、关键战役、时间线），适合作为该主题 L0 世界模型的时间轴底座，后续 L2/L1 可挂接各阶段的更细来源。", "filter_trace": "{\"independence\": \"权威第三方百科，独立于交战双方任一方宣传口径\", \"quality_density\": \"高密度：六个阶段、具体日期、地名、兵力/面积数据，可证伪\", \"recency\": \"概览性时间线截至2024年8月库尔斯克突袭，地缘快变主题需后续来源补充最新态势\"}", "debate_trace": null, "credibility_id": "cred-c5bdc1ac4106", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:40:37", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-dbc73395ef8a", "facet": null, "proposition": "俄乌战争自2022年2月24日俄罗斯三线全面入侵以来，呈现阶段性拉锯：乌军在基辅与哈尔科夫两度成功反攻，俄军则在马里乌波尔、巴赫穆特等围城/血腥消耗战中夺地，而乌军2023夏季反攻受阻于俄军防线、2024年8月反向突袭库尔斯克——总体是双方互有攻守、缺乏决定性突破的长期消耗战。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-dbc73395ef8a", "source_ref_ids": "[\"src-dbc73395ef8a\"]", "verbatim_excerpt": "2022年2月24日俄罗斯从白俄罗斯、俄罗斯本土、克里米亚三线发动全面入侵，为二战以来欧洲最大军事行动。", "cached_text_hash": "14811c1dd302c3aa15c8631d46554224f262a2bef3f0aa85f8ddb0f7bf1780bc", "analysis_note": "Britannica 概览提供的是战争阶段的结构性骨架（六个阶段、关键战役、时间线），适合作为该主题 L0 世界模型的时间轴底座，后续 L2/L1 可挂接各阶段的更细来源。", "filter_trace": "{\"independence\": \"权威第三方百科，独立于交战双方任一方宣传口径\", \"quality_density\": \"高密度：六个阶段、具体日期、地名、兵力/面积数据，可证伪\", \"recency\": \"概览性时间线截至2024年8月库尔斯克突袭，地缘快变主题需后续来源补充最新态势\"}", "debate_trace": null, "credibility_id": "cred-d7194f2c3b06", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 12:40:37", "updated_at": "2026-06-29 13:07:45", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-06-29 13:07:45',NULL);
INSERT INTO "knowledge_change_log" VALUES(561,'l3_claim','sc-dbe9c95547e7','*','update','{"id": "sc-dbe9c95547e7", "facet": null, "proposition": "一条小红书热门笔记(约5千赞、800+评论)以「在乌克兰的女孩」第一人称视角呈现其个人眼中的乌克兰现状,提供了当事人主观体验侧的民间视角;正文按风控策略未抓取(仅卡片级证据)。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-dbe9c95547e7", "source_ref_ids": "[\"src-dbe9c95547e7\"]", "verbatim_excerpt": "一个乌克兰女孩视角下的乌克兰现状(点赞5046 评论822)", "cached_text_hash": "08a765c4970806ab8091ec794f53895e577509cd1ad04faca96c1d7b49a9eaee", "analysis_note": "卡片级证据:仅留存标题/作者/互动数与xsec_token,正文未抓取。因此只能蒸馏出该笔记的「定位/框架」——当事人主观视角的民间表达——而无法对其正文内的具体事实主张做可信度判断。高互动数反映传播热度,不代表信息密度或独立性。", "filter_trace": "{\"independence\": \"单一小红书个人账号,无独立来源;高赞/高评论属传播热度而非独立性\", \"quality_density\": \"正文缺失,仅卡片元数据,信息密度低,无可证伪的具体细节\", \"recency\": \"标注为「现状」类内容,但无发布时间戳,时效性无法确认\"}", "debate_trace": null, "credibility_id": "cred-efc70a5ed875", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 11:28:29", "updated_at": "2026-06-29 12:40:37", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-dbe9c95547e7", "facet": null, "proposition": "一条小红书热门笔记(约5千赞、800+评论)以「在乌克兰的女孩」第一人称视角呈现其个人眼中的乌克兰现状,提供了当事人主观体验侧的民间视角;正文按风控策略未抓取(仅卡片级证据)。", "claim_kind": "opinion", "source_kind": "post", "single_source_ref_id": "src-dbe9c95547e7", "source_ref_ids": "[\"src-dbe9c95547e7\"]", "verbatim_excerpt": "一个乌克兰女孩视角下的乌克兰现状(点赞5046 评论822)", "cached_text_hash": "08a765c4970806ab8091ec794f53895e577509cd1ad04faca96c1d7b49a9eaee", "analysis_note": "卡片级证据:仅留存标题/作者/互动数与xsec_token,正文未抓取。因此只能蒸馏出该笔记的「定位/框架」——当事人主观视角的民间表达——而无法对其正文内的具体事实主张做可信度判断。高互动数反映传播热度,不代表信息密度或独立性。", "filter_trace": "{\"independence\": \"单一小红书个人账号,无独立来源;高赞/高评论属传播热度而非独立性\", \"quality_density\": \"正文缺失,仅卡片元数据,信息密度低,无可证伪的具体细节\", \"recency\": \"标注为「现状」类内容,但无发布时间戳,时效性无法确认\"}", "debate_trace": null, "credibility_id": "cred-d52a2966fac0", "parent_l2_id": null, "lifecycle": null, "status": "activ