INSERT INTO "knowledge_change_log" VALUES(625,'l2_finding','sf-19f3b3eb27c1','*','update','{"id": "sf-19f3b3eb27c1", "facet": "_unfileted", "finding_type": "claim", "statement": "俄罗斯战时经济的韧性/可持续性存在直接分歧：一方（Adam Tooze）定性为油气收入停滞、制裁累积下的结构性脆弱『纸牌屋』；另一方认为 Q1 GDP 仅微缩 0.2%、今年仍将增长约 1%，Kiel『结构性枯竭』之说被指误导，甚至有观点称俄在制裁下越来越富。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 3, "cross_platform_count": 3, "corroboration_sources": "[\"web\", \"x\", \"xiaohongshu\"]", "conflict_note": "sc-3fdc904ca23a（web，结构性脆弱）与 sc-02c2a9805a91（x，经济未崩、仍增长）就同一对象给出相反评估，构成核心张力；sc-3d42acbf1ed2（小红书标题级『越来越富』）方向一致但仅卡片级、不可核验，权重低。保留矛盾不抹平。", "source_ref_ids": "[\"src-3fdc904ca23a\", \"src-02c2a9805a91\", \"src-3d42acbf1ed2\"]", "credibility_id": "cred-4e9425d9aa1d", "l3_ids": "[\"sc-3fdc904ca23a\", \"sc-02c2a9805a91\", \"sc-3d42acbf1ed2\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:10:29", "updated_at": "2026-06-29 13:10:29", "updated_by": "condense-aggregate", "audit_note": null}','{"id": "sf-19f3b3eb27c1", "facet": "_unfileted", "finding_type": "claim", "statement": "俄罗斯战时经济的韧性/可持续性存在直接分歧：一方（Adam Tooze）定性为油气收入停滞、制裁累积下的结构性脆弱『纸牌屋』；另一方认为 Q1 GDP 仅微缩 0.2%、今年仍将增长约 1%，Kiel『结构性枯竭』之说被指误导，甚至有观点称俄在制裁下越来越富。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 3, "cross_platform_count": 3, "corroboration_sources": "[\"web\", \"x\", \"xiaohongshu\"]", "conflict_note": "sc-3fdc904ca23a（web，结构性脆弱）与 sc-02c2a9805a91（x，经济未崩、仍增长）就同一对象给出相反评估，构成核心张力；sc-3d42acbf1ed2（小红书标题级『越来越富』）方向一致但仅卡片级、不可核验，权重低。保留矛盾不抹平。", "source_ref_ids": "[\"src-3fdc904ca23a\", \"src-02c2a9805a91\", \"src-3d42acbf1ed2\"]", "credibility_id": "cred-0fef53118f4f", "l3_ids": "[\"sc-3fdc904ca23a\", \"sc-02c2a9805a91\", \"sc-3d42acbf1ed2\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": n