INSERT INTO "knowledge_change_log" VALUES(626,'l2_finding','sf-c913e02f2920','*','update','{"id": "sf-c913e02f2920", "facet": "_unfileted", "finding_type": "event", "statement": "美国主导的乌克兰和平方案要求基辅作出领土让步：2025 年 11 月 28 点方案要求东部割地、限制乌军规模、禁止入约（不限武器装备），CSIS 评其『亲俄且模糊』、AP 称将割地予俄；2025 年 12 月草案进一步要求冻结赫尔松/扎波罗热前线并自顿涅茨克部分撤出，泽连斯基提反提案并承认顿巴斯为『最困难一点』，特朗普方称柏林会谈后约 90% 问题已解决。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 2, "cross_platform_count": 1, "corroboration_sources": "[\"web\"]", "conflict_note": null, "source_ref_ids": "[\"src-2df254c71e7d\", \"src-334cc1ca247f\"]", "credibility_id": "cred-d8a270ea31d4", "l3_ids": "[\"sc-2df254c71e7d\", \"sc-334cc1ca247f\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:10:29", "updated_at": "2026-06-29 13:10:29", "updated_by": "condense-aggregate", "audit_note": null}','{"id": "sf-c913e02f2920", "facet": "_unfileted", "finding_type": "event", "statement": "美国主导的乌克兰和平方案要求基辅作出领土让步：2025 年 11 月 28 点方案要求东部割地、限制乌军规模、禁止入约（不限武器装备），CSIS 评其『亲俄且模糊』、AP 称将割地予俄；2025 年 12 月草案进一步要求冻结赫尔松/扎波罗热前线并自顿涅茨克部分撤出，泽连斯基提反提案并承认顿巴斯为『最困难一点』，特朗普方称柏林会谈后约 90% 问题已解决。", "value_text": null, "value_num": null, "unit": null, "valid_from": null, "valid_to": null, "corroboration_count": 2, "cross_platform_count": 1, "corroboration_sources": "[\"web\"]", "conflict_note": null, "source_ref_ids": "[\"src-2df254c71e7d\", \"src-334cc1ca247f\"]", "credibility_id": "cred-df6315ea9358", "l3_ids": "[\"sc-2df254c71e7d\", \"sc-334cc1ca247f\"]", "parent_l1_id": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:10:29", "updated_at": "2026-06-29 13:16:00", "updated_by": "condense-aggregate", "audit_note": null}','type=event corrob=2/1','condense-aggregate','2026-06-29 13:16:00',NULL);
