INSERT INTO "knowledge_change_log" VALUES(678,'l1_viewpoint','vp-9621ff7013ac','*','update','{"id": "vp-9621ff7013ac", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "俄战时经济呈现『韧性 vs 结构性脆弱』的真实张力，且证据跨平台分布。承压侧：2025年西方能源制裁致俄石油收入同比降约20%、乌拉尔原油对布伦特折价扩至每桶逾24美元、影子舰队承压(sf-65fcae87d5e1/sf-23e7ae404212)；Urals在波罗的海/黑海港约$50/桶较前跌约50%、卢布走弱仅部分对冲(sf-c25e9096d56b/sf-addfd9dccd21)；2025国防预算约15.5万亿卢布(占GDP约7.2%)、央行紧缩抗通胀、动员与外流致劳动力短缺、世行下调增速(sf-08d37cf2d5b6)；2026军费下调被智库定性为『非胜利/受控停滞』、普京承认能源紧张与加油站排队、莫斯科约四成汽油断供(sf-22b41160809b/sf-13fb8f5483ad)。韧性侧：有观点称Q1 GDP仅微缩0.2%、今年仍增长约1%、Kiel『结构耗竭』论被指夸大、Adam Tooze的『纸牌屋』定性遭反驳(sf-b98ecb1db8a1/sf-19f3b3eb27c1)；中文社媒以『未崩溃/进口替代』叙事(国产药占比63%—86%、为何未崩溃高互动设问)同向佐证(sf-fe75d70665b0/sf-5d0643752e7b/sf-ff308e01246e/sf-4ac6b4238528)。两侧均未被权威2026财年财政/通胀/劳动力数据裁决——这正是核心未决点，且韧性侧多源系回音室式重复设问，不能压过承压侧的硬数据。", "stance": "contested", "l2_ids": "[\"sf-65fcae87d5e1\", \"sf-23e7ae404212\", \"sf-c25e9096d56b\", \"sf-addfd9dccd21\", \"sf-08d37cf2d5b6\", \"sf-22b41160809b\", \"sf-13fb8f5483ad\", \"sf-b98ecb1db8a1\", \"sf-19f3b3eb27c1\", \"sf-fe75d70665b0\", \"sf-5d0643752e7b\", \"sf-ff308e01246e\", \"sf-4ac6b4238528\", \"sf-b79c61587bab\"]", "open_questions": "[\"俄2026财年权威财政/通胀/劳动力数据能否裁决『受控停滞』与『仍可支撑战争』之争\"]", "confidence": "medium", "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\", \"src-bdb72a69a328\", \"src-f86f0a02b7bb\", \"src-f26d039d177f\", \"src-57716a69cc86\", \"src-892677e1d3e1\", \"src-7e38f8f1c038\", \"src-8e691f9c959f\", \"src-5ced799861a4\", \"src-7434fb7500ab\", \"src-f89329c832ec\", \"src-fbe09c63a68a\", \"src-02c2a9805a91\", \"src-3fdc904ca23a\", \"src-3d42acbf1ed2\", \"src-b0f6d13376c6\", \"src-c3589354aae9\", \"src-d4fd7651d27d\"]", "credibility_id": "cred-49bfa069460e", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated