INSERT INTO "knowledge_change_log" VALUES(679,'l1_viewpoint','vp-220f1a485a0b','*','update','{"id": "vp-220f1a485a0b", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "无人机已成为重塑战场形态的主导变量，证据较强且跨平台。乌新一代中程无人机正瓦解俄南部后勤补给线，交战转向无人机覆盖的『灰色地带』取代传统前线、机动致命、士兵几无藏身之处(sf-07d94e42e19d/sf-fbe82e31e497)。乌方实战部署具名系统：美制GBU-39/B SDB空袭前线俄阵地、搭载M2勃朗宁的『Sky Sentinel』遥控炮塔反Shahed/Geran(sf-a7f7e24ba7f5/sf-ccc25f6be903/sf-59a5550c057f)，但反无人机系统效能尚需实战验证、自身易受攻击、自动化有误伤风险。攻防持续升级，出现被报道为单夜约370架的大规模袭击及对莫斯科的袭击(sf-848488e3bebb/sf-29c6fb7c6d01)。战线正向白俄罗斯外溢：ISW评估俄白为自白领土发起无人机打击创造条件、库尔斯克仍是重要跨境战线，乌于6月26日警告白俄拆除乌白边境无人机通信站(sf-cb2a52790a3b/sf-f6ab1441fceb)。多数具体战果(如20380护卫舰被击中、370架规模)缺独立可核验细节，属叙事印证而非已证实事实。", "stance": "established", "l2_ids": "[\"sf-07d94e42e19d\", \"sf-fbe82e31e497\", \"sf-a7f7e24ba7f5\", \"sf-ccc25f6be903\", \"sf-59a5550c057f\", \"sf-848488e3bebb\", \"sf-29c6fb7c6d01\", \"sf-80c198f56176\", \"sf-cb2a52790a3b\", \"sf-f6ab1441fceb\", \"sf-914806b2fbdd\", \"sf-bd4f48c03301\", \"sf-32097d12a1a8\"]", "open_questions": "[\"大规模无人机袭击与反无人机系统的实战战果需独立可核验细节\", \"白俄罗斯作为发射阵地的战线升级是否实质落地\"]", "confidence": "medium", "source_ref_ids": "[\"src-144db63a9d52\", \"src-326d91c55f3a\", \"src-2e92529ce93e\", \"src-2f3f0e2fad11\", \"src-29df650e0cd9\", \"src-190ce3895a76\", \"src-4e893ca84bd7\", \"src-4f82a42b4c15\", \"src-93f49315a162\", \"src-d1ce88d68a88\", \"src-90ce42415df6\", \"src-cf81acaeb25d\", \"src-bab169626f4f\", \"src-ad1ae14d84e0\", \"src-b908e3a355f3\"]", "credibility_id": "cred-8e6b8da3b102", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-220f1a485a0b", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "theme", "narrative": "无人机已成为重塑战场形态的主导变量，证据较强且跨平台。乌新一代中程无人机正瓦解俄南部后勤补给线，交战转向无人机覆盖的『灰色地带』取代传统前线