INSERT INTO "knowledge_change_log" VALUES(680,'l1_viewpoint','vp-6a2be86711f6','*','update','{"id": "vp-6a2be86711f6", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "停火/谈判轨道活跃但未突破，且以乌方领土让步为主轴。2025年4–6月两轮伊斯坦布尔谈判仅达成战俘交换；俄6月备忘录提供两种30天停火方案，据Chatham House其一要求乌正式放弃入北约、领土上无北约军事存在(sf-ba4f38adf1c9/sf-27e314c35b41)；俄并提议互限对纵深目标打击、普京据报正考虑相互停止远程打击(sf-f5dc0c68c5a7/sf-11037776b763/sf-bee4ded1202b)。美方主导方案要求基辅割地：2025年11月28点方案要求东部割地、限军、禁入约(不限武装)，CSIS评『亲俄且模糊』；12月草案要求冻结赫尔松/扎波罗热前线并自顿涅茨克部分撤出，泽连斯基提反提案、承认顿巴斯为最难点(sf-c1d0fde47d96/sf-c913e02f2920)。泽连斯基公开表示愿即刻直接谈判(sf-1c31243357ad)。普京以库尔斯克『罪行』为由公开主张乌须付出领土代价、夺地建『安全/缓冲区』(sf-3578433e194a/sf-8ac94dc562dc)。落地与执行可行性仍是核心未决点。", "stance": "emerging", "l2_ids": "[\"sf-ba4f38adf1c9\", \"sf-27e314c35b41\", \"sf-f5dc0c68c5a7\", \"sf-11037776b763\", \"sf-bee4ded1202b\", \"sf-c1d0fde47d96\", \"sf-c913e02f2920\", \"sf-1c31243357ad\", \"sf-3578433e194a\", \"sf-8ac94dc562dc\", \"sf-d92e74d66c77\", \"sf-b3853aaff153\"]", "open_questions": "[\"停火谈判(特朗普方案/俄备忘录后)能否真正落地及执行可行性\"]", "confidence": "medium", "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\", \"src-47d36b56c17f\", \"src-8d064e2faca7\", \"src-2df254c71e7d\", \"src-334cc1ca247f\", \"src-b73f9df2e14f\", \"src-03ffbc1d6338\", \"src-b69eba4f1b93\", \"src-457fc3be2e00\", \"src-92cca377a81c\", \"src-af2be8ea61e3\"]", "credibility_id": "cred-f28c5745ec07", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-6a2be86711f6", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "停火/谈判轨道活跃但未突破，且以乌方领土让步为主轴。2025年4–6月两轮伊斯坦布尔谈判仅达成战俘交换；俄6月备忘录提供两种30天停火方案，据Chatham House其一要求乌正式放弃入北约、领土上无北约军事存在(sf-ba4f38adf1c9/sf-27e314c35b41)；俄并提议互限对纵深目标打击、普京据报正考虑相互停止远程打击(sf-f5dc0c68c5a7/sf-11037776b763/sf-bee4ded1202b)。美方主导方案要求基辅割地：2025年11月28点方案要求东部割地、限军、禁入约(不限武装)，CSIS评『亲俄且模糊』；12月草案要求冻结赫尔松/扎波罗热前线并自顿涅茨克部分撤出，泽连斯基提反提案、承认顿巴斯为最难点(sf-c1d0fde47d96/sf-c913e02f2920)。泽连斯基公开表示愿即刻直接谈判(sf-1c31243357ad)。普京以库尔斯克『罪行』为由公开主张乌须付出领土代价、夺地建『安全/缓冲区』(sf-3578433e194a/sf-8ac94dc562dc)。落地与执行可行性仍是核心未决点。", "stance": "emerging", "l2_ids": "[\"sf-ba4f38adf1c9\", \"sf-27e314c35b41\", \"sf-f5dc0c68c5a7\", \"sf-11037776b763\", \"sf-bee4ded1202b\", \"sf-c1d0fde47d96\", \"sf-c913e02f2920\", \"sf-1c31243357ad\", \"sf-3578433e194a\", \"sf-8ac94dc562dc\", \"sf-d92e74d66c77\", \"sf-b3853aaff153\"]", "open_questions": "[\"停火谈判(特朗普方案/俄备忘录后)能否真正落地及执行可行性\"]", "confidence": "medium", "source_ref_ids": "[\"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598c1b723\", \"src-47d36b56c17f\", \"src-8d064e2faca7\", \"src-2df254c71e7d\", \"src-334cc1ca247f\", \"src-b73f9df2e14f\", \"src-03ffbc1d6338\", \"src-b69eba4f1b93\", \"src-457fc3be2e00\", \"src-92cca377a81c\", \"src-af2be8ea61e3\"]", "credibility_id": "cred-a73bdb864158", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:16:53", "updated_by": "condense-synthesize", "audit_note": null}','kind=sub_question stance=emerging','condense-synthesize','2026-06-29 13:16:53',NULL);
INSERT INTO "knowledge_change_log" VALUES(681,'l1_viewpoint','vp-6e07ac1395f2','*','update','{"id": "vp-6e07ac1395f2", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "存在与主流叙事相左的亲俄叙事，需保留张力而非抹平。一名X用户断言俄已占Kostyantynivka与Lyman、将包围Slovyansk/Kramatorsk进而控制整个顿巴斯，并指控西方主流媒体『乌以无人机攻势击败俄』报道系捏造(sf-404390f2702d/sf-d22f344fa9b8)。该叙事为单源、不可核验，与领土控制硬数据(俄控约19–20%、2025净夺取仅约0.72%全境、推进显著放缓)直接相悖，应作为对照信号保留而非采信。", "stance": "contested", "l2_ids": "[\"sf-404390f2702d\", \"sf-d22f344fa9b8\"]", "open_questions": "[\"顿巴斯具体战线归属需独立战场核验\"]", "confidence": "low", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "credibility_id": "cred-3861cb3916de", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-6e07ac1395f2", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "存在与主流叙事相左的亲俄叙事，需保留张力而非抹平。一名X用户断言俄已占Kostyantynivka与Lyman、将包围Slovyansk/Kramatorsk进而控制整个顿巴斯，并指控西方主流媒体『乌以无人机攻势击败俄』报道系捏造(sf-404390f2702d/sf-d22f344fa9b8)。该叙事为单源、不可核验，与领土控制硬数据(俄控约19–20%、2025净夺取仅约0.72%全境、推进显著放缓)直接相悖，应作为对照信号保留而非采信。", "stance": "contested", "l2_ids": "[\"sf-404390f2702d\", \"sf-d22f344fa9b8\"]", "open_questions": "[\"顿巴斯具体战线归属需独立战场核验\"]", "confidence": "low", "source_ref_ids": "[\"src-3a6bff93c0af\"]", "credibility_id": "cred-105390d47a17", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:16:53", "updated_by": "condense-synthesize", "audit_note": null}','kind=contrarian stance=contested','condense-synthesize','2026-06-29 13:16:53',NULL);
INSERT INTO "knowledge_change_log" VALUES(682,'l1_viewpoint','vp-8cc589214d4d','*','update','{"id": "vp-8cc589214d4d", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "viewpoint", "narrative": "乌克兰得以持续抵抗的核心支撑被综合为『西方援助+不对称(尤其无人机)作战』：web端梳理2022–24年欧盟及成员国逾1450亿美元援助、军援从便携系统升级至HIMARS/爱国者/F-16，叠加本土无人机创新(sf-ae3187333e8a)。但供应链存在断档脆弱性——F-16曾连续三周以上无法获得美制导弹致难以拦截俄无人机/导弹(sf-df6e40fd3e22/sf-066925673df9)；分析指出完全切断美军事与情报援助将严重削弱乌作战能力，兵力与可持续性是乌长期存续关键(sf-397589f9a840/sf-a171a4800aa7)。断档系临时波动还是结构性问题尚未裁定。", "stance": "established", "l2_ids": "[\"sf-ae3187333e8a\", \"sf-df6e40fd3e22\", \"sf-066925673df9\", \"sf-397589f9a840\", \"sf-a171a4800aa7\"]", "open_questions": "[\"西方军援供应链断档是临时波动还是结构性问题\"]", "confidence": "medium", "source_ref_ids": "[\"src-5e652caee352\", \"src-6b4af507be01\", \"src-804693cbd100\", \"src-43f57fedfa87\", \"src-c00527967443\"]", "credibility_id": "cred-3886a293de91", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-8cc589214d4d", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "viewpoint", "narrative": "乌克兰得以持续抵抗的核心支撑被综合为『西方援助+不对称(尤其无人机)作战』：web端梳理2022–24年欧盟及成员国逾1450亿美元援助、军援从便携系统升级至HIMARS/爱国者/F-16，叠加本土无人机创新(sf-ae3187333e8a)。但供应链存在断档脆弱性——F-16曾连续三周以上无法获得美制导弹致难以拦截俄无人机/导弹(sf-df6e40fd3e22/sf-066925673df9)；分析指出完全切断美军事与情报援助将严重削弱乌作战能力，兵力与可持续性是乌长期存续关键(sf-397589f9a840/sf-a171a4800aa7)。断档系临时波动还是结构性问题尚未裁定。", "stance": "established", "l2_ids": "[\"sf-ae3187333e8a\", \"sf-df6e40fd3e22\", \"sf-066925673df9\", \"sf-397589f9a840\", \"sf-a171a4800aa7\"]", "open_questions": "[\"西方军援供应链断档是临时波动还是结构性问题\"]", "confidence": "medium", "source_ref_ids": "[\"src-5e652caee352\", \"src-6b4af507be01\", \"src-804693cbd100\", \"src-43f57fedfa87\", \"src-c00527967443\"]", "credibility_id": "cred-73076678a846", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:16:53", "updated_by": "condense-synthesize", "audit_note": null}','kind=viewpoint stance=established','condense-synthesize','2026-06-29 13:16:53',NULL);
INSERT INTO "knowledge_change_log" VALUES(683,'l1_viewpoint','vp-0e9d9f060a22','*','update','{"id": "vp-0e9d9f060a22", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "中文社媒(小红书)对俄乌议题高关注但证据价值受限——大量笔记正文因风控未抓取，仅留卡片级元数据，构成覆盖度/抓取缺口而非可印证事实。议题包括为何乌能坚持、俄经济为何未崩溃、战争结局、在乌平民视角、制裁产品清单、跨境收汇等(sf-2937acd89a3b/sf-31bd1fa1e3b9/sf-6eca83623fcc/sf-eb9bf9fa56bb/sf-b2b7f1ca4f9d/sf-91e46a3b4cab/sf-5355827f2c0e/sf-77f0a6b01648)。其中以情绪化/悬念框架(『俄不希望你看到的数字』、士兵最后五分钟)及单源传闻(老金称单日3架米格-29被毁、普京称停火需中国担保)尤需警惕(sf-c76dde95a0f1/sf-57628fbe9225)。这些应作为线索留存、待补抓正文后再评估,不得据卡片标题蒸馏事实。", "stance": "uncertain", "l2_ids": "[\"sf-2937acd89a3b\", \"sf-31bd1fa1e3b9\", \"sf-6eca83623fcc\", \"sf-eb9bf9fa56bb\", \"sf-b2b7f1ca4f9d\", \"sf-91e46a3b4cab\", \"sf-5355827f2c0e\", \"sf-77f0a6b01648\", \"sf-c76dde95a0f1\", \"sf-57628fbe9225\"]", "open_questions": "[\"小红书卡片级笔记补抓正文后是否改变现有结论(覆盖度缺口)\"]", "confidence": "low", "source_ref_ids": "[\"src-4a3e59ac95a9\", \"src-617e73ef09a7\", \"src-8082b83893a3\", \"src-888c6708efbf\", \"src-97f3ed24f93d\", \"src-a9a0c49cc904\", \"src-aebc47f9e8d7\", \"src-db6b00712709\", \"src-b47ffe323751\", \"src-bb9fb7c33856\", \"src-dbe9c95547e7\", \"src-e07623d8e4a3\", \"src-3d2bd074f154\", \"src-de1c80d16df0\", \"src-819b761634f4\", \"src-1197f691f12d\", \"src-203e750d5c6f\", \"src-054ba6dc7d00\", \"src-2ed4b44997f4\", \"src-3406f384a8d2\", \"src-229fef399f44\", \"src-3fd6ca20c26e\", \"src-326d91c55f3a\", \"src-ea94b692a69d\", \"src-f8237ffa44ff\", \"src-baa2a4619ead\"]", "credibility_id": "cred-ecc421c4d24a", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-0e9d9f060a22", "facet": "_unfileted", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "contrarian", "narrative": "中文社媒(小红书)对俄乌议题高关注但证据价值受限——大量笔记正文因风控未抓取，仅留卡片级元数据，构成覆盖度/抓取缺口而非可印证事实。议题包括为何乌能坚持、俄经济为何未崩溃、战争结局、在乌平民视角、制裁产品清单、跨境收汇等(sf-2937acd89a3b/sf-31bd1fa1e3b9/sf-6eca83623fcc/sf-eb9bf9fa56bb/sf-b2b7f1ca4f9d/sf-91e46a3b4cab/sf-5355827f2c0e/sf-77f0a6b01648)。其中以情绪化/悬念框架(『俄不希望你看到的数字』、士兵最后五分钟)及单源传闻(老金称单日3架米格-29被毁、普京称停火需中国担保)尤需警惕(sf-c76dde95a0f1/sf-57628fbe9225)。这些应作为线索留存、待补抓正文后再评估,不得据卡片标题蒸馏事实。", "stance": "uncertain", "l2_ids": "[\"sf-2937acd89a3b\", \"sf-31bd1fa1e3b9\", \"sf-6eca83623fcc\", \"sf-eb9bf9fa56bb\", \"sf-b2b7f1ca4f9d\", \"sf-91e46a3b4cab\", \"sf-5355827f2c0e\", \"sf-77f0a6b01648\", \"sf-c76dde95a0f1\", \"sf-57628fbe9225\"]", "open_questions": "[\"小红书卡片级笔记补抓正文后是否改变现有结论(覆盖度缺口)\"]", "confidence": "low", "source_ref_ids": "[\"src-4a3e59ac95a9\", \"src-617e73ef09a7\", \"src-8082b83893a3\", \"src-888c6708efbf\", \"src-97f3ed24f93d\", \"src-a9a0c49cc904\", \"src-aebc47f9e8d7\", \"src-db6b00712709\", \"src-b47ffe323751\", \"src-bb9fb7c33856\", \"src-dbe9c95547e7\", \"src-e07623d8e4a3\", \"src-3d2bd074f154\", \"src-de1c80d16df0\", \"src-819b761634f4\", \"src-1197f691f12d\", \"src-203e750d5c6f\", \"src-054ba6dc7d00\", \"src-2ed4b44997f4\", \"src-3406f384a8d2\", \"src-229fef399f44\", \"src-3fd6ca20c26e\", \"src-326d91c55f3a\", \"src-ea94b692a69d\", \"src-f8237ffa44ff\", \"src-baa2a4619ead\"]", "credibility_id": "cred-9fd04c671d75", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:16:53", "updated_by": "condense-synthesize", "audit_note": null}','kind=contrarian stance=uncertain','condense-synthesize','2026-06-29 13:16:53',NULL);
INSERT INTO "knowledge_change_log" VALUES(684,'l1_viewpoint','vp-b23e12f61377','*','update','{"id": "vp-b23e12f61377", "facet": "f_territorial_control", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "领土控制呈『高位回落后趋稳、推进显著放缓』的清晰轨迹。俄控乌领土份额2022年春达峰值约25–27%，经哈尔科夫/赫尔松反攻回落，至2025秋–2026年2月稳定在约19–20%(含克里米亚)(sf-ff99d68abcf3/sf-efc1acae8503)。2025全年净夺取约4336(DeepState)至4831(ISW)平方公里、约占乌全境0.72%，2026年推进明显放缓(最近测量周期同比降约46%)(sf-c0a6015f18d2)。乌2024年8月库尔斯克攻势(约1.1万人)峰值控约1000平方公里俄领土,至2025初被俄反攻缩至约四分之一;由此形成的俄方小块缓冲区分量不足以充当迫使乌让出顿巴斯的谈判筹码(sf-7cf4444be95c/sf-42ad1ce61a98)。这与亲俄『已控整个顿巴斯』叙事直接相悖。", "stance": "established", "l2_ids": "[\"sf-c0a6015f18d2\", \"sf-ff99d68abcf3\", \"sf-efc1acae8503\", \"sf-7cf4444be95c\", \"sf-42ad1ce61a98\"]", "open_questions": "[\"顿巴斯关键城市(Kostyantynivka/Slovyansk/Kramatorsk)归属的最新核验\"]", "confidence": "high", "source_ref_ids": "[\"src-fc72351b7008\", \"src-a5385c09a477\", \"src-ad9cdb6444c8\", \"src-ab71ebaae693\"]", "credibility_id": "cred-aebd64c798f9", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:13:03", "updated_by": "condense-synthesize", "audit_note": null}','{"id": "vp-b23e12f61377", "facet": "f_territorial_control", "sub_question": null, "viewpoint_scope": null, "synthesis_kind": "sub_question", "narrative": "领土控制呈『高位回落后趋稳、推进显著放缓』的清晰轨迹。俄控乌领土份额2022年春达峰值约25–27%，经哈尔科夫/赫尔松反攻回落，至2025秋–2026年2月稳定在约19–20%(含克里米亚)(sf-ff99d68abcf3/sf-efc1acae8503)。2025全年净夺取约4336(DeepState)至4831(ISW)平方公里、约占乌全境0.72%，2026年推进明显放缓(最近测量周期同比降约46%)(sf-c0a6015f18d2)。乌2024年8月库尔斯克攻势(约1.1万人)峰值控约1000平方公里俄领土,至2025初被俄反攻缩至约四分之一;由此形成的俄方小块缓冲区分量不足以充当迫使乌让出顿巴斯的谈判筹码(sf-7cf4444be95c/sf-42ad1ce61a98)。这与亲俄『已控整个顿巴斯』叙事直接相悖。", "stance": "established", "l2_ids": "[\"sf-c0a6015f18d2\", \"sf-ff99d68abcf3\", \"sf-efc1acae8503\", \"sf-7cf4444be95c\", \"sf-42ad1ce61a98\"]", "open_questions": "[\"顿巴斯关键城市(Kostyantynivka/Slovyansk/Kramatorsk)归属的最新核验\"]", "confidence": "high", "source_ref_ids": "[\"src-fc72351b7008\", \"src-a5385c09a477\", \"src-ad9cdb6444c8\", \"src-ab71ebaae693\"]", "credibility_id": "cred-7e3db2aaa6f8", "parent_l0_id": null, "rank": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-06-29 13:13:03", "updated_at": "2026-06-29 13:16:53", "updated_by": "condense-synthesize", "audit_note": null}','kind=sub_question stance=established','condense-synthesize','2026-06-29 13:16:53',NULL);
INSERT INTO "knowledge_change_log" VALUES(685,'l0_worldview','wv-f47306bed0a5dbd4','*','update','{"id": "wv-f47306bed0a5dbd4", "summary_kind": "state_of_understanding", "proposition": "截至2026年中,俄乌战争进入『战线相对凝固、消耗与谈判并行』的阶段:俄控乌领土稳定在约19–20%且推进显著放缓(2025净夺取仅约全境0.72%),无人机已成为主导战场形态的不对称变量并向白俄罗斯外溢;乌克兰的持续抵抗高度依赖西方援助+本土无人机创新,而军援供应链(如F-16导弹)存在断档脆弱性。俄战时经济处于『韧性 vs 结构性脆弱』的真实张力中——制裁压低石油收入、燃料短缺与高军费可见,但尚无权威2026财年数据裁决其能否长期支撑战争。美方主导的和平方案与俄方备忘录均以乌领土让步为主轴、谈判轨道活跃但未突破,落地可行性存疑。中文社媒关注度高但多为正文缺失的卡片级线索,证据价值有限。", "scope": null, "key_findings": "[\"sf-c0a6015f18d2\", \"sf-22b41160809b\", \"sf-07d94e42e19d\", \"sf-fbe82e31e497\", \"sf-ba4f38adf1c9\", \"sf-c913e02f2920\", \"sf-ae3187333e8a\", \"sf-19f3b3eb27c1\", \"sf-f6ab1441fceb\"]", "open_questions": "[\"俄2026财年权威财政/通胀/劳动力数据能否裁决『受控停滞』与『仍可支撑战争』之争\", \"美方方案/俄备忘录后的停火谈判能否真正落地及执行可行性\", \"西方军援供应链断档是临时波动还是结构性问题\", \"大规模无人机袭击与反无人机系统的实战战果需独立可核验细节\", \"小红书卡片级笔记补抓正文后是否改变现有结论(覆盖度缺口)\"]", "confidence": "medium", "supersedes_id": "wv-c0422a20ed8fca08", "l1_ids": "[\"vp-9621ff7013ac\", \"vp-220f1a485a0b\", \"vp-6a2be86711f6\", \"vp-6e07ac1395f2\", \"vp-8cc589214d4d\", \"vp-0e9d9f060a22\", \"vp-b23e12f61377\"]", "source_ref_ids": "[\"src-04b976e998b7\", \"src-35b5b46bb66f\", \"src-41e03bc94a1d\", \"src-bdb72a69a328\", \"src-f86f0a02b7bb\", \"src-f26d039d177f\", \"src-57716a69cc86\", \"src-892677e1d3e1\", \"src-7e38f8f1c038\", \"src-8e691f9c959f\", \"src-5ced799861a4\", \"src-7434fb7500ab\", \"src-f89329c832ec\", \"src-fbe09c63a68a\", \"src-02c2a9805a91\", \"src-3fdc904ca23a\", \"src-3d42acbf1ed2\", \"src-b0f6d13376c6\", \"src-c3589354aae9\", \"src-d4fd7651d27d\", \"src-144db63a9d52\", \"src-326d91c55f3a\", \"src-2e92529ce93e\", \"src-2f3f0e2fad11\", \"src-29df650e0cd9\", \"src-190ce3895a76\", \"src-4e893ca84bd7\", \"src-4f82a42b4c15\", \"src-93f49315a162\", \"src-d1ce88d68a88\", \"src-90ce42415df6\", \"src-cf81acaeb25d\", \"src-bab169626f4f\", \"src-ad1ae14d84e0\", \"src-b908e3a355f3\", \"src-7bcb95db7c9e\", \"src-65378bb4a0ce\", \"src-88448fc33f10\", \"src-6a4598